const QUOTE_GROUP_BY_CAT_STORAGE_KEY = 'nts_quote_group_by_category_v1'
function loadSavedQuoteGroupMode(): boolean {
  try {
    const raw = localStorage.getItem(QUOTE_GROUP_BY_CAT_STORAGE_KEY)
    if (raw === '0' || raw === 'false') return false
    if (raw === '1' || raw === 'true') return true
  } catch {}
