    cardEdit.value.Don_vi_tien_te = nextCur
    if (nextCur === 'VND') {
      cardEdit.value.Ti_gia = 1
    }
  }
  syncCostMarkupFromPrices(cardCostMarkup, cardEdit.value.Gia_tieu_chuan, cardEdit.value.Don_gia)
