const importedTermsHtml = ref('')
const selectedTermId = ref('')
const editableTermContent = ref('')
const previewEditor = ref<any>(null)

watch(contractTerms, (list) => {
  if (!selectedTermId.value && list.length > 0) {
    const defaultTerm = list.find(t => {
      const m = (t.mau || '').toLowerCase()
      return m.includes('mặc định') || m.includes('mac dinh')
    }) || list[0]
    selectedTermId.value = defaultTerm.id
  } else if (selectedTermId.value && selectedTermId.value !== 'custom_import') {
    const term = list.find(t => t.id === selectedTermId.value)
    if (term && !editableTermContent.value.trim()) {
      editableTermContent.value = term.noiDung
    }
  }
}, { immediate: true })

watch(selectedTermId, (newId) => {
  if (isSwitchingQuoteTab.value) return
  if (newId === 'custom_import') {
    editableTermContent.value = importedTermsHtml.value
  } else if (newId) {
    const term = contractTerms.value.find(t => t.id === newId)
    editableTermContent.value = term ? term.noiDung : ''
  } else {
    editableTermContent.value = ''
  }
})

