/* datalist options */
const contractOptionsBySo = computed(() => {
  const set = new Set<string>()
  contractsRaw.value.forEach(r => {
    const so = String(r?.[1] ?? '').trim()
    if (so) set.add(so)
  })
  return Array.from(set).sort((a, b) => a.localeCompare(b))
})
const contractOptionsByMa = computed(() => {
  const set = new Set<string>()
  contractsRaw.value.forEach(r => {
    const ma = String(r?.[0] ?? '').trim()
    if (ma) set.add(ma)
  })
  return Array.from(set).sort((a, b) => a.localeCompare(b))
})

/* map 1 row hop_dong_chi_tiet -> item selectedItems */
function mapHopDongChiTietRowToItem(row: any[]) {
  // tolerate length
  // buildHopDongChiTietRows() của mày đang trả:
  // [0]ma_hop_dong [1]so_hop_dong [2]Ma_hang [3]Ten_hang [4]Main_img
  // [5]Ma_ncc [6]Ten_ncc [7]Mo_ta_chung [8]Mo_ta_chi_tiet [9]Features [10]Danh_muc
  // [11]License_duration [12]DVT [13]Gia_tieu_chuan [14]Don_gia [15]Don_vi_tien_te
  // [16]Ti_gia [17]Thue_VAT [18]So_luong [19]Ghi_chu
  const maHang = String(row?.[2] ?? '')
  const baseProduct =
    products.value.find(p => p.Ma_hang === maHang) ||
    products.value.find(p => p.Ma_hang && maHang.startsWith(p.Ma_hang + '-V'))

  const item: HangHoa & { So_luong: number } = {
    Ma_hang: maHang,
    Ten_hang: String(row?.[3] ?? ''),
    Main_img: String(row?.[4] ?? ''),
    Ma_nha_cung_cap: String(row?.[5] ?? ''),
    Ten_nha_cung_cap: String(row?.[6] ?? ''),
    Mo_ta_chung: String(row?.[7] ?? ''),
    Mo_ta_chi_tiet: String(row?.[8] ?? ''),
    Features: String(row?.[9] ?? ''),
    Danh_muc: String(row?.[10] ?? '').toUpperCase(),
    License_duration: String(row?.[11] ?? ''),
    DVT: String(row?.[12] ?? ''),
    Gia_tieu_chuan: toNum(row?.[13], 0),
    Don_gia: row?.[43] !== undefined && row?.[43] !== '' && toNum(row[43], 0) > 0 ? toNum(row[43], 0) : toNum(row?.[14], 0),
    Trang_thai: 'Hiển thị',
    Don_vi_tien_te: String(row?.[15] ?? 'VND'),
    Ti_gia: toNum(row?.[16], 1),
    Thue_VAT: toNum(row?.[17], 0),
    Ma_hang_lien_ket: '',
    Ten_hang_lien_ket: '',
    Ghi_chu: String(row?.[19] ?? ''),
    So_luong: Math.max(1, toNum(row?.[18], 1)),
    // ✅ 3 CỘT MỚI
    gia_hardware: toNum(row?.[20], 0),
    gia_nhap: toNum(row?.[21], 0),
    muc_phan_tram_off: toNum(row?.[22], 0),
    // ✅ snapshot giá gốc thực tế (Báo giá khách) & giá gốc kho (Báo giá gốc)
    _gia_hardware_goc: row?.[38] !== undefined && row?.[38] !== '' ? toNum(row[38], 0) : (baseProduct ? toNum(baseProduct.gia_hardware, 0) : toNum(row?.[20], 0)),
    _gia_nhap_goc: row?.[39] !== undefined && row?.[39] !== '' ? toNum(row[39], 0) : (baseProduct ? toNum(baseProduct.gia_nhap, 0) : toNum(row?.[21], 0)),
    _muc_phan_tram_off_goc: row?.[37] !== undefined && row?.[37] !== '' ? toNum(row[37], 0) : (baseProduct ? toNum(baseProduct.muc_phan_tram_off, 0) : toNum(row?.[22], 0)),
    _Don_gia_goc: row?.[47] !== undefined && row?.[47] !== '' && toNum(row[47], 0) > 0 ? toNum(row[47], 0) : (row?.[35] !== undefined && row?.[35] !== '' ? toNum(row[35], 0) : (baseProduct ? toNum(baseProduct.Don_gia, 0) : toNum(row?.[14], 0))),
    _Gia_tieu_chuan_goc: toNum(row?.[13], 0) > 0 ? toNum(row?.[13], 0) : (baseProduct ? toNum(baseProduct.Gia_tieu_chuan, 0) : 0),
    _Ti_gia_goc: baseProduct ? toNum(baseProduct.Ti_gia, 1) : toNum(row?.[16], 1),
    _Thue_VAT_goc: baseProduct ? toNum(baseProduct.Thue_VAT, 0) : toNum(row?.[17], 0),
    // ✅ snapshot giá kho gốc ban đầu (Báo giá gốc)
    _gia_hardware_kho: baseProduct ? toNum(baseProduct.gia_hardware, 0) : toNum(row?.[20], 0),
    _gia_nhap_kho: baseProduct ? toNum(baseProduct.gia_nhap, 0) : toNum(row?.[21], 0),
    _muc_phan_tram_off_kho: row?.[41] !== undefined && row?.[41] !== '' ? toNum(row[41], 0) : (baseProduct ? toNum(baseProduct.muc_phan_tram_off, 0) : toNum(row?.[22], 0)),
    _Don_gia_kho: row?.[40] !== undefined && row?.[40] !== '' && toNum(row[40], 0) > 0 ? toNum(row[40], 0) : (baseProduct ? toNum(baseProduct.Don_gia, 0) : toNum(row?.[14], 0)),
    _Gia_tieu_chuan_kho: toNum(row?.[13], 0) > 0 ? toNum(row?.[13], 0) : (baseProduct ? toNum(baseProduct.Gia_tieu_chuan, 0) : 0),
    _Ti_gia_kho: baseProduct ? toNum(baseProduct.Ti_gia, 1) : toNum(row?.[16], 1),
    _Thue_VAT_kho: baseProduct ? toNum(baseProduct.Thue_VAT, 0) : toNum(row?.[17], 0)
  } as any

  // ✅ Preserve start_date / end_date / thoi_han_bao_hanh / volume / Description / sku_code from indices 28-34
  item.start_date = String(row?.[28] ?? '')
  item.end_date = String(row?.[29] ?? '')
  ;(item as any).thoi_han_bao_hanh = String(row?.[31] ?? '')
  ;(item as any).volume = String(row?.[32] ?? '')
  ;(item as any).Description = String(row?.[33] || baseProduct?.Description || '')
  item.sku_code = String(row?.[34] || baseProduct?.sku_code || '')

  // ✅ Restore USD-based values if available (saved as VND with Ti_gia=1, but original USD data at index 24-27)
  const tiGiaUSD = toNum(row?.[24], 0)
  if (tiGiaUSD > 1) {
    item.Ti_gia = tiGiaUSD
    item.Don_gia = toNum(row?.[26], 0)          // Don_giaUS (giá USD hợp đồng)
    item.Gia_tieu_chuan = toNum(row?.[25], 0)   // Gia_tieu_chuanUSD (giá USD gốc)
    item.gia_nhap = toNum(row?.[27], 0)         // gia_nhapUSD (giá USD gốc)
    item.Don_vi_tien_te = 'USD'
    item._Ti_gia_goc = tiGiaUSD
    item._Gia_tieu_chuan_goc = item.Gia_tieu_chuan
    item._Ti_gia_kho = baseProduct ? toNum(baseProduct.Ti_gia, tiGiaUSD) : tiGiaUSD
    item._Gia_tieu_chuan_kho = item.Gia_tieu_chuan > 0 ? item.Gia_tieu_chuan : (baseProduct ? toNum(baseProduct.Gia_tieu_chuan, 0) : 0)
    if (row?.[36] !== undefined && row?.[36] !== '' && toNum(row[36], 0) > 0) {
      item._Don_gia_goc = toNum(row[36], item.Don_gia)
    } else if (row?.[47] !== undefined && row?.[47] !== '' && toNum(row[47], 0) > 0) {
      item._Don_gia_goc = toNum(row[47], 0) / tiGiaUSD
    } else if (row?.[35] !== undefined && row?.[35] !== '' && toNum(row[35], 0) > 0) {
      item._Don_gia_goc = toNum(row[35], 0) / tiGiaUSD
    } else if (!baseProduct) {
      item._Don_gia_goc = item.Don_gia
    }
    if (row?.[39] === undefined || row?.[39] === '') {
      item._gia_nhap_goc = baseProduct ? toNum(baseProduct.gia_nhap, item.gia_nhap) : item.gia_nhap
    }
    if (row?.[40] === undefined || row?.[40] === '' || toNum(row[40], 0) <= 0) {
      item._Don_gia_kho = baseProduct ? toNum(baseProduct.Don_gia, item.Don_gia) : item.Don_gia
    }
    if (!baseProduct) {
      item._gia_nhap_kho = item.gia_nhap
    }
  }

  return item
}

/* tìm row tổng quát theo số/mã */
function findContractRow() {
  const keyRaw = loadKey.value.trim()
  if (!keyRaw) return null
  // Xóa phần ngày tháng (vd: " - 14:30:00 14/05/2024" hoặc " - 14/05/2024") nếu có
  const key = keyRaw.replace(/\s*-\s*(?:\d{2}:\d{2}:\d{2}\s+)?\d{1,2}\/\d{1,2}\/\d{4}$/, '')
  
  if (loadMode.value === 'SO') {
    return contractsRaw.value.find(r => String(r?.[1] ?? '').trim() === key) || null
  }
  if (loadMode.value === 'PO') {
    return contractsRaw.value.find(r => String(r?.[22] ?? '').trim() === key) || null
  }
  return contractsRaw.value.find(r => String(r?.[0] ?? '').trim() === key) || null
}

function isContractRowOfficial(r: any[] | null | undefined): boolean {
  if (!r || !Array.isArray(r)) return false
  const status = String(r?.[15] ?? '').trim().toLowerCase()
  if (status === 'chính thức' || status === 'chinh thuc') return true
  if (r?.[33] === true || String(r?.[33] ?? '').toUpperCase() === 'TRUE') return true
  return false
}

const selectedLoadContractRow = computed(() => findContractRow())
const isSelectedLoadContractOfficial = computed(() => isContractRowOfficial(selectedLoadContractRow.value))

async function openLoadInvoiceModal() {
  loadSortBy.value = 'desc';
  loadStatusFilter.value = '';
  loadFromDate.value = '';
  loadToDate.value = '';
  loadSearchQuery.value = '';
  showLoadMobileDateFilter.value = false;
  showLoadInvoiceModal.value = true;
  invoiceListState.value = 'loading'
  try {
    const [hdRows, khList] = await Promise.all([
      fetchHopDongTongQuatFromFirebase(),
      fetchKhachHangFromFirebase()
    ]);
    contractsRaw.value = Array.isArray(hdRows) ? hdRows : [];
    customers.value = Array.isArray(khList) ? khList : [];
    markLoaded(invoiceListState)
  } catch (e) {
    console.error('Error fetching latest contracts for load modal:', e);
    invoiceListState.value = 'ready'
  }
}

function findExistingTabByContractRow(row: any, fallbackMa = ''): QuoteTabSession | undefined {
  snapshotCurrentStateToActiveTab()
  const ma = String(row?.[0] ?? fallbackMa ?? '').trim().toLowerCase()
  const so = String(row?.[1] ?? '').trim().toLowerCase()
  const maGoc = String(row?.[32] ?? '').trim().toLowerCase()

  return quoteTabs.value.find(t => {
    const tLoadedMa = String(t.loadedMaHopDong || '').trim().toLowerCase()
    const tLoadedGoc = String(t.loadedMaHopDongGoc || '').trim().toLowerCase()
    const tMa = String(t.maHopDong || '').trim().toLowerCase()
    const tSo = String(t.soHopDong || '').trim().toLowerCase()

    if (ma && (tLoadedMa === ma || tMa === ma || (tLoadedGoc && tLoadedGoc === ma))) {
      return true
    }
    if (maGoc && tLoadedMa && (tLoadedGoc === maGoc || tLoadedMa === maGoc)) {
      return true
    }
    if (so && tLoadedMa && tSo === so) {
      return true
    }
    return false
  })
}

async function loadInvoiceToFE() {
  loadMsg.value = ''
  const row = findContractRow()
  if (!row) {
    loadMsg.value = '❌ Không tìm thấy hóa đơn/hợp đồng theo mã/số đã chọn.'
    showAsyncError('Lỗi', 'Không tìm thấy hóa đơn/hợp đồng theo mã/số đã chọn.')
    return
  }

  if (isContractRowOfficial(row)) {
    loadMsg.value = '⚠️ PO chính thức chỉ cho phép Nhân bản, không cho phép chỉnh sửa.'
    showAsyncError('Không thể chỉnh sửa', 'PO chính thức đã chốt, chỉ cho phép Nhân bản.')
    return
  }

  const ma = String(row?.[0] ?? '').trim()
  const so = String(row?.[1] ?? '').trim()

  const existingTab = findExistingTabByContractRow(row, loadKey.value)
  if (existingTab) {
    if (existingTab.id !== activeQuoteTabId.value) {
      switchQuoteTab(existingTab.id)
    } else {
      scrollActiveTabIntoView()
    }
    flushQuoteTabsToStorageNow()
    showLoadInvoiceModal.value = false
    loadKey.value = ''
    if (window.innerWidth <= 1100) setMobileStep(2)
    const displayLabel = so || ma
    loadMsg.value = `✅ Đã chuyển tới tab đang mở hợp đồng ${displayLabel}.`
    triggerToast(`Đã chuyển tới tab đang mở hợp đồng ${displayLabel}`)
    return
  }

  try {
    loadingInvoice.value = true
    showAsyncLoading('Đang load hóa đơn...')

    await createNewQuoteTab({ silent: true, skipGenerateIds: true })

    loadedMaHopDong.value = ma              // ✅ GHI NHỚ HỢP ĐỒNG CŨ
    loadedMaHopDongGoc.value = String(row?.[32] ?? '').trim() || ma  // ✅ GHI NHỚ MÃ GỐC
    soHopDong.value = so || soHopDong.value // số hợp đồng GIỮ NGUYÊN
    currentPO.value = String(row?.[22] ?? '').trim() // ✅ Lấy Số PO từ index 22

    // ⚠️ KHÔNG dùng lại mã cũ
    maHopDong.value = genUniqueMaHopDong(activeQuoteTabId.value)

    // ghi chú (tolerant)
    ghiChuHopDong.value = String(row?.[16] ?? '').trim()
    contentOfContractPO.value = String(row?.[24] ?? '').trim()
    
    chietKhauTruocThuePct.value = toNum(row?.[26], 0)
    thueChenhLechPct.value = row?.[28] !== undefined && row?.[28] !== '' ? toNum(row?.[28], 25) : 25

    // ====== load data mapping structure ======
    try {
      const structStr = String(row?.[36] || '').trim()
      if (structStr && structStr.startsWith('[')) {
        excelMappingConfig.value = JSON.parse(structStr)
      }
    } catch (err) {
      console.warn('Cannot parse structure JSON from hop_dong_tong_quat', err)
    }

    // ====== load customer ======
    const maKH = String(row?.[2] ?? '').trim()
    if (maKH) {
      fillCustomerByMa(maKH) // sẽ set khach + maKHInput + tenKHInput
    } else {
      // fallback: set tên nếu có
      const tenKH = String(row?.[3] ?? '').trim()
      if (tenKH) fillCustomerByTen(tenKH)
    }

    // ====== load chi tiết ======
    const detailRows = await fetchHopDongChiTietFromFirebase()
    const all = Array.isArray(detailRows) ? detailRows : []
    const mine = all.filter((r: any[]) => String(r?.[0] ?? '').trim() === ma)

    // đổ vào selectedItems
    selectedItems.value = mine.map(mapHopDongChiTietRowToItem)

    // sync qtyMap (để card qty đúng nếu add tiếp)
    selectedItems.value.forEach(it => {
      if (it.Ma_hang) qtyMap[it.Ma_hang] = Math.max(1, toNum(it.So_luong, 1))
    })

    restoreCmpSrOverridesFromContractRow(row)

    syncFlatRows()
    flushQuoteTabsToStorageNow()
    scrollActiveTabIntoView()

    showLoadInvoiceModal.value = false
    loadKey.value = ''
    if (window.innerWidth <= 1100) setMobileStep(2)
    loadMsg.value = '✅ Đã load hóa đơn/hợp đồng lên FE.'
    showAsyncSuccess('Load thành công', 'Hóa đơn đã được mở ở tab mới.')
  } catch (e: any) {
    loadMsg.value = '❌ Lỗi load: ' + String(e?.message || e)
    showAsyncError('Load thất bại', String(e?.message || e))
  } finally {
    loadingInvoice.value = false
  }
}

const latestMaxPoFromDb = ref(0)

async function generateNewQuoteIds() {
  try {
    const [hdRows, poData] = await Promise.all([
      fetchHopDongTongQuatFromFirebase(),
      fetchPoDxmhFromFirebase()
    ])
    
    contractsRaw.value = Array.isArray(hdRows) ? hdRows : []

    let maxPO = 0
    if (Array.isArray(poData)) {
      poData.forEach((row: any) => {
        const soPo = parseInt(String(row[2] || '').replace(/\D/g, ''))
        if (!isNaN(soPo) && soPo > maxPO) maxPO = soPo
      })
    }
    latestMaxPoFromDb.value = maxPO

    const nextIds = computeNextLocalSoHopDongAndPO(activeQuoteTabId.value)
    soHopDong.value = nextIds.soHopDong
    currentPO.value = nextIds.currentPO
    flushQuoteTabsToStorageNow()
  } catch (e) {
    console.error('Lỗi khi tính toán số HĐ/PO mới:', e)
  }
}

async function cloneInvoiceToFE() {
  loadMsg.value = ''
  const row = findContractRow()
  if (!row) {
    loadMsg.value = '❌ Không tìm thấy hóa đơn/hợp đồng theo mã/số đã chọn.'
    showAsyncError('Lỗi', 'Không tìm thấy hóa đơn/hợp đồng theo mã/số đã chọn.')
    return
  }

  try {
    loadingInvoice.value = true
    showAsyncLoading('Đang nhân bản hàng hóa...')

    const ma = String(row?.[0] ?? '').trim()

    await createNewQuoteTab({ silent: true })

    // Load percentages
    chietKhauTruocThuePct.value = toNum(row?.[26], 0)
    thueChenhLechPct.value = row?.[28] !== undefined && row?.[28] !== '' ? toNum(row?.[28], 25) : 25

    // ====== load data mapping structure ======
    try {
      const structStr = String(row?.[36] || '').trim()
      if (structStr && structStr.startsWith('[')) {
        excelMappingConfig.value = JSON.parse(structStr)
      }
    } catch (err) {
      console.warn('Cannot parse structure JSON from hop_dong_tong_quat', err)
    }

    // clear customer info, notes, PO as requested
    resetCustomer()
    ghiChuHopDong.value = ''
    contentOfContractPO.value = ''
    loadedMaHopDong.value = null
    loadedMaHopDongGoc.value = null
    // do not clear currentPO because it was just generated

    // load chi tiết
    const detailRows = await fetchHopDongChiTietFromFirebase()
    const all = Array.isArray(detailRows) ? detailRows : []
    const mine = all.filter((r: any[]) => String(r?.[0] ?? '').trim() === ma)

    selectedItems.value = mine.map(mapHopDongChiTietRowToItem)

    selectedItems.value.forEach(it => {
      if (it.Ma_hang) qtyMap[it.Ma_hang] = Math.max(1, toNum(it.So_luong, 1))
    })

    restoreCmpSrOverridesFromContractRow(row)

    syncFlatRows()
    showLoadInvoiceModal.value = false
    loadKey.value = ''
    if (window.innerWidth <= 1100) setMobileStep(2)
    loadMsg.value = '✅ Đã nhân bản hàng hóa.'
    
    flushQuoteTabsToStorageNow()
    scrollActiveTabIntoView()
    if (route.query.ma || route.query.clone) {
      router.replace('/baogiafirebase')
    }
    
    showAsyncSuccess('Thành công', 'Đã đổ dữ liệu hàng hóa sang tab báo giá mới')
    triggerToast('Đã nhân bản hàng hóa sang tab mới!')
  } catch (e: any) {
    loadMsg.value = '❌ Lỗi nhân bản: ' + String(e?.message || e)
    showAsyncError('Nhân bản thất bại', String(e?.message || e))
  } finally {
    loadingInvoice.value = false
  }
}

// --- PIPELINE LOAD STATE ---
const LOAD_CARD_LAZY_BATCH_SIZE = 20
const showLoadPipelineModal = ref(false)
const poDxmhList = ref<any[]>([])
const loadPipelineFilter = ref('')
const loadingPipeline = ref(false)
const loadPipelineMsg = ref('')
const loadPipelineSearch = ref('')
const ctmhList = ref<any[]>([])
const hdChiTietList = ref<any[]>([])
const loadPipelineDisplayLimit = ref(LOAD_CARD_LAZY_BATCH_SIZE)
const pipelineLazySentinelRef = ref<HTMLElement | null>(null)
let pipelineLazyObserver: IntersectionObserver | null = null

const loadedPipelineExtraData = ref<any>(null)

watch(loadPipelineSearch, () => {
  loadPipelineDisplayLimit.value = LOAD_CARD_LAZY_BATCH_SIZE
})

const filteredPoDxmhRows = computed(() => {
  let list = [...poDxmhList.value].reverse()
  if (loadPipelineSearch.value) {
    const kw = loadPipelineSearch.value.trim().toLowerCase()
    list = list.filter(r => 
      String(r?.[2] ?? '').toLowerCase().includes(kw) || // so_po
      String(r?.[3] ?? '').toLowerCase().includes(kw) || // ten_po
      String(r?.[0] ?? '').toLowerCase().includes(kw) || // ma_hop_dong
      String(r?.[7] ?? '').toLowerCase().includes(kw)    // company
    )
  }
  return list
})

const filteredPoDxmhList = computed(() => {
  return filteredPoDxmhRows.value.slice(0, loadPipelineDisplayLimit.value).map(r => {
    const so_po = String(r?.[2] ?? '').trim()
    const so_hd = String(r?.[1] ?? '').trim()
    const maHD = String(r?.[0] ?? '').trim()
    
    // Tìm chi tiết mua hàng theo ma_hop_dong
    const items = ctmhList.value.filter((c: any[]) => 
      String(c?.[0] ?? '').trim() === maHD
    )
    
    // Map chi tiết: ten_hang_hoa[6], sl[9], list_price_usd[10]
    const hangHoaList = items.map(c => ({
      ten: String(c?.[6] ?? '').trim(),
      sl: String(c?.[9] ?? '').trim(),
      listPrice: String(c?.[10] ?? '').trim()
    })).filter(h => h.ten)

    // Tìm created_time từ hợp đồng tổng quát (index 4 = ngày tạo)
    const contract = contractsRaw.value.find((cr: any[]) => String(cr?.[0] ?? '').trim() === maHD)
    const createdTime = contract ? String(contract?.[4] ?? '').trim() : ''

    return {
      ma_hop_dong: maHD,
      so_hop_dong: so_hd,
      so_po: so_po,
      ten_po: String(r?.[3] ?? '').trim(),
      trang_thai: String(r?.[5] ?? '').trim(),
      company: String(r?.[7] ?? '').trim(),
      contact: String(r?.[11] ?? '').trim(),
      created_time: createdTime,
      hang_hoa_list: hangHoaList,
      raw: r
    }
  })
})

function loadMorePipelineCards() {
  if (loadPipelineDisplayLimit.value < filteredPoDxmhRows.value.length) {
    loadPipelineDisplayLimit.value += LOAD_CARD_LAZY_BATCH_SIZE
  }
}

function onLoadPipelineGridScroll(e: Event) {
  const el = e.target as HTMLElement | null
  if (!el) return
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 220) {
    loadMorePipelineCards()
  }
}

watch(pipelineLazySentinelRef, (sentinel) => {
  if (pipelineLazyObserver) {
    pipelineLazyObserver.disconnect()
    pipelineLazyObserver = null
  }
  if (sentinel && typeof IntersectionObserver !== 'undefined') {
    pipelineLazyObserver = new IntersectionObserver(
      (entries) => {
        if (entries.some(entry => entry.isIntersecting)) {
          loadMorePipelineCards()
        }
      },
      { rootMargin: '220px' }
    )
    pipelineLazyObserver.observe(sentinel)
  }
})

async function openLoadPipelineModal() {
  loadPipelineDisplayLimit.value = LOAD_CARD_LAZY_BATCH_SIZE
  showLoadPipelineModal.value = true
  loadPipelineMsg.value = ''
  pipelineListState.value = 'loading'
  try {
    const [poRows, ctmhRows, hdctRows] = await Promise.all([
      fetchPoDxmhFromFirebase(),
      fetchChiTietMuaHangFromFirebase(),
      fetchHopDongChiTietFromFirebase()
    ])
    poDxmhList.value = Array.isArray(poRows) ? poRows : []
    ctmhList.value = Array.isArray(ctmhRows) ? ctmhRows : []
    hdChiTietList.value = Array.isArray(hdctRows) ? hdctRows : []
    markLoaded(pipelineListState)
  } catch (e) {
    console.error('Error fetching POs:', e)
    pipelineListState.value = 'ready'
  }
}

async function loadPipelineToFE() {
  const kw = loadPipelineFilter.value.trim()
  if (!kw) return

  const keyRaw = kw.replace(/\s*-\s*(?:\d{2}:\d{2}:\d{2}\s+)?\d{1,2}\/\d{1,2}\/\d{4}$/, '')
  const searchKey = keyRaw.toLowerCase()

  const poRow = poDxmhList.value.find(r => {
    const s0 = String(r?.[0] ?? '').trim().toLowerCase() // ma_hop_dong
    const s1 = String(r?.[1] ?? '').trim().toLowerCase() // so_hop_dong
    const s2 = String(r?.[2] ?? '').trim().toLowerCase() // so_po
    const s3 = String(r?.[3] ?? '').trim().toLowerCase() // ten_po
    const compositeKey = `${s2} - ${s0}`
    return compositeKey === searchKey || s0 === searchKey || s1 === searchKey || s2 === searchKey || s3 === searchKey
  })
  if (!poRow) {
    loadPipelineMsg.value = '❌ Không tìm thấy PO tương ứng.'
    return
  }

  const so_po = String(poRow[2] || '').trim()
  const so_hd = String(poRow[1] || '').trim()
  const ma_hd = String(poRow[0] || '').trim()

  try {
    loadingPipeline.value = true
    loadPipelineMsg.value = 'Đang tải dữ liệu, vui lòng đợi...'
    showAsyncLoading('Đang load Pipeline...')

    const [hdRows, khList, allCT, allCTMH, allDR] = await Promise.all([
      fetchHopDongTongQuatFromFirebase(),
      fetchKhachHangFromFirebase(),
      fetchHopDongChiTietFromFirebase(),
      fetchChiTietMuaHangFromFirebase(),
      fetchDealRegFromFirebase()
    ])
    
    contractsRaw.value = hdRows || []
    customers.value = khList || []
    
    let contractRow = null
    if (ma_hd) {
      contractRow = contractsRaw.value.find(r => String(r?.[0] ?? '').trim().toLowerCase() === ma_hd.toLowerCase())
    }
    if (!contractRow && so_hd) {
      contractRow = contractsRaw.value.find(r => String(r?.[1] ?? '').trim().toLowerCase() === so_hd.toLowerCase())
    }
    if (!contractRow && so_po) {
      contractRow = contractsRaw.value.find(r => String(r?.[22] ?? '').trim().toLowerCase() === so_po.toLowerCase())
    }

    if (!contractRow) {
      loadPipelineMsg.value = '❌ Đã tìm thấy PO nhưng không tìm thấy Hợp đồng tương ứng!'
      loadingPipeline.value = false
      return
    }

    const ma = String(contractRow?.[0] ?? '').trim()
    const so = String(contractRow?.[1] ?? '').trim()

    const myCTMH = (allCTMH || []).filter((r: any[]) => String(r?.[2] ?? '').trim().toLowerCase() === so_po.toLowerCase() || (so_hd && String(r?.[1] ?? '').trim().toLowerCase() === so_hd.toLowerCase()))

    const myDR = (allDR || []).filter((r: any[]) => String(r?.[2] ?? '').trim().toLowerCase() === so_po.toLowerCase() || (so_hd && String(r?.[1] ?? '').trim().toLowerCase() === so_hd.toLowerCase()))

    const existingTab = findExistingTabByContractRow(contractRow, ma_hd)
    if (existingTab) {
      if (existingTab.id !== activeQuoteTabId.value) {
        switchQuoteTab(existingTab.id)
      } else {
        scrollActiveTabIntoView()
      }
      loadedPipelineExtraData.value = {
        po: poRow,
        contract: contractRow,
        chiTietMuaHang: myCTMH,
        dealReg: myDR
      }
      flushQuoteTabsToStorageNow()
      showLoadPipelineModal.value = false
      loadingPipeline.value = false
      loadPipelineFilter.value = ''
      asyncResultModal.value.show = false
      triggerToast(`Đã chuyển tới tab đang mở hợp đồng ${so || ma}`)
      showPipelineModal.value = true
      return
    }

    await createNewQuoteTab({ silent: true, skipGenerateIds: true })
    currentPO.value = so_po

    loadedMaHopDong.value = ma
    loadedMaHopDongGoc.value = String(contractRow?.[32] ?? '').trim() || ma  // ✅ GHI NHỚ MÃ GỐC
    soHopDong.value = so || soHopDong.value
    maHopDong.value = genUniqueMaHopDong(activeQuoteTabId.value)
    ghiChuHopDong.value = String(contractRow?.[16] ?? '').trim()
    contentOfContractPO.value = String(contractRow?.[24] ?? '').trim()
    
    chietKhauTruocThuePct.value = toNum(contractRow?.[26], 0)
    thueChenhLechPct.value = contractRow?.[28] !== undefined && contractRow?.[28] !== '' ? toNum(contractRow?.[28], 25) : 25

    // ====== load data mapping structure ======
    try {
      const structStr = String(contractRow?.[36] || '').trim()
      if (structStr && structStr.startsWith('[')) {
        excelMappingConfig.value = JSON.parse(structStr)
      }
    } catch (err) {
      console.warn('Cannot parse structure JSON from hop_dong_tong_quat', err)
    }

    const maKH = String(contractRow?.[2] ?? '').trim()
    if (maKH) fillCustomerByMa(maKH)
    else {
      const tenKH = String(contractRow?.[3] ?? '').trim()
      if (tenKH) fillCustomerByTen(tenKH)
    }

    const mineCT = (allCT || []).filter((r: any[]) => String(r?.[0] ?? '').trim() === ma)

    selectedItems.value = mineCT.map(mapHopDongChiTietRowToItem)

    selectedItems.value.forEach(it => {
      if (it.Ma_hang) qtyMap[it.Ma_hang] = Math.max(1, toNum(it.So_luong, 1))
    })

    restoreCmpSrOverridesFromContractRow(contractRow)

    loadedPipelineExtraData.value = {
      po: poRow,
      contract: contractRow,
      chiTietMuaHang: myCTMH,
      dealReg: myDR
    }

    syncFlatRows()
    flushQuoteTabsToStorageNow()
    scrollActiveTabIntoView()

    showLoadPipelineModal.value = false
    loadingPipeline.value = false
    loadPipelineFilter.value = ''
    showAsyncSuccess('Load Pipeline thành công', `PO: ${so_po}`)
    
    showPipelineModal.value = true

  } catch (e: any) {
    console.error(e)
    loadPipelineMsg.value = '❌ Lỗi load: ' + String(e?.message || e)
    showAsyncError('Load Pipeline thất bại', String(e?.message || e))
    loadingPipeline.value = false
  }
}

const quoteCurrency = ref('VND')
type VndPriceFieldKey =
  | 'gia_tieu_chuan'
  | 'list_price'
  | 'gia_nhap'
  | 'don_gia_kh'
  | 'tt_truoc_thue'
  | 'vat'
  | 'tt_sau_thue'

const defaultVndFieldRounding: Record<VndPriceFieldKey, VndRoundingMode> = {
  gia_tieu_chuan: 'none',
  list_price: 'none',
  gia_nhap: 'none',
  don_gia_kh: 'round',
  tt_truoc_thue: 'round',
  vat: 'round',
  tt_sau_thue: 'none'
}

function loadInitialVndFieldRounding(): Record<VndPriceFieldKey, VndRoundingMode> {
  try {
    if (typeof localStorage !== 'undefined') {
      const saved = localStorage.getItem('bg_vnd_field_rounding')
      if (saved) {
        const parsed = JSON.parse(saved)
        if (parsed && typeof parsed === 'object') {
          return { ...defaultVndFieldRounding, ...parsed }
        }
      }
    }
  } catch {}
  return { ...defaultVndFieldRounding }
}

const vndFieldRounding = reactive<Record<VndPriceFieldKey, VndRoundingMode>>(loadInitialVndFieldRounding())

watch(
  vndFieldRounding,
  val => {
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('bg_vnd_field_rounding', JSON.stringify(val))
      }
    } catch {}
  },
  { deep: true }
)

const vndRoundingMode = computed<VndRoundingMode>({
  get: () => vndFieldRounding.don_gia_kh || 'round',
  set: (val: VndRoundingMode) => {
    vndFieldRounding.don_gia_kh = val
    vndFieldRounding.tt_truoc_thue = val
    vndFieldRounding.vat = val
  }
})

function getItemOrFieldRounding(item: any, field: VndPriceFieldKey): VndRoundingMode {
  const itemMode = item?._vndRounding?.[field] as VndRoundingMode | undefined
  if (itemMode && (itemMode === 'round' || itemMode === 'ceil' || itemMode === 'floor' || itemMode === 'none')) {
    return itemMode
  }
  return vndFieldRounding[field] || 'none'
}

function getRoundingBtnLabel(mode: VndRoundingMode, compact = false): string {
  if (mode === 'ceil') return compact ? '↑.000' : '↑ .000'
  if (mode === 'floor') return compact ? '↓.000' : '↓ .000'
  if (mode === 'round') return compact ? '≈.000' : '≈ .000'
  return compact ? '.000▾' : '.000 ▾'
}

const vndRoundingMenu = reactive<{
  open: boolean
  top: number
  left: number
  scope: 'column' | 'quoteEdit' | 'itemForm' | 'cardEdit'
  field: VndPriceFieldKey
  label: string
}>({
  open: false,
  top: 0,
  left: 0,
  scope: 'column',
  field: 'don_gia_kh',
  label: ''
})

function getActiveMenuRoundingMode(): VndRoundingMode {
  const f = vndRoundingMenu.field
  if (vndRoundingMenu.scope === 'quoteEdit' && quoteEdit.value) {
    return getItemOrFieldRounding(quoteEdit.value, f)
  }
  if (vndRoundingMenu.scope === 'itemForm' && itemForm.value) {
    return (itemForm.value as any)?._vndRounding?.[f] || 'none'
  }
  if (vndRoundingMenu.scope === 'cardEdit' && cardEdit.value) {
    return (cardEdit.value as any)?._vndRounding?.[f] || 'none'
  }
  return vndFieldRounding[f] || 'none'
}

function openVndRoundingMenu(
  e: MouseEvent,
  scope: 'column' | 'quoteEdit' | 'itemForm' | 'cardEdit',
  field: VndPriceFieldKey,
  label: string
) {
  const btn = e.currentTarget as HTMLElement | null
  if (
    vndRoundingMenu.open &&
    vndRoundingMenu.scope === scope &&
    vndRoundingMenu.field === field
  ) {
    vndRoundingMenu.open = false
    return
  }
  let top = 120
  let left = 120
  if (btn && typeof window !== 'undefined') {
    const rect = btn.getBoundingClientRect()
    const menuW = 248
    const menuH = 215
    left = Math.min(Math.max(8, rect.left), Math.max(8, window.innerWidth - menuW - 12))
    if (rect.bottom + menuH + 10 > window.innerHeight && rect.top > menuH + 10) {
      top = rect.top - menuH - 6
    } else {
      top = rect.bottom + 6
    }
  }
  vndRoundingMenu.scope = scope
  vndRoundingMenu.field = field
  vndRoundingMenu.label = label
  vndRoundingMenu.top = top
  vndRoundingMenu.left = left
  vndRoundingMenu.open = true
}

function applyDirectBaseFieldRoundingOnObject(target: any, field: VndPriceFieldKey, mode: VndRoundingMode) {
  if (!target) return
  if (!target._vndRounding) target._vndRounding = {}
  target._vndRounding[field] = mode

  const propMap: Partial<Record<VndPriceFieldKey, string>> = {
    list_price: 'Don_gia',
    gia_tieu_chuan: 'Gia_tieu_chuan',
    gia_nhap: 'gia_nhap'
  }
  const prop = propMap[field]
  if (!prop) return

  if (!target._unroundedBase) target._unroundedBase = {}
  if (target._unroundedBase[prop] === undefined) {
    target._unroundedBase[prop] = toNum(target[prop], 0)
  }

  if (mode === 'none') {
    if (target._unroundedBase[prop] !== undefined) {
      target[prop] = target._unroundedBase[prop]
      delete target._unroundedBase[prop]
    }
    return
  }

  const baseVal = toNum(target._unroundedBase[prop] ?? target[prop], 0)
  const tg = Math.max(1, toNum(target.Ti_gia, 1))
  const rawVnd = baseVal * tg
  const roundedVnd = roundVndByMode(rawVnd, mode)
  target[prop] = tg > 1 ? roundedVnd / tg : roundedVnd
}

function selectVndRoundingOption(mode: VndRoundingMode) {
  const { scope, field } = vndRoundingMenu
  if (scope === 'column') {
    vndFieldRounding[field] = mode
    selectedItems.value.forEach((it: any) => {
      if (it && it._vndRounding && it._vndRounding[field] !== undefined) {
        delete it._vndRounding[field]
      }
    })
  } else if (scope === 'quoteEdit' && quoteEdit.value) {
    applyDirectBaseFieldRoundingOnObject(quoteEdit.value, field, mode)
    quoteEdit.value = { ...quoteEdit.value }
  } else if (scope === 'itemForm' && itemForm.value) {
    applyDirectBaseFieldRoundingOnObject(itemForm.value, field, mode)
  } else if (scope === 'cardEdit' && cardEdit.value) {
    applyDirectBaseFieldRoundingOnObject(cardEdit.value, field, mode)
  }
  vndRoundingMenu.open = false
}

function roundVndThousand(n: number, mode: VndRoundingMode = vndFieldRounding.don_gia_kh): number {
  return roundVndByMode(n, mode)
}

/* ======================
   ĐỐI CHIẾU HÀNG HÓA (SOPHOS / KASPERSKY / ACRONIS) -> VIEWOFFICE
====================== */
type RefVendorType = 'sophos' | 'kaspersky' | 'acronis'

interface RefCompareOption {
  id: string
  vendor: RefVendorType
  role: 'goc' | 'tg' | 'mau'
  roleBadge: string
  fileName: string
  sheet: string
  rowNum: number
  colLetter: string
  cellRef: string
  sku: string
  priceText: string
  subNote?: string
}

const vendorRefFilesMeta = ref<Record<RefVendorType, VendorRefFileMeta | null>>({
  sophos: null,
  kaspersky: null,
  acronis: null
})
const vendorRefLoadError = ref<Record<RefVendorType, string>>({
  sophos: '',
  kaspersky: '',
  acronis: ''
})

const sophosRefData = ref<any>(null)
let sophosRefLoadingPromise: Promise<any> | null = null
const kasRefData = ref<any>(null)
let kasRefLoadingPromise: Promise<any> | null = null
const acronisRefData = ref<any>(null)
let acronisRefLoadingPromise: Promise<any> | null = null

const fetchVendorRefFilesMeta = async (force = false) => {
  if (
    !force &&
    (vendorRefFilesMeta.value.sophos ||
      vendorRefFilesMeta.value.kaspersky ||
      vendorRefFilesMeta.value.acronis)
  ) {
    return vendorRefFilesMeta.value
  }
  try {
    const snap = await get(dbRef(database, 'vendor_ref_files'))
    const val = snap.val() || {}
    vendorRefFilesMeta.value = {
      sophos: val.sophos || null,
      kaspersky: val.kaspersky || null,
      acronis: val.acronis || null
    }
  } catch (err) {
    console.error('Lỗi đọc vendor_ref_files từ Firebase:', err)
  }
  return vendorRefFilesMeta.value
}

const getVendorImportFileMeta = (vendor: RefVendorType) => {
  const m = vendorRefFilesMeta.value?.[vendor]
  if (!m) return null
  if (m.import_file_name) {
    return {
      name: m.import_file_name,
      url: m.import_file_url || m.index_url || '',
      updatedAt: m.import_updated_at || m.updated_at || 0
    }
  }
  if (vendor === 'sophos' && m.tg_file_name) {
    return {
      name: m.tg_file_name,
      url: m.tg_file_url || m.index_url || '',
      updatedAt: m.tg_updated_at || m.updated_at || 0
    }
  }
  if ((vendor === 'kaspersky' || vendor === 'acronis') && m.mau_file_name) {
    return {
      name: m.mau_file_name,
      url: m.mau_file_url || m.index_url || '',
      updatedAt: m.mau_updated_at || m.updated_at || 0
    }
  }
  if (m.goc_file_name) {
    return {
      name: m.goc_file_name,
      url: m.goc_file_url || m.index_url || '',
      updatedAt: m.goc_updated_at || m.updated_at || 0
    }
  }
  return null
}

const getVendorCompareFileMeta = (vendor: RefVendorType, part: 'goc' | 'tg' = 'goc') => {
  const m = vendorRefFilesMeta.value?.[vendor]
  if (!m) return null
  if (part === 'goc') {
    if (vendor === 'sophos') {
      const sName = m.skulist_file_name || m.goc_file_name
      const sUrl = m.skulist_file_url || m.goc_file_url || m.index_url || ''
      if (!sName) return null
      return {
        name: sName,
        url: sUrl,
        updatedAt: m.goc_updated_at || m.updated_at || 0
      }
    }
    if (!m.goc_file_name) return null
    return {
      name: m.goc_file_name,
      url: m.goc_file_url || m.index_url || '',
      updatedAt: m.goc_updated_at || m.updated_at || 0
    }
  }
  if (vendor === 'sophos') {
    if (!m.tg_file_name) return null
    return {
      name: m.tg_file_name,
      url: m.tg_file_url || m.index_url || '',
      updatedAt: m.tg_updated_at || m.updated_at || 0
    }
  }
  if (vendor === 'kaspersky' || vendor === 'acronis') {
    if (!m.mau_file_name) return null
    return {
      name: m.mau_file_name,
      url: m.mau_file_url || m.index_url || '',
      updatedAt: m.mau_updated_at || m.updated_at || 0
    }
  }
  return null
}

const loadSophosRefData = async (forceReload = false) => {
  if (!forceReload && sophosRefData.value) return sophosRefData.value
  if (!forceReload && sophosRefLoadingPromise) return sophosRefLoadingPromise
  sophosRefLoadingPromise = (async () => {
    try {
      vendorRefLoadError.value.sophos = ''
      const allMeta = await fetchVendorRefFilesMeta(forceReload)
      const meta = allMeta?.sophos
      if (!meta?.index_url) {
        vendorRefLoadError.value.sophos =
          'Chưa có file tham chiếu Sophos trên Cloudinary. Vui lòng upload tại trang Quản lý hàng hóa.'
        return { gocSkus: {}, trungGianItems: [], lpSophos: [], tgSkuLocations: {} }
      }
      const res = await fetch(meta.index_url)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      sophosRefData.value = await res.json()
      return sophosRefData.value
    } catch (e: any) {
      vendorRefLoadError.value.sophos =
        'Không tải được dữ liệu tham chiếu Sophos từ Cloudinary: ' + (e?.message || e)
      return { gocSkus: {}, trungGianItems: [], lpSophos: [], tgSkuLocations: {} }
    } finally {
      sophosRefLoadingPromise = null
    }
  })()
  return sophosRefLoadingPromise
}

