  const set = new Set<string>()
  products.value.forEach(p => {
    const key = p.Ten_nha_cung_cap?.trim() || p.Ma_nha_cung_cap?.trim()
    if (key) set.add(key)
  })
  return Array.from(set).sort((a, b) => a.localeCompare(b))
})

const normalizeString = (s: string) => (s || '').toLowerCase().replace(/[^a-z0-9\u00C0-\u024F\u1E00-\u1EFF]/gi, '')

const showCustomerPickerModal = ref(false)
const customerPickerField = ref<'ma_kh' | 'ten_kh' | 'ten_cong_ty' | 'mst'>('ma_kh')
const customerPickerSearch = ref('')
const customerPickerVisibleCount = ref(20)

const customerPickerTitle = computed(() => {
  switch (customerPickerField.value) {
    case 'ma_kh': return 'CHỌN MÃ KHÁCH HÀNG'
    case 'ten_kh': return 'CHỌN TÊN NGƯỜI LIÊN HỆ / KHÁCH HÀNG'
    case 'ten_cong_ty': return 'CHỌN TÊN CÔNG TY'
    case 'mst': return 'CHỌN MÃ SỐ THUẾ (MST)'
  }
})

const customerPickerColumnLabel = computed(() => {
  switch (customerPickerField.value) {
    case 'ma_kh': return 'Mã khách hàng'
    case 'ten_kh': return 'Tên người liên hệ (Khách hàng)'
    case 'ten_cong_ty': return 'Tên công ty'
    case 'mst': return 'Mã số thuế (MST)'
  }
})

function getCustomerPickerValue(cus: KhachHang): string {
  if (!cus) return ''
  switch (customerPickerField.value) {
    case 'ma_kh': return String(cus.Ma_khach_hang || '').trim()
    case 'ten_kh': return String(cus.Ten_khach_hang || '').trim()
    case 'ten_cong_ty': return String(cus.Ten_cong_ty || '').trim()
    case 'mst': return String(cus.MST || '').trim()
  }
}

function isCustomerRowSelected(cus: KhachHang): boolean {
  const val = getCustomerPickerValue(cus)
  if (!val) return false
  switch (customerPickerField.value) {
    case 'ma_kh': return (maKHInput.value || khach.value.Ma_khach_hang) === val
    case 'ten_kh': return (tenKHInput.value || khach.value.Ten_khach_hang) === val
    case 'ten_cong_ty': return khach.value.Ten_cong_ty === val
    case 'mst': return khach.value.MST === val
  }
}

function openCustomerPicker(field: 'ma_kh' | 'ten_kh' | 'ten_cong_ty' | 'mst' = 'ma_kh') {
  customerPickerField.value = field
  customerPickerSearch.value = ''
  customerPickerVisibleCount.value = 20
  showCustomerPickerModal.value = true
}

watch(customerPickerSearch, () => {
  customerPickerVisibleCount.value = 20
})

const filteredCustomerPickerList = computed(() => {
  const q = normalizeString(removeDiacritics(customerPickerSearch.value.trim()))
  const seen = new Set<string>()
  const result: KhachHang[] = []
  for (const c of customers.value || []) {
    const val = getCustomerPickerValue(c)
    if (!val) continue
    const key = val.toLowerCase()
    if (seen.has(key)) continue
    if (q) {
      const hay = normalizeString(removeDiacritics(val))
      if (!hay.includes(q)) continue
    }
    seen.add(key)
    result.push(c)
  }
  return result
})

const visibleCustomerPickerList = computed(() => {
  return filteredCustomerPickerList.value.slice(0, customerPickerVisibleCount.value)
})

function onCustomerPickerScroll(e: Event) {
  const el = e.target as HTMLElement
  if (!el) return
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 60) {
    if (customerPickerVisibleCount.value < filteredCustomerPickerList.value.length) {
      customerPickerVisibleCount.value += 20
    }
  }
}

function selectCustomerFromPicker(cus: KhachHang) {
  if (!cus) return
  isExistingCustomer.value = true
  hasImportedCustomerPendingSave.value = false
  originalKhach.value = JSON.parse(JSON.stringify(cus))
  khach.value = JSON.parse(JSON.stringify(cus))
  maKHInput.value = cus.Ma_khach_hang || ''
  tenKHInput.value = cus.Ten_khach_hang || ''
  showCustomerPickerModal.value = false
  triggerToast(`Đã chọn: ${getCustomerPickerValue(cus)}`)
}

type ProductPickerFieldType =
  | 'ten_hang'
  | 'ma_hang'
  | 'sku_code'
  | 'danh_muc'
  | 'dvt'
  | 'hang'
  | 'type'
  | 'license_duration'
  | 'thoi_han_bao_hanh'
  | 'volume'

interface ProductPickerEntry {
  value: string
  product?: HangHoa
}

const CUSTOM_PICKER_OPTIONS_STORAGE_KEY = 'bg_custom_picker_options_v1'
const customProductPickerOptions = ref<Record<string, string[]>>((() => {
  try {
    const raw = localStorage.getItem(CUSTOM_PICKER_OPTIONS_STORAGE_KEY)
    const parsed = raw ? JSON.parse(raw) : null
    if (parsed && typeof parsed === 'object') return parsed
  } catch {}
  return {}
})())

function persistCustomProductPickerOptions() {
  try {
    localStorage.setItem(CUSTOM_PICKER_OPTIONS_STORAGE_KEY, JSON.stringify(customProductPickerOptions.value))
  } catch {}
  set(dbRef(database, 'hang_hoa_tuy_chon'), customProductPickerOptions.value).catch(() => {})
}

// Đồng bộ tùy chọn tự thêm từ Firebase (nếu có)
get(dbRef(database, 'hang_hoa_tuy_chon'))
  .then(snap => {
    const val = snap.val()
    if (val && typeof val === 'object') {
      const merged: Record<string, string[]> = { ...customProductPickerOptions.value }
      Object.entries(val).forEach(([k, arr]) => {
        const list = Array.isArray(arr) ? arr : Object.values((arr as any) || {})
        const existing = Array.isArray(merged[k]) ? merged[k] : []
        const seen = new Set(existing.map(x => String(x || '').trim().toLowerCase()))
        list.forEach((v: any) => {
          const s = String(v || '').trim()
          if (s && !seen.has(s.toLowerCase())) {
            seen.add(s.toLowerCase())
            existing.push(s)
          }
        })
        merged[k] = existing
      })
      customProductPickerOptions.value = merged
      try {
        localStorage.setItem(CUSTOM_PICKER_OPTIONS_STORAGE_KEY, JSON.stringify(merged))
      } catch {}
    }
  })
  .catch(() => {})

const showProductPickerModal = ref(false)
const productPickerTarget = ref<'manual' | 'card' | 'quoteEdit'>('manual')
const productPickerField = ref<ProductPickerFieldType>('ten_hang')
const productPickerSearch = ref('')
const productPickerVisibleCount = ref(20)

const isAttributePickerField = computed<boolean>(() => {
  return [
    'danh_muc',
    'dvt',
    'hang',
    'type',
    'license_duration',
    'thoi_han_bao_hanh',
    'volume'
  ].includes(productPickerField.value)
})

const canAddCustomOptionInPicker = computed<boolean>(() => {
  if (!isAttributePickerField.value) return false
  const raw = String(productPickerSearch.value || '').trim()
  if (!raw) return false
  const lower = raw.toLowerCase()
  return !filteredProductPickerList.value.some(e => e.value.toLowerCase() === lower)
})

function addAndSelectCustomPickerOption() {
  if (!isAttributePickerField.value) return
  let cleanVal = String(productPickerSearch.value || '').trim()
  if (!cleanVal) return
  const field = productPickerField.value
  if (field === 'danh_muc' || field === 'hang') {
    cleanVal = cleanVal.toUpperCase()
  }
  const bucket = Array.isArray(customProductPickerOptions.value[field])
    ? [...customProductPickerOptions.value[field]]
    : []
  if (!bucket.some(x => String(x || '').trim().toLowerCase() === cleanVal.toLowerCase())) {
    bucket.unshift(cleanVal)
    customProductPickerOptions.value = {
      ...customProductPickerOptions.value,
      [field]: bucket
    }
    persistCustomProductPickerOptions()
  }
  selectProductFromPicker({ value: cleanVal })
}

const productPickerTitle = computed(() => {
  switch (productPickerField.value) {
    case 'ma_hang': return 'CHỌN MÃ HÀNG HÓA (P/N)'
    case 'sku_code': return 'CHỌN MÃ SKU (SKU CODE)'
    case 'danh_muc': return 'CHỌN DANH MỤC HÀNG HÓA'
    case 'dvt': return 'CHỌN ĐƠN VỊ TÍNH (ĐVT)'
    case 'hang': return 'CHỌN HÃNG / NHÀ CUNG CẤP'
    case 'type': return 'CHỌN LOẠI HÀNG (TYPE)'
    case 'license_duration': return 'CHỌN LICENSE DURATION'
    case 'thoi_han_bao_hanh': return 'CHỌN THỜI HẠN BẢO HÀNH'
    case 'volume': return 'CHỌN VOLUME (RANGE USERS / BLOCKS)'
    default: return 'CHỌN TÊN HÀNG HÓA'
  }
})

const productPickerColumnLabel = computed(() => {
  switch (productPickerField.value) {
    case 'ma_hang': return 'Mã hàng hóa (P/N)'
    case 'sku_code': return 'SKU Code'
    case 'danh_muc': return 'Danh mục'
    case 'dvt': return 'Đơn vị tính (ĐVT)'
    case 'hang': return 'Hãng / Nhà cung cấp'
    case 'type': return 'Loại hàng (Type)'
    case 'license_duration': return 'License duration'
    case 'thoi_han_bao_hanh': return 'Thời hạn bảo hành'
    case 'volume': return 'Volume'
    default: return 'Tên hàng hóa'
  }
})

function getProductFieldFromItem(p: HangHoa, field: ProductPickerFieldType): string {
  if (!p) return ''
  switch (field) {
    case 'ma_hang': return String(p.Ma_hang || '').trim()
    case 'sku_code': return String(p.sku_code || '').trim()
    case 'danh_muc': return String(p.Danh_muc || '').trim().toUpperCase()
    case 'dvt': return String(p.DVT || '').trim()
    case 'hang': return String(p.Ten_nha_cung_cap || p.Ma_nha_cung_cap || '').trim()
    case 'type': return String(p.Type ?? p.TYPE ?? '').trim()
    case 'license_duration': return String(p.License_duration || '').trim()
    case 'thoi_han_bao_hanh': return String(p.thoi_han_bao_hanh || '').trim()
    case 'volume': return String(p.volume || '').trim()
    default: return String(p.Ten_hang || '').trim()
  }
}

function getActiveProductModalTarget(): any {
  if (productPickerTarget.value === 'manual') return itemForm.value
  if (productPickerTarget.value === 'card') return cardEdit.value
  return quoteEdit.value
}

function isProductRowSelected(entry: ProductPickerEntry): boolean {
  const target = getActiveProductModalTarget()
  if (!target || !entry?.value) return false
  const curVal = getProductFieldFromItem(target, productPickerField.value)
  return curVal.toLowerCase() === entry.value.toLowerCase()
}

function openProductPicker(
  target: 'manual' | 'card' | 'quoteEdit' = 'manual',
  field: ProductPickerFieldType = 'ten_hang'
) {
  productPickerTarget.value = target
  productPickerField.value = field
  productPickerSearch.value = ''
  productPickerVisibleCount.value = 20
  showProductPickerModal.value = true
}

watch(productPickerSearch, () => {
  productPickerVisibleCount.value = 20
})

const filteredProductPickerList = computed<ProductPickerEntry[]>(() => {
  const q = normalizeString(removeDiacritics(productPickerSearch.value.trim()))
  const field = productPickerField.value
  const seen = new Set<string>()
  const result: ProductPickerEntry[] = []

  const pushEntry = (val: string, product?: HangHoa) => {
    const clean = String(val || '').trim()
    if (!clean) return
    const key = clean.toLowerCase()
    if (seen.has(key)) return
    if (q) {
      const hay = normalizeString(removeDiacritics(clean))
      if (!hay.includes(q)) return
    }
    seen.add(key)
    result.push({ value: clean, product })
  }

  const customList = customProductPickerOptions.value[field]
  if (Array.isArray(customList)) {
    for (const customVal of customList) {
      pushEntry(customVal)
    }
  }

  if (field === 'danh_muc') {
    for (const cat of existingCategories.value || []) {
      pushEntry(String(cat || '').toUpperCase())
    }
  } else if (field === 'dvt') {
    for (const u of ['CÁI', 'BẢN QUYỀN', 'BỘ', 'GÓI', 'THIẾT BỊ', 'CHIẾC', 'NĂM', 'THÁNG', 'LICENSE', 'USER', 'DEVICE']) {
      pushEntry(u)
    }
  } else if (field === 'type') {
    for (const t of ['New', 'Renewal', 'Base Plus', 'Renewal Plus', 'Hardware', 'Software']) {
      pushEntry(t)
    }
  } else if (field === 'license_duration') {
    for (const ld of ['12 months', '24 months', '36 months', '1 Year', '2 Years', '3 Years', 'Perpetual']) {
      pushEntry(ld)
    }
  } else if (field === 'thoi_han_bao_hanh') {
    for (const bh of ['12 tháng', '24 tháng', '36 tháng', '6 tháng', '60 tháng', 'Theo tiêu chuẩn hãng']) {
      pushEntry(bh)
    }
  } else if (field === 'volume') {
    for (const vol of ['1-9 users', '10-24 users', '25-49 users', '50-99 users', '100-249 users']) {
      pushEntry(vol)
    }
  }

  for (const p of products.value || []) {
    const val = getProductFieldFromItem(p, field)
    if (!val) continue
    pushEntry(val, p)
  }

  return result
})

const visibleProductPickerList = computed(() => {
  return filteredProductPickerList.value.slice(0, productPickerVisibleCount.value)
})

function onProductPickerScroll(e: Event) {
  const el = e.target as HTMLElement
  if (!el) return
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 60) {
    if (productPickerVisibleCount.value < filteredProductPickerList.value.length) {
      productPickerVisibleCount.value += 20
    }
  }
}

function selectProductFromPicker(entry: ProductPickerEntry) {
  if (!entry || !entry.value) return
  const field = productPickerField.value
  const targetMode = productPickerTarget.value

  if (field === 'ten_hang' || field === 'ma_hang') {
    const rawP = entry.product
    if (!rawP) return
    const p = getProductWithPriceList(rawP)
    if (targetMode === 'manual') {
      const keepQty = itemForm.value.So_luong
      isMaHangEdited.value = true
      itemForm.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
    } else if (targetMode === 'card' && cardEdit.value) {
      const keepQty = cardEdit.value.So_luong
      isCardMaHangEdited.value = true
      cardEdit.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
    } else if (targetMode === 'quoteEdit' && quoteEdit.value) {
      const keepQty = quoteEdit.value.So_luong
      quoteEdit.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
    }
  } else if (field === 'sku_code') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      if (!String(targetObj.Ten_hang || '').trim() && entry.product) {
        const p = getProductWithPriceList(entry.product)
        const keepQty = targetObj.So_luong
        if (targetMode === 'manual') {
          isMaHangEdited.value = true
          itemForm.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
        } else if (targetMode === 'card' && cardEdit.value) {
          isCardMaHangEdited.value = true
          cardEdit.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
        } else if (targetMode === 'quoteEdit' && quoteEdit.value) {
          quoteEdit.value = { ...JSON.parse(JSON.stringify(p)), So_luong: Math.max(1, toNum(keepQty, 1)) }
        }
      } else {
        targetObj.sku_code = entry.value
        if (targetMode === 'manual') updateMaHang()
      }
    }
  } else if (field === 'danh_muc') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.Danh_muc = entry.value.toUpperCase()
      if (targetMode === 'manual') updateMaHang()
      else if (targetMode === 'card') updateCardMaHang()
    }
  } else if (field === 'dvt') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.DVT = entry.value
    }
  } else if (field === 'hang') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.Ten_nha_cung_cap = entry.value
      if (targetMode === 'manual') updateMaNcc()
      else if (targetMode === 'card') updateCardMaNcc()
    }
  } else if (field === 'type') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.Type = entry.value
      if (targetMode === 'manual') updateMaHang()
    }
  } else if (field === 'license_duration') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.License_duration = entry.value
    }
  } else if (field === 'thoi_han_bao_hanh') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.thoi_han_bao_hanh = entry.value
    }
  } else if (field === 'volume') {
    const targetObj = getActiveProductModalTarget()
    if (targetObj) {
      targetObj.volume = entry.value
    }
  }

  showProductPickerModal.value = false
  triggerToast(`Đã chọn: ${entry.value}`)
}

function checkVolumeMatch(volumeStr: string, userCount: number): boolean {
  if (!volumeStr) return false;
  const str = volumeStr.toLowerCase();
  
  // 1. Range: A-B or A - B
  const rangeMatch = str.match(/(\d+)\s*-\s*(\d+)/);
  if (rangeMatch) {
    const min = parseInt(rangeMatch[1], 10);
    const max = parseInt(rangeMatch[2], 10);
    return userCount >= min && userCount <= max;
  }
  
  // 2. Less than: < 50
  const lessMatch = str.match(/<\s*(\d+)/);
  if (lessMatch) {
    const val = parseInt(lessMatch[1], 10);
    return userCount < val;
  }
  
  // 3. Greater than: > 1000 or 1000+
  const greaterMatch1 = str.match(/>\s*(\d+)/);
  if (greaterMatch1) {
    const val = parseInt(greaterMatch1[1], 10);
    return userCount > val;
  }
  const greaterMatch2 = str.match(/(\d+)\s*\+/);
  if (greaterMatch2) {
    const val = parseInt(greaterMatch2[1], 10);
    return userCount >= val;
  }
  
  return false;
}

const filteredProducts = computed(() => {
  const kw = keyword.value.trim()
  const uCount = parseInt(userVolumeFilter.value, 10)
  const hasVolumeFilter = userVolumeFilter.value !== '' && !isNaN(uCount)
  const hasPriceListFilter = Boolean(selectedPriceListId.value && activePriceList.value && filterOnlyPriceListItems.value)

  const words = kw ? kw.toLowerCase().split(/\s+/).filter(Boolean) : []

  return products.value
    .filter(p => {
      if (hasPriceListFilter && !activePriceListMap.value.has(String(p.Ma_hang || '').trim())) {
        return false
      }

      const okSupplier =
        supplierFilter.value === 'ALL' ||
        p.Ten_nha_cung_cap === supplierFilter.value ||
        p.Ma_nha_cung_cap === supplierFilter.value
      if (!okSupplier) return false

      let okKw = true
      if (words.length > 0) {
        const ma = (p.Ma_hang || '').toLowerCase()
        const sku = (p.sku_code || '').toLowerCase()
        const ten = (p.Ten_hang || '').toLowerCase()
        const ncc = (p.Ten_nha_cung_cap || '').toLowerCase()

        const maN = normalizeString(ma)
        const skuN = normalizeString(sku)
        const tenN = normalizeString(ten)
        const nccN = normalizeString(ncc)

        okKw = words.every(w => {
          const wN = normalizeString(w)
          return ma.includes(w) || maN.includes(wN) ||
                 sku.includes(w) || skuN.includes(wN) ||
                 ten.includes(w) || tenN.includes(wN) ||
                 ncc.includes(w) || nccN.includes(wN)
        })
      }

      let okVolume = true
      if (hasVolumeFilter) {
        okVolume = checkVolumeMatch(p.volume || '', uCount)
      }

      return okKw && okVolume
    })
    .map(p => getProductWithPriceList(p))
})

watch(keyword, (newVal) => {
  if (searchTimeout) clearTimeout(searchTimeout)
  const clean = String(newVal || '').trim()
  if (clean.length < 2) return
  searchTimeout = setTimeout(() => {
    if (String(keyword.value || '').trim() === clean && filteredProducts.value.length > 0) {
      saveRecentSearch(clean)
    }
  }, 2000)
})

const PRODUCT_LAZY_BATCH_SIZE = 25
const displayLimit = ref(PRODUCT_LAZY_BATCH_SIZE)
const productLazySentinelRef = ref<HTMLElement | null>(null)
let productLazyObserver: IntersectionObserver | null = null

watch([keyword, supplierFilter, userVolumeFilter, selectedPriceListId, filterOnlyPriceListItems], () => {
  displayLimit.value = PRODUCT_LAZY_BATCH_SIZE
})

const displayedProducts = computed(() => {
  return filteredProducts.value.slice(0, displayLimit.value)
})

function loadMoreProducts() {
  if (displayLimit.value < filteredProducts.value.length) {
    displayLimit.value += PRODUCT_LAZY_BATCH_SIZE
  }
}

function onProductGridScroll(e: Event) {
  const el = e.target as HTMLElement | null
  if (!el) return
  if (el.scrollTop + el.clientHeight >= el.scrollHeight - 220) {
    loadMoreProducts()
  }
  if (typeof window !== 'undefined' && window.innerWidth <= 1100 && el.classList.contains('sidebar-left')) {
    const curY = Math.max(0, el.scrollTop || 0)
    const delta = curY - lastProductSidebarScrollTop
    if (curY <= 36 || showRecentSearches.value) {
      isMobileProductHeaderHidden.value = false
    } else if (delta > 10 && curY > 72) {
      isMobileProductHeaderHidden.value = true
      if (!isPriceListCollapsed.value) {
        isPriceListCollapsed.value = true
      }
    } else if (delta < -8) {
      isMobileProductHeaderHidden.value = false
    }
    lastProductSidebarScrollTop = curY
  }
}

watch(productLazySentinelRef, (sentinel) => {
  if (productLazyObserver) {
    productLazyObserver.disconnect()
    productLazyObserver = null
  }
  if (sentinel && typeof IntersectionObserver !== 'undefined') {
    productLazyObserver = new IntersectionObserver(
      (entries) => {
        if (entries.some(entry => entry.isIntersecting)) {
          loadMoreProducts()
        }
      },
      { rootMargin: '220px' }
    )
    productLazyObserver.observe(sentinel)
  }
})

/* ======================
   CARD QTY realtime
====================== */
function incQty(ma: string) {
  qtyMap[ma] = Math.max(1, toNum(qtyMap[ma], 1) + 1)
}
function decQty(ma: string) {
  qtyMap[ma] = Math.max(1, toNum(qtyMap[ma], 1) - 1)
}

/* ======================
   ADD / RESET
====================== */
function resolveMaHang(item: HangHoa) {
  if (!item.Ma_hang) return item.Ma_hang;
  const exactMatch = selectedItems.value.find(
    it => it.Ten_hang === item.Ten_hang && 
         (it.Ma_hang === item.Ma_hang || it.Ma_hang.startsWith(item.Ma_hang + '-V'))
  );
  if (exactMatch) return exactMatch.Ma_hang;

  const collision = selectedItems.value.find(it => it.Ma_hang === item.Ma_hang);
  if (collision && collision.Ten_hang !== item.Ten_hang) {
    let maxV = 0;
    selectedItems.value.forEach(it => {
      if (it.Ma_hang.startsWith(item.Ma_hang + '-V')) {
        const vNum = parseInt(it.Ma_hang.split('-V').pop() || '0');
        if (!isNaN(vNum) && vNum > maxV) maxV = vNum;
      }
    });
    return `${item.Ma_hang}-V${maxV + 1}`;
  }
  return item.Ma_hang;
}
function insertItemIntoGroup(cloned: any) {
  if (!quoteGroupByCategory.value) {
    selectedItems.value.push(cloned);
    return selectedItems.value.length - 1;
  }
  const targetCat = (cloned.Danh_muc || '').trim().toUpperCase();
  
  let insertIdx = -1;
  for (let i = selectedItems.value.length - 1; i >= 0; i--) {
    const cat = (selectedItems.value[i].Danh_muc || '').trim().toUpperCase();
    if (cat === targetCat) {
      insertIdx = i + 1;
      break;
    }
  }

  if (insertIdx !== -1) {
    selectedItems.value.splice(insertIdx, 0, cloned);
    return insertIdx;
  } else {
    selectedItems.value.push(cloned);
    return selectedItems.value.length - 1;
  }
}

function addItemFromCard(rawP: HangHoa) {
  const p = getProductWithPriceList(rawP)
  const qty = Math.max(1, qtyMap[p.Ma_hang] || 1)
  const resolvedMaHang = resolveMaHang(p);

  const foundIdx = selectedItems.value.findIndex(
    it => it.Ma_hang === resolvedMaHang
  )

  let highlightIdx = -1;
  if (foundIdx >= 0) {
    selectedItems.value[foundIdx].So_luong += qty
    selectedItems.value[foundIdx].Don_gia = p.Don_gia
    ;(selectedItems.value[foundIdx] as any)._Don_gia_goc = p.Don_gia
    ;(selectedItems.value[foundIdx] as any)._Don_gia_kho = p.Don_gia
    highlightIdx = foundIdx;
  } else {
    const cloned = cloneHang(p, qty);
    cloned.Ma_hang = resolvedMaHang;
    highlightIdx = insertItemIntoGroup(cloned);
  }
  
  scrollToAndHighlightRow(highlightIdx);
  if (String(keyword.value || '').trim().length >= 2) {
    saveRecentSearch(keyword.value);
  }
  triggerToast('Đã thêm sản phẩm thành công!');
  addedStatus[p.Ma_hang] = true;
  setTimeout(() => { addedStatus[p.Ma_hang] = false; }, 1500);
}

function getLinkedItems(p: HangHoa) {
  if (!p.Ma_hang_lien_ket) return [];
  const codes = String(p.Ma_hang_lien_ket).split(/[,\n]+/).map(c => c.trim()).filter(Boolean);
  const names = p.Ten_hang_lien_ket ? String(p.Ten_hang_lien_ket).split(/[,\n]+/).map(n => n.trim()) : [];
  
  return codes.map((code, idx) => {
    let name = names[idx];
    if (!name) {
      const found = products.value.find(x => x.Ma_hang === code);
      name = found ? found.Ten_hang : code;
    }
    return { code, name };
  });
}

function addLinkedItem(code: string) {
  const foundProduct = products.value.find(x => x.Ma_hang === code);
  if (foundProduct) {
    addItemFromCard(getProductWithPriceList(foundProduct));
  }
}


function scrollToAndHighlightRow(idx: number, scroll = true) {
  setTimeout(() => {
    const rowEl = document.getElementById(`quote-row-${idx}`);
    if (rowEl) {
      if (scroll) {
        rowEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      rowEl.classList.remove('highlight-pulse');
      void rowEl.offsetWidth; // trigger reflow
      rowEl.classList.add('highlight-pulse');

      // Ensure highlight turns off and clean up any stuck drag classes
      setTimeout(() => {
        if (rowEl) {
          rowEl.classList.remove('highlight-pulse');
          rowEl.classList.remove('ghost-item');
          rowEl.classList.remove('sortable-chosen');
          rowEl.classList.remove('sortable-ghost');
        }
      }, 900);
    }
  }, 100);
}

function addItem(item: HangHoa & { So_luong: number }) {
  addAction(`Thêm hàng "${item.Ten_hang}"`)
  const resolvedMaHang = resolveMaHang(item);

  const foundIdx = selectedItems.value.findIndex(
    it => it.Ma_hang === resolvedMaHang
  )

  let highlightIdx = -1;
  if (foundIdx >= 0) {
    selectedItems.value[foundIdx].So_luong += Math.max(1, toNum(item.So_luong, 1))
    highlightIdx = foundIdx;
  } else {
    const cloned = withOriginalPriceFields(JSON.parse(JSON.stringify(item)));
    cloned.Ma_hang = resolvedMaHang;
    highlightIdx = insertItemIntoGroup(cloned);
  }
  
  // Rebuild liên kết cho TẤT CẢ hàng cùng danh mục (cả hàng mới lẫn hàng cũ)
  const addedCat = (item.Danh_muc || '').trim().toUpperCase();
  if (addedCat) rebuildCategoryLinks(addedCat);
  
  scrollToAndHighlightRow(highlightIdx);
  if (String(keyword.value || '').trim().length >= 2) {
    saveRecentSearch(keyword.value);
  }
  triggerToast('Đã thêm sản phẩm thành công!');
  const itemCode = String(resolvedMaHang || item.Ma_hang || '').trim();
  if (itemCode) {
    addedStatus[itemCode] = true;
    setTimeout(() => { addedStatus[itemCode] = false; }, 1500);
  }
}

/**
 * Rebuild Ma_hang_lien_ket + Ten_hang_lien_ket cho TẤT CẢ item
 * trong selectedItems có cùng danh mục.
 * Mỗi item sẽ liên kết tới tất cả item khác cùng danh mục
 * (từ cả selectedItems + products database).
 */
function rebuildCategoryLinks(category: string) {
  const cat = category.trim().toUpperCase();
  if (!cat) return;

  // Thu thập tất cả item cùng danh mục trong bảng báo giá
  const itemsInCat = selectedItems.value.filter(
    it => (it.Danh_muc || '').trim().toUpperCase() === cat
  );
  
  // Thu thập tất cả item cùng danh mục trong kho sản phẩm (database)
  const productsInCat = products.value.filter(
    p => (p.Danh_muc || '').trim().toUpperCase() === cat
  );

  // Merge tất cả (Ma_hang -> Ten_hang), ưu tiên selectedItems
  const allMap = new Map<string, string>();
  itemsInCat.forEach(it => allMap.set(it.Ma_hang, it.Ten_hang));
  productsInCat.forEach(p => {
    if (!allMap.has(p.Ma_hang)) allMap.set(p.Ma_hang, p.Ten_hang);
  });

  // Với mỗi item trong bảng báo giá cùng danh mục, gán liên kết = tất cả item KHÁC
  itemsInCat.forEach(it => {
    const others = new Map(allMap);
    others.delete(it.Ma_hang); // loại chính nó
    if (others.size > 0) {
      it.Ma_hang_lien_ket = Array.from(others.keys()).join('\n');
      it.Ten_hang_lien_ket = Array.from(others.values()).join('\n');
    }
   });
}

const showConfirmAddDbModal = ref(false);
