function normalizeProductFileHistory(rawList: any): ProductFileEntry[] {
  if (!rawList) return []
  const arr = Array.isArray(rawList) ? rawList : Object.values(rawList)
  return arr
    .filter((x: any) => x && (x.file_url || x.file_name))
    .map((x: any, idx: number) => ({
      id: String(x.id || `file_${idx}_${Date.now()}`),
      file_name: String(x.file_name || 'File đính kèm'),
      file_url: String(x.file_url || ''),
      file_type: String(x.file_type || ''),
      file_uploaded_at: String(x.file_uploaded_at || ''),
      gia_von: Number(x.gia_von ?? x.Gia_tieu_chuan) || 0,
      don_gia: Number(x.don_gia ?? x.Don_gia) || 0,
      gia_nhap: Number(x.gia_nhap) || 0,
      don_vi_tien_te: String(x.don_vi_tien_te || x.Don_vi_tien_te || 'VND'),
      ghi_chu_file: String(x.ghi_chu_file || '')
    }))
}

function findSysProductForModal(item: any): HangHoa | undefined {
  if (!item) return undefined
  const ma = String(item.Ma_hang || '').trim()
  const baseMa = ma.replace(/-V\d+$/i, '')
  const sku = String(item.sku_code || '').trim().toLowerCase()
  const ten = String(item.Ten_hang || '').trim().toLowerCase()
  return products.value.find(p => {
    const pMa = String(p.Ma_hang || '').trim()
    if (ma && pMa === ma) return true
    if (baseMa && pMa === baseMa) return true
    if (sku && String(p.sku_code || '').trim().toLowerCase() === sku) return true
    if (ten && String(p.Ten_hang || '').trim().toLowerCase() === ten) return true
    return false
  })
}

function getProductLastUpdated(item: any): string {
  if (!item) return ''
  if (item.last_updated && String(item.last_updated).trim()) {
    return String(item.last_updated).trim()
  }
  const sys = findSysProductForModal(item)
  return String(sys?.last_updated || '').trim()
}

function getCustomerLastUpdated(kh: any): string {
  if (!kh) return ''
  if (kh.last_updated && String(kh.last_updated).trim()) {
    return String(kh.last_updated).trim()
  }
  const ma = String(kh.Ma_khach_hang || maKHInput.value || '').trim().toLowerCase()
  const mst = String(kh.MST || '').trim().toLowerCase()
  const cty = String(kh.Ten_cong_ty || '').trim().toLowerCase()
  const ten = String(kh.Ten_khach_hang || tenKHInput.value || '').trim().toLowerCase()
  const found = customers.value.find(c => {
    if (ma && String(c.Ma_khach_hang || '').trim().toLowerCase() === ma) return true
    if (mst && String(c.MST || '').trim().toLowerCase() === mst) return true
    if (cty && String(c.Ten_cong_ty || '').trim().toLowerCase() === cty) return true
    if (ten && String(c.Ten_khach_hang || '').trim().toLowerCase() === ten) return true
    return false
  })
  return String(found?.last_updated || '').trim()
}

function getProductFileHistory(item: any): ProductFileEntry[] {
  if (!item) return []
  const direct = normalizeProductFileHistory(item.danh_sach_file)
  if (direct.length > 0) return direct
  const sys = findSysProductForModal(item)
  return normalizeProductFileHistory(sys?.danh_sach_file)
}

function formatLastUpdated(val: any): string {
  if (!val) return 'Chưa ghi nhận'
  const s = String(val).trim()
  if (!s) return 'Chưa ghi nhận'
  const d = new Date(s)
  if (isNaN(d.getTime())) return s
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function isExcelAttachedFile(fEntry: any): boolean {
  const name = String(fEntry?.file_name || '').toLowerCase()
  const url = String(fEntry?.file_url || '').toLowerCase()
  return /\.(xlsx|xls|csv|xlsm|xlsb)(\?|#|$)/i.test(name) || /\.(xlsx|xls|csv|xlsm|xlsb)(\?|#|$)/i.test(url)
}

function getAttachedFileViewHref(fEntry: any): string {
  const rawUrl = String(fEntry?.file_url || '').trim()
  if (!rawUrl) return '#'
  const name = String(fEntry?.file_name || '').toLowerCase()
  const isOfficeDoc =
    isExcelAttachedFile(fEntry) ||
    /\.(doc|docx|ppt|pptx)(\?|#|$)/i.test(name) ||
    /\.(doc|docx|ppt|pptx)(\?|#|$)/i.test(rawUrl.toLowerCase())

  if (isOfficeDoc && /^https?:\/\//i.test(rawUrl) && !/\.json(\?|#|$)/i.test(rawUrl)) {
    return `https://view.officeapps.live.com/op/view.aspx?src=${encodeURIComponent(rawUrl)}`
  }
  return rawUrl
}

function applyFilePriceToModalTarget(target: any, fEntry: ProductFileEntry) {
  if (!target || !fEntry) return
  if (fEntry.gia_von > 0) {
    target.Gia_tieu_chuan = fEntry.gia_von
    target._Gia_tieu_chuan_goc = fEntry.gia_von
    target._Gia_tieu_chuan_kho = fEntry.gia_von
  }
  if (fEntry.don_gia > 0) {
    target.Don_gia = fEntry.don_gia
    target._Don_gia_goc = fEntry.don_gia
    target._Don_gia_kho = fEntry.don_gia
  }
  if (fEntry.gia_nhap > 0) {
    target.gia_nhap = fEntry.gia_nhap
    target._gia_nhap_goc = fEntry.gia_nhap
    target._gia_nhap_kho = fEntry.gia_nhap
  }
  if (fEntry.don_vi_tien_te) target.Don_vi_tien_te = fEntry.don_vi_tien_te
  triggerToast(`Đã áp giá từ file "${fEntry.file_name}"`)
}

const quoteEditTieuChuanPct = computed(() => {
  if (!quoteEdit.value) return 0;
  const lp = donGiaLPKho(quoteEdit.value);
  const tc = toNum(quoteEdit.value.Gia_tieu_chuan, 0);
  if (!lp || lp === 0) return 0;
  return round2((1 - tc / lp) * 100);
});

function updateTieuChuanPct(val: number) {
  if (!quoteEdit.value) return;
  const lp = donGiaLPKho(quoteEdit.value);
  const nextTc = lp * (1 - val / 100);
  quoteEdit.value.Gia_tieu_chuan = nextTc;
  quoteEdit.value._Gia_tieu_chuan_goc = nextTc;
  quoteEdit.value._Gia_tieu_chuan_kho = nextTc;
  quoteEdit.value = { ...quoteEdit.value };
}

// KASPERSKY CALCULATOR
const showKasperskyCalculatorModal = ref(false)
const showKasperskyImageFullscreen = ref(false)
const listFileGiaOff = ref<any[]>([])
const selectedFileGiaOffIndex = ref(-1)

const previewImageLink = computed(() => {
  if (selectedFileGiaOffIndex.value >= 0 && listFileGiaOff.value[selectedFileGiaOffIndex.value]) {
    return listFileGiaOff.value[selectedFileGiaOffIndex.value][3] // link_file
  }
  return ''
})

const fetchFileGiaOffList = async () => {
  if (listFileGiaOff.value.length > 0) return
  try {
    const snap = await get(dbRef(database, 'file_gia_off'))
    const val = snap.val()
    if (val && typeof val === 'object') {
      const parseOffTime = (str: string) => {
        if (!str) return 0
        const s = String(str).trim()
        const m1 = s.match(/^(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?,?\s*(\d{1,2})\/(\d{1,2})\/(\d{4})$/)
        if (m1) return new Date(Number(m1[6]), Number(m1[5]) - 1, Number(m1[4]), Number(m1[1]), Number(m1[2]), Number(m1[3] || 0)).getTime()
        const m2 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?$/)
        if (m2) return new Date(Number(m2[3]), Number(m2[2]) - 1, Number(m2[1]), Number(m2[4]), Number(m2[5]), Number(m2[6] || 0)).getTime()
        const t = Date.parse(s)
        return isNaN(t) ? 0 : t
      }
      const entries = Object.entries(val).map(([k, v]: [string, any]) => {
        if (Array.isArray(v)) {
          return { row: [String(v[0] || k), String(v[1] || ''), String(v[2] || ''), String(v[3] || '')], ts: parseOffTime(String(v[1] || '')) }
        }
        const rawTime = String(v?.created_time ?? v?.Created_time ?? '')
        let displayTime = rawTime
        const tsNum = parseOffTime(rawTime)
        if (tsNum > 0 && rawTime.includes('GMT')) {
          const d = new Date(tsNum)
          const pad = (n: number) => String(n).padStart(2, '0')
          displayTime = `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`
        }
        return {
          row: [
            String(v?.id ?? v?.ID ?? k ?? ''),
            displayTime,
            String(v?.ten_file ?? v?.TEN_FILE ?? ''),
            String(v?.link_file ?? v?.LINK_FILE ?? '')
          ],
          ts: tsNum
        }
      })
      entries.sort((a, b) => a.ts - b.ts)
      const data = entries.map(e => e.row)
      listFileGiaOff.value = data
      if (data.length > 0) {
        selectedFileGiaOffIndex.value = data.length - 1
      }
    }
  } catch (err) {
    console.error('Lỗi khi fetch file_gia_off từ Firebase:', err)
  }
}

watch(showKasperskyCalculatorModal, (val) => {
  if (val) {
    fetchFileGiaOffList()
  }
})

const kaspProduct = ref<string>('')
const kaspLicenseType = ref<string>('')
const kaspUsersStr = ref('')
const kaspDuration = ref<number | string>('') // years

function openKasperskyCalculator() {
  kaspProduct.value = '';
  kaspUsersStr.value = '';
  kaspLicenseType.value = '';
  kaspDuration.value = '';

  if (userVolumeFilter.value) {
    kaspUsersStr.value = userVolumeFilter.value;
  }

  if (quoteEdit.value) {
    const typeStr = (quoteEdit.value.Ten_hang || '').toLowerCase();
    const moTa = (quoteEdit.value.Mo_ta_chung || '').toLowerCase();
    
    if (typeStr.includes('renewal') || moTa.includes('renewal')) {
      kaspLicenseType.value = 'Renewal Plus';
    } else if (typeStr.includes('base') || moTa.includes('base')) {
      kaspLicenseType.value = 'Base Plus';
    }
    
    const duration = quoteEdit.value.License_duration || '';
    const match = String(duration).match(/(\d+)/);
    if (match) {
      kaspDuration.value = parseInt(match[1], 10);
    }
  }
  
  showKasperskyCalculatorModal.value = true;
}
const kaspCalculatedOff = computed(() => {
  if (selectedFileGiaOffIndex.value === -1 || !kaspProduct.value || !kaspLicenseType.value || !kaspDuration.value || !kaspUsersStr.value || String(kaspUsersStr.value).trim() === '') {
    return null;
  }
  let baseOff = 0;
  
  const uCount = parseInt(String(kaspUsersStr.value), 10);
  const n = isNaN(uCount) ? 0 : uCount;
  
  let rangeStr = '';
  if (n < 50) rangeStr = '< 50 users';
  else if (n < 100) rangeStr = '50 - 99 users';
  else if (n < 150) rangeStr = '100 - 149 users';
  else if (n < 250) rangeStr = '150 - 249 users';
  else if (n < 500) rangeStr = '250 - 499 users';
  else rangeStr = '500 - 999 users';

  if (kaspProduct.value === 'NEXT Foundations / EDR Optimum') {
    if (kaspLicenseType.value === 'Base Plus') {
      if (rangeStr === '< 50 users') baseOff = 56;
      else if (rangeStr === '50 - 99 users') baseOff = 59;
      else if (rangeStr === '100 - 149 users') baseOff = 60;
      else if (rangeStr === '150 - 249 users') baseOff = 62;
      else if (rangeStr === '250 - 499 users') baseOff = 63;
      else if (rangeStr === '500 - 999 users') baseOff = 64;
    } else if (kaspLicenseType.value === 'Renewal Plus') {
      if (rangeStr === '< 50 users') baseOff = 55;
      else if (rangeStr === '50 - 99 users') baseOff = 58;
      else if (rangeStr === '100 - 149 users') baseOff = 59;
      else if (rangeStr === '150 - 249 users') baseOff = 61;
      else if (rangeStr === '250 - 499 users') baseOff = 62;
      else if (rangeStr === '500 - 999 users') baseOff = 63;
    }
  } else if (kaspProduct.value === 'XDR Optimum') {
    if (kaspLicenseType.value === 'Base Plus') {
      if (rangeStr === '< 50 users') baseOff = 67;
      else if (rangeStr === '50 - 99 users') baseOff = 70;
      else if (rangeStr === '100 - 149 users') baseOff = 71;
      else if (rangeStr === '150 - 249 users') baseOff = 72;
      else if (rangeStr === '250 - 499 users') baseOff = 73;
      else if (rangeStr === '500 - 999 users') baseOff = 74;
    } else if (kaspLicenseType.value === 'Renewal Plus') {
      if (rangeStr === '< 50 users') baseOff = 66;
      else if (rangeStr === '50 - 99 users') baseOff = 69;
      else if (rangeStr === '100 - 149 users') baseOff = 70;
      else if (rangeStr === '150 - 249 users') baseOff = 71;
      else if (rangeStr === '250 - 499 users') baseOff = 72;
      else if (rangeStr === '500 - 999 users') baseOff = 73;
    }
  }

  let durationBonus = 0;
  if (kaspDuration.value === 2) {
    durationBonus = 2;
  } else if (kaspDuration.value >= 3 && kaspDuration.value <= 5) {
    durationBonus = 3;
  }
  
  return baseOff + durationBonus;
})

const applyKaspOff = () => {
  if (kaspCalculatedOff.value === null) return;
  updateTieuChuanPct(kaspCalculatedOff.value)
  showKasperskyCalculatorModal.value = false
}

function openQuoteEdit(idx: number, focusField?: string) {
  const priceFocusFields = [
    'So_luong', 'Ti_gia', 'Gia_tieu_chuan', 'Gia_tieu_chuan_usd',
    'Don_gia', 'Don_gia_usd', 'gia_nhap', 'gia_nhap_usd',
    'muc_phan_tram_off', 'unit_price_kh', 'line_truoc_thue',
    'Thue_VAT', 'item_chenh_lech'
  ]
  if (idx < 0 && guideTempTableDemoActive.value && selectedItems.value.length === 0) {
    closeQuoteEditRaw()
    _adjustedFields.clear()
    quoteEditIdx.value = -1
    pendingQuoteEditFocusField.value = focusField || ''
    quoteEdit.value = createGuideDemoQuoteItem()
    activeQuoteEditTab.value = focusField && priceFocusFields.includes(focusField) ? 'price' : 'info'
    showQuoteEditModal.value = true
    return
  }
  const it = selectedItems.value[idx]
  if (!it) return
  closeQuoteEditRaw()
  withOriginalPriceFields(it)
  quoteEdit.value = JSON.parse(JSON.stringify(it))
  quoteEditIdx.value = idx
  pendingQuoteEditFocusField.value = focusField || ''

  if (focusField && priceFocusFields.includes(focusField)) {
    activeQuoteEditTab.value = 'price'
  } else {
    activeQuoteEditTab.value = 'info'
  }

  // Phát hiện Don_gia / gia_hardware / muc_phan_tram_off đã có chênh lệch trước đó
  // → giữ lại chênh lệch, không cho saveQuoteEdit ghi đè _goc
  _adjustedFields.clear()
  if (getGocNumber(it, '_Don_gia_goc', toNum(it.Don_gia, 0)) !== toNum(it.Don_gia, 0)) {
    _adjustedFields.add('Don_gia')
  }
  if (getGocNumber(it, '_gia_hardware_goc', toNum(it.gia_hardware, 0)) !== toNum(it.gia_hardware, 0)) {
    _adjustedFields.add('gia_hardware')
  }
  if (getGocNumber(it, '_muc_phan_tram_off_goc', toNum(it.muc_phan_tram_off, 0)) !== toNum(it.muc_phan_tram_off, 0)) {
    _adjustedFields.add('muc_phan_tram_off')
  }

  showQuoteEditModal.value = true
}

function closeQuoteEdit() {
  if ((quoteEdit.value as any)?._isGuideDemo && guideStashedRealQuoteEdit) {
    restoreStashedRealQuoteEdit()
    return
  }
  showQuoteEditModal.value = false
  quoteEdit.value = null
  quoteEditIdx.value = -1
}

watch(showQuoteEditModal, (val) => {
  console.log('[watch showQuoteEditModal] val=', val, 'pendingFocusField=', pendingQuoteEditFocusField.value)
  if (val && pendingQuoteEditFocusField.value) {
    const field = pendingQuoteEditFocusField.value
    pendingQuoteEditFocusField.value = ''
