      }
      const input = (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.getAttribute('contenteditable') === 'true')
        ? el as HTMLInputElement
        : el.querySelector('.editor-content, input, textarea') as HTMLInputElement | null
      console.log('[watch showQuoteEditModal] input element=', input?.tagName, 'readonly=', input?.readOnly)
      if (input) {
        input.focus()
        if (typeof input.select === 'function') input.select()
        input.scrollIntoView({ block: 'center', behavior: 'smooth' })
      }
    }
    setTimeout(tryFocus, 200)
  }
})

