export type PreviewFormatMode = 'pdf' | 'excel' | 'word' | 'png' | 'html'
const previewFormatMode = ref<PreviewFormatMode>('pdf')
const isPreviewDirectEditMode = ref<boolean>(true)

// Tỷ lệ chia cột Trái / Phải trong modal Xuất báo giá (cho phép kéo thanh ngăn cách)
const previewSplitLeftPct = ref<number>(40)
const isResizingPreviewSplit = ref<boolean>(false)

// Kích thước trang xem trước tùy chỉnh (kéo rộng / cao khung trang bản in)
const previewSheetCustomWidth = ref<number | null>(null)
const previewSheetCustomHeight = ref<number | null>(null)

// Lưu nội dung & style chỉnh sửa trực tiếp trên từng ô của bản Xem trước
const previewCellOverridesMap: Record<string, PreviewCellOverride> = {}
const previewColWidthOverrides = reactive<Record<number, number>>({})
const previewRowHeightOverrides = reactive<Record<number, number>>({})
const previewOverrideCount = ref<number>(0)
const previewRenderTick = ref<number>(0)

// Trạng thái ô đang chọn trên bản Xem trước
const activePreviewCellKey = ref<string>('')
const activePreviewCellAddr = ref<string>('')
const activePreviewCellFormula = ref<string>('')
const activePreviewCellText = ref<string>('')
const activePreviewColIndex = ref<number>(0)
const activePreviewExcelRow = ref<number>(0)
const activePreviewColWidth = ref<number>(0)
const activePreviewRowHeight = ref<number>(0)
const activePreviewCellColor = ref<string>('#0f172a')
const activePreviewCellBgColor = ref<string>('#ffffff')

const previewFormatTabs: { id: PreviewFormatMode; label: string; badge: string; desc: string }[] = [
  { id: 'pdf', label: 'PDF / Bản in', badge: '.pdf', desc: 'Bố cục trang giấy chuẩn A4, hỗ trợ sửa trực tiếp và kéo rộng cột / cao dòng trước khi in hoặc lưu PDF' },
  { id: 'excel', label: 'Excel', badge: '.xlsx', desc: ' Giao diện bảng tính có lưới cột A, B, C... & thanh công thức fx — kéo biên cột/dòng để chỉnh độ rộng cột & chiều cao dòng xuất ra Excel' },
  { id: 'word', label: 'Word', badge: '.doc', desc: 'Trang văn bản Microsoft Word có thước lề trên — cho phép click sửa chữ, định dạng đậm/nghiêng/màu và kéo bảng trực tiếp' },
  { id: 'png', label: 'Ảnh PNG', badge: '.png', desc: 'Khung chụp ảnh độ phân giải cao (2x Retina) — mọi chỉnh sửa chữ và kích thước cột/dòng đều giữ nguyên khi xuất ảnh' },
  { id: 'html', label: 'Web HTML', badge: '.html', desc: 'Giao diện trình duyệt độc lập — cho phép chỉnh sửa nội dung, màu sắc và độ rộng cột trước khi tải file .html' }
]

const currentPreviewFormatInfo = computed(() => {
  return previewFormatTabs.find(t => t.id === previewFormatMode.value) || previewFormatTabs[0]
})

function excelColLetterFromNumber(colNum: number): string {
  let n = Math.max(1, colNum)
  let str = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    str = String.fromCharCode(65 + rem) + str
    n = Math.floor((n - 1) / 26)
  }
  return str
}

const previewGridColHeaders = computed(() => {
  const tpl = activePrintTemplate.value
  const totalCols = Math.max(tpl?.so_cot || 9, 1)
  const effectiveWidths: number[] = []
  for (let c = 1; c <= totalCols; c++) {
    const baseW = Number(tpl?.col_widths?.[c] ?? 100)
    const ovW = previewColWidthOverrides[c]
    effectiveWidths.push(ovW !== undefined ? Math.max(0, ovW) : Math.max(0, baseW))
  }
  const totalW = Math.max(1, effectiveWidths.reduce((acc, w) => acc + w, 0))
  return effectiveWidths.map((w, idx) => {
    const colIdx = idx + 1
    return {
      colIdx,
      letter: excelColLetterFromNumber(colIdx),
      widthPx: Math.round(w),
      pct: Number(((w / totalW) * 100).toFixed(2))
    }
  })
})

const previewSheetPaddingPx = computed(() => {
  return Number(activePrintTemplate.value?.cau_hinh_trang?.padding_trang ?? 14)
})

interface PreviewRowHeaderItem {
  excelRow: number
  gridRow: number
  heightPx: number
}
const previewGridRowHeaders = ref<PreviewRowHeaderItem[]>([])
const previewTableTopOffsetPx = ref<number>(14)

function syncPreviewRowRulerMetrics() {
  const container = (showPrintPreviewZoomModal.value && zoomModalPrintPreviewRef.value)
    ? zoomModalPrintPreviewRef.value
    : modalPrintPreviewRef.value
  if (!container) return

  const imgs = Array.from(container.querySelectorAll('img'))
  for (const img of imgs) {
    if (!img.complete && !img.dataset.pvLoadBound) {
      img.dataset.pvLoadBound = '1'
      img.addEventListener('load', () => {
        syncPreviewRowRulerMetrics()
      }, { once: true })
    }
  }

  const tableEl = container.querySelector('table.nts-grid-table') as HTMLElement | null
  if (!tableEl) {
    previewGridRowHeaders.value = []
    return
  }

  const sheetRect = container.getBoundingClientRect()
  const tableRect = tableEl.getBoundingClientRect()
  const scale = sheetRect.width > 0 && container.offsetWidth > 0
    ? sheetRect.width / container.offsetWidth
    : 1
  const topOffset = Math.max(0, Math.round((tableRect.top - sheetRect.top) / (scale || 1)))
  previewTableTopOffsetPx.value = topOffset

  const trs = Array.from(tableEl.querySelectorAll('tr[data-excel-row]')) as HTMLElement[]
  const items: PreviewRowHeaderItem[] = []
  for (const tr of trs) {
    const excelRow = Number(tr.getAttribute('data-excel-row') || 0)
    if (!excelRow) continue
    const h = tr.offsetHeight
    if (h <= 0 || window.getComputedStyle(tr).display === 'none') continue
    items.push({
      excelRow,
      gridRow: Number(tr.getAttribute('data-grid-row') || 0),
      heightPx: Math.max(8, Math.round(h))
    })
  }
  previewGridRowHeaders.value = items
  if (activePreviewExcelRow.value > 0) {
    const found = items.find(r => r.excelRow === activePreviewExcelRow.value)
    if (found) {
      activePreviewRowHeight.value = previewRowHeightOverrides[activePreviewExcelRow.value] || found.heightPx
    }
  }
}

function selectPreviewRowFromRuler(excelRow: number) {
  activePreviewExcelRow.value = excelRow
  const found = previewGridRowHeaders.value.find(r => r.excelRow === excelRow)
  activePreviewRowHeight.value = previewRowHeightOverrides[excelRow] || (found ? found.heightPx : 28)

  const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
  for (const c of containers) {
    c.querySelectorAll('tr.is-active-preview-row').forEach(el => el.classList.remove('is-active-preview-row'))
    const tr = c.querySelector(`tr[data-excel-row="${excelRow}"]`) as HTMLElement | null
    if (tr) {
      tr.classList.add('is-active-preview-row')
      const firstTd = (tr.querySelector('td.preview-interactive-td') || tr.querySelector('td')) as HTMLElement | null
      if (firstTd && c === (showPrintPreviewZoomModal.value ? zoomModalPrintPreviewRef.value : modalPrintPreviewRef.value)) {
        const key = firstTd.getAttribute('data-edit-key') || ''
        const addr = firstTd.getAttribute('data-excel-addr') || ''
        const formula = firstTd.getAttribute('data-excel-formula') || ''
        const targetCol = Number(firstTd.getAttribute('data-target-col') || firstTd.getAttribute('data-grid-col') || 1)
        if (key) activePreviewCellKey.value = key
        if (addr) activePreviewCellAddr.value = addr
        activePreviewCellFormula.value = formula
        activePreviewColIndex.value = targetCol
        const hdr = previewGridColHeaders.value.find(h => h.colIdx === targetCol)
        if (hdr) activePreviewColWidth.value = hdr.widthPx
      }
    }
  }
}

function recomputePreviewOverrideCount() {
  const cellCount = Object.keys(previewCellOverridesMap).length
  const colCount = Object.keys(previewColWidthOverrides).length
  const rowCount = Object.keys(previewRowHeightOverrides).length
  const sheetSizeCount = (previewSheetCustomWidth.value || previewSheetCustomHeight.value) ? 1 : 0
  previewOverrideCount.value = cellCount + colCount + rowCount + sheetSizeCount
}

function resetAllPreviewOverrides() {
  for (const k of Object.keys(previewCellOverridesMap)) {
    delete previewCellOverridesMap[k]
  }
  for (const k of Object.keys(previewColWidthOverrides)) {
    delete previewColWidthOverrides[Number(k)]
  }
  for (const k of Object.keys(previewRowHeightOverrides)) {
    delete previewRowHeightOverrides[Number(k)]
  }
  previewSheetCustomWidth.value = null
  previewSheetCustomHeight.value = null
  activePreviewCellKey.value = ''
  activePreviewCellAddr.value = ''
  activePreviewCellFormula.value = ''
  activePreviewCellText.value = ''
  activePreviewColIndex.value = 0
  activePreviewExcelRow.value = 0
  activePreviewColWidth.value = 0
  activePreviewRowHeight.value = 0
  recomputePreviewOverrideCount()
  previewRenderTick.value++
  nextTick(() => syncPreviewRowRulerMetrics())
}

function resetActivePreviewCellOverride() {
  const key = activePreviewCellKey.value
  if (key && previewCellOverridesMap[key]) {
    delete previewCellOverridesMap[key]
  }
  if (activePreviewColIndex.value && previewColWidthOverrides[activePreviewColIndex.value]) {
    delete previewColWidthOverrides[activePreviewColIndex.value]
  }
  if (activePreviewExcelRow.value && previewRowHeightOverrides[activePreviewExcelRow.value]) {
    delete previewRowHeightOverrides[activePreviewExcelRow.value]
  }
  recomputePreviewOverrideCount()
  previewRenderTick.value++
  nextTick(() => syncPreviewRowRulerMetrics())
}

function syncPreviewColumnDomWidths(colIdx: number, newWidthPx: number) {
  previewColWidthOverrides[colIdx] = Math.max(24, Math.round(newWidthPx))
  recomputePreviewOverrideCount()
  const headers = previewGridColHeaders.value
  const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
  for (const container of containers) {
    headers.forEach(h => {
      const colEl = container.querySelector(`col[data-col-idx="${h.colIdx}"]`) as HTMLElement | null
      if (colEl) {
        colEl.style.width = `${h.pct}%`
      }
    })
  }
  syncPreviewRowRulerMetrics()
}

function syncPreviewRowDomHeight(excelRow: number, newHeightPx: number) {
  const clamped = Math.max(8, Math.min(400, Math.round(newHeightPx)))
  previewRowHeightOverrides[excelRow] = clamped
  recomputePreviewOverrideCount()
  const clipMaxH = Math.max(6, clamped - (clamped < 26 ? 2 : 8))
  const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
  let measuredAfter = clamped
  for (const container of containers) {
    const trEl = container.querySelector(`tr[data-excel-row="${excelRow}"]`) as HTMLElement | null
    if (trEl) {
      trEl.style.height = `${clamped}px`
    }
    const tds = container.querySelectorAll(`tr[data-excel-row="${excelRow}"] > td`)
    tds.forEach(tdEl => {
      const td = tdEl as HTMLElement
      td.style.height = `${clamped}px`
      const img = td.querySelector('img') as HTMLElement | null
      if (img) {
        img.style.height = `${Math.max(10, clamped - 6)}px`
      } else {
        if (clamped < 26) {
          td.style.paddingTop = '0px'
          td.style.paddingBottom = '0px'
          td.style.lineHeight = `${Math.max(8, clamped - 2)}px`
        } else {
          td.style.paddingTop = '4px'
          td.style.paddingBottom = '4px'
          td.style.lineHeight = ''
        }
        let clipDiv = td.querySelector(':scope > .pv-cell-clip') as HTMLElement | null
        if (!clipDiv && td.innerHTML.trim() !== '') {
          const wrapper = document.createElement('div')
          wrapper.className = 'pv-cell-clip'
          wrapper.innerHTML = td.innerHTML
          td.innerHTML = ''
          td.appendChild(wrapper)
          clipDiv = wrapper
        }
        if (clipDiv) {
          clipDiv.style.maxHeight = `${clipMaxH}px`
          clipDiv.style.overflow = 'hidden'
        }
      }
    })
    if (trEl && trEl.offsetHeight > 0) {
      measuredAfter = trEl.offsetHeight
    }
  }
  const rItem = previewGridRowHeaders.value.find(r => r.excelRow === excelRow)
  if (rItem) {
    rItem.heightPx = measuredAfter
  }
}

function onActivePreviewColWidthInput(val: number) {
  const colIdx = activePreviewColIndex.value || 1
  if (!Number.isFinite(val) || val < 24) return
  activePreviewColWidth.value = Math.round(val)
  syncPreviewColumnDomWidths(colIdx, val)
}

function onActivePreviewRowHeightInput(val: number) {
  const rowIdx = activePreviewExcelRow.value || 1
  if (!Number.isFinite(val) || val < 8) return
  activePreviewRowHeight.value = Math.round(val)
  syncPreviewRowDomHeight(rowIdx, val)
}

function stepActivePreviewColWidth(deltaPx: number) {
  const colIdx = activePreviewColIndex.value || 1
  if (!activePreviewColIndex.value) activePreviewColIndex.value = colIdx
  const hdr = previewGridColHeaders.value.find(h => h.colIdx === colIdx)
  const baseW = activePreviewColWidth.value || (hdr ? hdr.widthPx : 90)
  const nextW = Math.max(24, Math.min(800, Math.round(baseW + deltaPx)))
  activePreviewColWidth.value = nextW
  syncPreviewColumnDomWidths(colIdx, nextW)
  previewRenderTick.value++
}

function stepActivePreviewRowHeight(deltaPx: number) {
  const rowIdx = activePreviewExcelRow.value || 1
  if (!activePreviewExcelRow.value) activePreviewExcelRow.value = rowIdx
  const rHdr = previewGridRowHeaders.value.find(r => r.excelRow === rowIdx)
  const baseH = activePreviewRowHeight.value || previewRowHeightOverrides[rowIdx] || (rHdr ? rHdr.heightPx : 28)
  const nextH = Math.max(8, Math.min(400, Math.round(baseH + deltaPx)))
  activePreviewRowHeight.value = nextH
  syncPreviewRowDomHeight(rowIdx, nextH)
  previewRenderTick.value++
}

function startPreviewColResize(e: MouseEvent, colIdx: number) {
  e.preventDefault()
  e.stopPropagation()
  const startX = e.clientX
  const hdr = previewGridColHeaders.value.find(h => h.colIdx === colIdx)
  const startW = hdr ? hdr.widthPx : (previewColWidthOverrides[colIdx] || 85)
  activePreviewColIndex.value = colIdx
  activePreviewColWidth.value = startW
  document.body.style.cursor = 'col-resize'
  document.body.style.userSelect = 'none'

  const onMove = (moveEvt: MouseEvent) => {
    const deltaX = moveEvt.clientX - startX
    const nextW = Math.max(24, Math.round(startW + deltaX))
    activePreviewColWidth.value = nextW
    syncPreviewColumnDomWidths(colIdx, nextW)
  }

  const onUp = () => {
    document.body.style.cursor = ''
    document.body.style.userSelect = ''
    window.removeEventListener('mousemove', onMove)
    window.removeEventListener('mouseup', onUp)
    previewRenderTick.value++
    nextTick(() => syncPreviewRowRulerMetrics())
  }

  window.addEventListener('mousemove', onMove)
  window.addEventListener('mouseup', onUp)
}

function startPreviewRowResize(e: MouseEvent, excelRow: number, trEl?: HTMLElement | null) {
  e.preventDefault()
  e.stopPropagation()
  const startY = e.clientY
  const rHdr = previewGridRowHeaders.value.find(r => r.excelRow === excelRow)
  const measuredH = trEl ? trEl.offsetHeight : (rHdr ? rHdr.heightPx : 28)
  const startH = previewRowHeightOverrides[excelRow] || Math.max(8, Math.round(measuredH))
  activePreviewExcelRow.value = excelRow
  activePreviewRowHeight.value = startH
  document.body.style.cursor = 'row-resize'
  document.body.style.userSelect = 'none'

  const onMove = (moveEvt: MouseEvent) => {
    const deltaY = moveEvt.clientY - startY
    const nextH = Math.max(8, Math.min(400, Math.round(startH + deltaY)))
    activePreviewRowHeight.value = nextH
    syncPreviewRowDomHeight(excelRow, nextH)
  }

  const onUp = () => {
    document.body.style.cursor = ''
    document.body.style.userSelect = ''
    window.removeEventListener('mousemove', onMove)
    window.removeEventListener('mouseup', onUp)
    previewRenderTick.value++
    nextTick(() => syncPreviewRowRulerMetrics())
  }

  window.addEventListener('mousemove', onMove)
  window.addEventListener('mouseup', onUp)
}

function startPreviewSheetSizeResize(e: MouseEvent, mode: 'width' | 'height' | 'both', sheetEl: HTMLElement | null) {
  if (!sheetEl) return
  e.preventDefault()
  e.stopPropagation()
  const rect = sheetEl.getBoundingClientRect()
  const startX = e.clientX
  const startY = e.clientY
  const startW = previewSheetCustomWidth.value || Math.round(rect.width)
  const startH = previewSheetCustomHeight.value || Math.round(rect.height)
  document.body.style.cursor = mode === 'width' ? 'ew-resize' : mode === 'height' ? 'ns-resize' : 'nwse-resize'
  document.body.style.userSelect = 'none'

  const onMove = (moveEvt: MouseEvent) => {
    if (mode === 'width' || mode === 'both') {
      const nextW = Math.max(480, Math.min(2200, Math.round(startW + (moveEvt.clientX - startX))))
      previewSheetCustomWidth.value = nextW
    }
    if (mode === 'height' || mode === 'both') {
      const nextH = Math.max(320, Math.min(4000, Math.round(startH + (moveEvt.clientY - startY))))
      previewSheetCustomHeight.value = nextH
    }
    recomputePreviewOverrideCount()
    syncPreviewRowRulerMetrics()
  }

  const onUp = () => {
    document.body.style.cursor = ''
    document.body.style.userSelect = ''
    window.removeEventListener('mousemove', onMove)
    window.removeEventListener('mouseup', onUp)
    nextTick(() => syncPreviewRowRulerMetrics())
  }

  window.addEventListener('mousemove', onMove)
  window.addEventListener('mouseup', onUp)
}

function startPreviewSplitResize(e: MouseEvent) {
  e.preventDefault()
  e.stopPropagation()
  const workspaceEl = (e.currentTarget as HTMLElement)?.parentElement
  if (!workspaceEl) return
  const rect = workspaceEl.getBoundingClientRect()
  isResizingPreviewSplit.value = true
  document.body.style.cursor = 'col-resize'
  document.body.style.userSelect = 'none'

  const onMove = (moveEvt: MouseEvent) => {
    const relX = moveEvt.clientX - rect.left
    const pct = (relX / Math.max(1, rect.width)) * 100
    previewSplitLeftPct.value = Math.max(24, Math.min(68, Math.round(pct * 10) / 10))
    syncPreviewRowRulerMetrics()
  }

  const onUp = () => {
    isResizingPreviewSplit.value = false
    document.body.style.cursor = ''
    document.body.style.userSelect = ''
    window.removeEventListener('mousemove', onMove)
    window.removeEventListener('mouseup', onUp)
    nextTick(() => syncPreviewRowRulerMetrics())
  }

  window.addEventListener('mousemove', onMove)
  window.addEventListener('mouseup', onUp)
}

function handlePreviewSheetMouseMove(e: MouseEvent) {
  const sheetEl = e.currentTarget as HTMLElement | null
  if (!sheetEl) return
  const target = e.target as HTMLElement | null
  const td = target?.closest('table.nts-grid-table td') as HTMLElement | null
  sheetEl.querySelectorAll('tr.is-row-resize-hover').forEach(el => el.classList.remove('is-row-resize-hover'))
  if (!td) {
    sheetEl.style.cursor = ''
    return
  }
  const rect = td.getBoundingClientRect()
  const nearRight = rect.right - e.clientX <= 7 && rect.right - e.clientX >= -2
  const nearBottom = rect.bottom - e.clientY <= 7 && rect.bottom - e.clientY >= -2
  if (nearRight) {
    td.style.cursor = 'col-resize'
  } else if (nearBottom) {
    td.style.cursor = 'row-resize'
    const tr = td.closest('tr[data-excel-row]')
    if (tr) tr.classList.add('is-row-resize-hover')
  } else {
    td.style.cursor = (isPreviewDirectEditMode.value && td.classList.contains('preview-interactive-td')) ? 'text' : 'pointer'
  }
}

function handlePreviewSheetMouseDown(e: MouseEvent) {
  const target = e.target as HTMLElement | null
  const td = target?.closest('table.nts-grid-table td') as HTMLElement | null
  if (!td) return
  const rect = td.getBoundingClientRect()
  const nearRight = rect.right - e.clientX <= 7 && rect.right - e.clientX >= -2
  const nearBottom = rect.bottom - e.clientY <= 7 && rect.bottom - e.clientY >= -2
  if (nearRight) {
    const targetCol = Number(td.getAttribute('data-target-col') || td.getAttribute('data-grid-col') || 1)
    startPreviewColResize(e, targetCol)
    return
  }
  if (nearBottom) {
    const tr = td.closest('tr[data-excel-row]') as HTMLElement | null
    const excelRow = Number(tr?.getAttribute('data-excel-row') || 1)
    startPreviewRowResize(e, excelRow, tr)
  }
}

function extractCleanPreviewCellHtml(td: HTMLElement): string {
  const clipEl = td.querySelector(':scope > .pv-cell-clip') as HTMLElement | null
  return clipEl ? clipEl.innerHTML : td.innerHTML
}

function handlePreviewSheetClick(e: MouseEvent) {
  const target = e.target as HTMLElement | null
  if (!target) return
  const anyTd = target.closest('table.nts-grid-table td') as HTMLElement | null
  if (!anyTd) return

  const tr = anyTd.closest('tr[data-excel-row]') as HTMLElement | null
  const excelRow = Number(tr?.getAttribute('data-excel-row') || 1)
  const targetCol = Number(anyTd.getAttribute('data-target-col') || anyTd.getAttribute('data-grid-col') || 1)
  activePreviewColIndex.value = targetCol
  activePreviewExcelRow.value = excelRow
  const hdr = previewGridColHeaders.value.find(h => h.colIdx === targetCol)
  activePreviewColWidth.value = hdr ? hdr.widthPx : Math.round(anyTd.offsetWidth)
  activePreviewRowHeight.value = previewRowHeightOverrides[excelRow] || Math.round((tr || anyTd).offsetHeight)

  const container = anyTd.closest('.print-preview-sheet')
  if (container) {
    container.querySelectorAll('tr.is-active-preview-row').forEach(el => el.classList.remove('is-active-preview-row'))
    if (tr) tr.classList.add('is-active-preview-row')
  }

  const td = anyTd.classList.contains('preview-interactive-td') ? anyTd : null
  if (!td) return

  if (container) {
    container.querySelectorAll('td.is-active-preview-cell').forEach(el => {
      if (el !== td) {
        el.classList.remove('is-active-preview-cell')
        el.removeAttribute('contenteditable')
      }
    })
  }
  td.classList.add('is-active-preview-cell')

  const key = td.getAttribute('data-edit-key') || ''
  const addr = td.getAttribute('data-excel-addr') || ''
  const formula = td.getAttribute('data-excel-formula') || ''

  activePreviewCellKey.value = key
  activePreviewCellAddr.value = addr
  activePreviewCellFormula.value = formula
  activePreviewCellText.value = (td.innerText || '').replace(/\r\n/g, '\n')

  if (isPreviewDirectEditMode.value && td.getAttribute('contenteditable') !== 'true') {
    td.setAttribute('contenteditable', 'true')
    td.setAttribute('spellcheck', 'false')
    td.focus()
  }
}

function handlePreviewSheetFocusIn(e: FocusEvent) {
  const target = e.target as HTMLElement | null
  if (!target) return
  const td = target.closest('td.preview-interactive-td') as HTMLElement | null
  if (!td) return
  if (isPreviewDirectEditMode.value && td.getAttribute('contenteditable') !== 'true') {
    td.setAttribute('contenteditable', 'true')
    td.setAttribute('spellcheck', 'false')
  }
}

function handlePreviewSheetInput(e: Event) {
  const target = e.target as HTMLElement | null
  if (!target) return
  const td = target.closest('td.preview-interactive-td') as HTMLElement | null
  if (!td) return
  const key = td.getAttribute('data-edit-key') || ''
  if (!key) return

  const newText = (td.innerText || '').replace(/\r\n/g, '\n')
  const newHtml = extractCleanPreviewCellHtml(td)
  activePreviewCellText.value = newText

  const existing = previewCellOverridesMap[key] || {}
  previewCellOverridesMap[key] = {
    ...existing,
    text: newText,
    html: newHtml
  }
  recomputePreviewOverrideCount()
  syncPreviewRowRulerMetrics()
}

function handlePreviewSheetBlur(e: FocusEvent) {
  const target = e.target as HTMLElement | null
  if (!target) return
  const td = target.closest('td.preview-interactive-td') as HTMLElement | null
  if (!td) return
  const key = td.getAttribute('data-edit-key') || ''
  if (key && previewCellOverridesMap[key]) {
    previewCellOverridesMap[key].text = (td.innerText || '').replace(/\r\n/g, '\n')
    previewCellOverridesMap[key].html = extractCleanPreviewCellHtml(td)
  }
  td.removeAttribute('contenteditable')
  syncPreviewRowRulerMetrics()
}

function onFormulaBarTextInput(newVal: string) {
  activePreviewCellText.value = newVal
  const key = activePreviewCellKey.value
  if (!key) return

  const htmlEscaped = newVal
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>')

  const existing = previewCellOverridesMap[key] || {}
  previewCellOverridesMap[key] = {
    ...existing,
    text: newVal,
    html: htmlEscaped
  }
  recomputePreviewOverrideCount()

  const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
  for (const c of containers) {
    const cellEl = c.querySelector(`td[data-edit-key="${key}"]`) as HTMLElement | null
    if (cellEl) {
      cellEl.innerHTML = htmlEscaped
    }
  }
}

function applyStyleToActivePreviewCell(action: 'bold' | 'italic' | 'underline' | 'align-left' | 'align-center' | 'align-right' | 'font-inc' | 'font-dec' | 'color' | 'bg', colorVal?: string) {
  const key = activePreviewCellKey.value
  if (!key) return

  const existing: PreviewCellOverride = { ...(previewCellOverridesMap[key] || {}) }
  const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
  const firstEl = containers.map(c => c.querySelector(`td[data-edit-key="${key}"]`) as HTMLElement | null).find(Boolean)

  if (action === 'bold') {
    const curBold = existing.bold !== undefined ? existing.bold : (firstEl ? Number(window.getComputedStyle(firstEl).fontWeight) >= 600 : false)
    existing.bold = !curBold
  } else if (action === 'italic') {
    const curItalic = existing.italic !== undefined ? existing.italic : (firstEl ? window.getComputedStyle(firstEl).fontStyle === 'italic' : false)
    existing.italic = !curItalic
  } else if (action === 'underline') {
    const curUnder = existing.underline !== undefined ? existing.underline : (firstEl ? window.getComputedStyle(firstEl).textDecorationLine.includes('underline') : false)
    existing.underline = !curUnder
  } else if (action === 'align-left') {
    existing.align = 'left'
  } else if (action === 'align-center') {
    existing.align = 'center'
  } else if (action === 'align-right') {
    existing.align = 'right'
  } else if (action === 'font-inc' || action === 'font-dec') {
    const curPt = existing.fontSizePt || (firstEl ? Math.round(parseFloat(window.getComputedStyle(firstEl).fontSize || '13') * 0.75) : 10)
    existing.fontSizePt = Math.max(7, Math.min(28, curPt + (action === 'font-inc' ? 1 : -1)))
  } else if (action === 'color' && colorVal) {
    existing.color = colorVal
    activePreviewCellColor.value = colorVal
  } else if (action === 'bg' && colorVal) {
    existing.bgColor = colorVal
    activePreviewCellBgColor.value = colorVal
  }

  previewCellOverridesMap[key] = existing
  recomputePreviewOverrideCount()

  for (const c of containers) {
    const td = c.querySelector(`td[data-edit-key="${key}"]`) as HTMLElement | null
    if (!td) continue
    if (existing.bold !== undefined) td.style.fontWeight = existing.bold ? '700' : '400'
    if (existing.italic !== undefined) td.style.fontStyle = existing.italic ? 'italic' : 'normal'
    if (existing.underline !== undefined) td.style.textDecoration = existing.underline ? 'underline' : 'none'
    if (existing.align) td.style.textAlign = existing.align
    if (existing.fontSizePt) td.style.fontSize = `${existing.fontSizePt}pt`
    if (existing.color) td.style.color = existing.color
    if (existing.bgColor) td.style.backgroundColor = existing.bgColor
  }
}

watch(isPreviewDirectEditMode, (enabled) => {
  if (!enabled) {
    const containers = [modalPrintPreviewRef.value, zoomModalPrintPreviewRef.value].filter(Boolean) as HTMLElement[]
    for (const c of containers) {
      c.querySelectorAll('td[contenteditable="true"]').forEach(el => {
        el.removeAttribute('contenteditable')
      })
    }
  }
})

async function loadPrintTemplates() {
  const list = await fetchAndSyncPrintTemplates()
  printTemplates.value = list
  if (!selectedPrintTemplateId.value || !list.some(t => t.id === selectedPrintTemplateId.value)) {
    const def = list.find(t => t.mac_dinh) || list[0]
    if (def) selectedPrintTemplateId.value = def.id
  }
  const validTicked = selectedPrintTemplateIds.value.filter(id => list.some(t => t.id === id))
  if (validTicked.length > 0) {
    selectedPrintTemplateIds.value = validTicked
  } else if (selectedPrintTemplateId.value) {
    selectedPrintTemplateIds.value = [selectedPrintTemplateId.value]
  }
}

const activePrintTemplate = computed<PrintTemplateConfig | null>(() => {
  if (!printTemplates.value.length) return null
  return (
    printTemplates.value.find(t => t.id === selectedPrintTemplateId.value) ||
    printTemplates.value.find(t => t.mac_dinh) ||
    printTemplates.value[0] ||
    null
  )
})

function isPrintTemplateTicked(id: string): boolean {
  return selectedPrintTemplateIds.value.includes(id)
}

function toggleTickPrintTemplate(id: string) {
  const idx = selectedPrintTemplateIds.value.indexOf(id)
  if (idx >= 0) {
    selectedPrintTemplateIds.value = selectedPrintTemplateIds.value.filter(x => x !== id)
    if (selectedPrintTemplateId.value === id && selectedPrintTemplateIds.value.length > 0) {
      selectedPrintTemplateId.value = selectedPrintTemplateIds.value[0]
    }
  } else {
    selectedPrintTemplateIds.value = [...selectedPrintTemplateIds.value, id]
    selectedPrintTemplateId.value = id
  }
}

const isAllPrintTemplatesTicked = computed<boolean>(() => {
  return (
    printTemplates.value.length > 0 &&
    printTemplates.value.every(t => selectedPrintTemplateIds.value.includes(t.id))
  )
})

function toggleSelectAllPrintTemplates() {
  if (isAllPrintTemplatesTicked.value) {
    selectedPrintTemplateIds.value = []
  } else {
    selectedPrintTemplateIds.value = printTemplates.value.map(t => t.id)
    if (!selectedPrintTemplateId.value && printTemplates.value[0]) {
      selectedPrintTemplateId.value = printTemplates.value[0].id
    }
  }
}

const selectedPrintTemplatesList = computed<PrintTemplateConfig[]>(() => {
  if (!printTemplates.value.length) return []
  const ticked = printTemplates.value.filter(t => selectedPrintTemplateIds.value.includes(t.id))
  if (ticked.length > 0) return ticked
  return activePrintTemplate.value ? [activePrintTemplate.value] : []
})

function getPrintTemplateFileSuffix(tpl: PrintTemplateConfig): string {
  if (tpl.id === 'MINTL_CHUAN_NTS') return 'BaoGiaKhach'
  if (tpl.id === 'MINTL_DOI_CHIEU_3_GIA' || isThreePriceComparisonTemplate(tpl)) return 'DoiChieu3Gia'
  if (tpl.id === 'MINTL_HOP_DONG' || isContractPriceTemplate(tpl)) return 'BaoGiaHopDong'
  if (tpl.id === 'MINTL_LIST_PRICE' || isListPriceTemplate(tpl)) return 'BaoGiaListPrice'
  if (tpl.id === 'MINTL_DAI_LY') return 'BaoGiaDaiLy'
  const raw = String(tpl.ten_mau || tpl.id || 'MauIn')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
  return raw || 'MauIn'
}

function getTemplateExportFileName(baseName: string, tpl: PrintTemplateConfig, totalSelected: number): string {
  if (totalSelected <= 1) return baseName
  return `${baseName}_${getPrintTemplateFileSuffix(tpl)}`
}

function buildCurrentQuoteExportContext(): QuoteExportContext {
  const isUsdExport = quoteCurrency.value === 'USD'
  const contractRows: QuoteExportRowItem[] = quoteRowsWithSTT.value.map((r: any) => {
    if (r.type === 'group') {
      return {
        type: 'group',
        roman: r.roman,
        title: r.title,
        supplier: r.supplier || ''
      }
    }
    const i = r.item
    const tg = toNum(i.Ti_gia, 1) || 1
    const donGiaVND = unitPrice(i)
    const truoc = lineTruocThue(i)
    const vat = lineVAT(i)
    const sau = lineSauThue(i)
    const lpVND = listPriceVndKho(i, true)
    const stdVND = standardPrice(i)
    const nhapVND = giaNhapVnd(i)

    return {
      type: 'item',
      stt: r.stt,
      item: i,
      listPrice: isUsdExport ? round2(lpVND / tg) : Number(lpVND) || 0,
      giaTieuChuan: isUsdExport ? round2(stdVND / tg) : Number(stdVND) || 0,
      giaNhap: isUsdExport ? round2(nhapVND / tg) : Number(nhapVND) || 0,
      pctOffHang: displayGiaTieuChuanPct(i),
      pctOff: toNum(i.muc_phan_tram_off, 0),
      donGiaKH: isUsdExport ? round2(donGiaVND / tg) : Number(donGiaVND) || 0,
      truocThue: isUsdExport ? round2(truoc / tg) : Number(truoc) || 0,
      pctVat: toNum(i.Thue_VAT, 0),
      vatAmount: isUsdExport ? round2(vat / tg) : Number(vat) || 0,
      sauThue: isUsdExport ? round2(sau / tg) : Number(sau) || 0
    }
  })

  const customerRows: QuoteExportRowItem[] = quoteRowsWithSTT.value.map((r: any) => {
    if (r.type === 'group') {
      return {
        type: 'group',
        roman: r.roman,
        title: r.title,
        supplier: r.supplier || ''
      }
    }
    const i = r.item
    const tg = getGocNumber(i, '_Ti_gia_goc', toNum(i.Ti_gia, 1)) || 1
    const donGiaVND = unitPriceRaw(i)
    const truoc = lineTruocThueRaw(i)
    const vat = lineVATRaw(i)
    const sau = lineSauThueRaw(i)
    const lpVND = listPriceVndKho(i, true)
    const stdVND = standardPriceRaw(i)
    const nhapVND = giaNhapVndRaw(i)

    return {
      type: 'item',
      stt: r.stt,
      item: i,
      listPrice: isUsdExport ? round2(lpVND / tg) : Number(lpVND) || 0,
      giaTieuChuan: isUsdExport ? round2(stdVND / tg) : Number(stdVND) || 0,
      giaNhap: isUsdExport ? round2(nhapVND / tg) : Number(nhapVND) || 0,
      pctOffHang: displayGiaTieuChuanPctRaw(i),
      pctOff: getGocNumber(i, '_muc_phan_tram_off_goc', toNum(i.muc_phan_tram_off, 0)),
      donGiaKH: isUsdExport ? round2(donGiaVND / tg) : Number(donGiaVND) || 0,
      truocThue: isUsdExport ? round2(truoc / tg) : Number(truoc) || 0,
      pctVat: vatGoc(i),
      vatAmount: isUsdExport ? round2(vat / tg) : Number(vat) || 0,
      sauThue: isUsdExport ? round2(sau / tg) : Number(sau) || 0
    }
  })

  const originRows: QuoteExportRowItem[] = quoteRowsWithSTT.value.map((r: any) => {
    if (r.type === 'group') {
      return {
        type: 'group',
        roman: r.roman,
        title: r.title,
        supplier: r.supplier || ''
      }
    }
    const i = r.item
    const tg = getGocNumber(i, '_Ti_gia_kho', getGocNumber(i, '_Ti_gia_goc', toNum(i.Ti_gia, 1))) || 1
    const donGiaVND = unitPriceKho(i)
    const truoc = lineTruocThueKho(i)
    const vat = lineVATKho(i)
    const sau = lineSauThueKho(i)
    const lpVND = listPriceVndKho(i, true)
    const stdVND = standardPriceKho(i)
    const nhapVND = giaNhapVndKho(i)
    const lp = donGiaLPKho(i)
    const tc = getGocNumber(i, '_Gia_tieu_chuan_kho', toNum(i.Gia_tieu_chuan, 0))
    const pctOffHang = (!lp || lp === 0) ? 0 : round2((1 - tc / lp) * 100)

    return {
      type: 'item',
      stt: r.stt,
      item: i,
      listPrice: isUsdExport ? round2(lpVND / tg) : Number(lpVND) || 0,
      giaTieuChuan: isUsdExport ? round2(stdVND / tg) : Number(stdVND) || 0,
      giaNhap: isUsdExport ? round2(nhapVND / tg) : Number(nhapVND) || 0,
      pctOffHang,
      pctOff: getGocNumber(i, '_muc_phan_tram_off_kho', getGocNumber(i, '_muc_phan_tram_off_goc', toNum(i.muc_phan_tram_off, 0))),
      donGiaKH: isUsdExport ? round2(donGiaVND / tg) : Number(donGiaVND) || 0,
      truocThue: isUsdExport ? round2(truoc / tg) : Number(truoc) || 0,
      pctVat: vatKho(i),
      vatAmount: isUsdExport ? round2(vat / tg) : Number(vat) || 0,
      sauThue: isUsdExport ? round2(sau / tg) : Number(sau) || 0
    }
  })

  const drRow = loadedPipelineExtraData.value?.dealReg?.[0]
  const dealRegCtx = drRow
    ? {
        country: String(drRow[13] || 'VIET NAM'),
        isExistingCustomer: String(drRow[14] || ''),
        companySize: String(drRow[15] || ''),
        budget: String(drRow[16] || ''),
        closeDate: String(drRow[17] || ''),
        competition: String(drRow[18] || ''),
        pocSchedule: String(drRow[19] || ''),
        partnerName: String(drRow[20] || 'Nam Truong Son System Integration Corp'),
        partnerAddress: String(drRow[21] || '55/10 Trần Đình Xu, Phường Cầu Kho, Quận 1, Thành phố Hồ Chí Minh, Việt Nam'),
        amName: String(drRow[22] || 'LÊ PHI SƠN'),
        amEmail: String(drRow[23] || 'sonlp@nts.com.vn'),
        amPhone: String(drRow[24] || '090 8137488'),
        remarks: String(drRow[25] || ghiChuHopDong.value || '')
      }
    : {
        country: 'VIET NAM',
        remarks: ghiChuHopDong.value || ''
      }

  const effectiveKhach = {
    ...khach.value,
    Ma_khach_hang: khach.value.Ma_khach_hang || maKHInput.value.trim() || '',
    Ten_khach_hang: khach.value.Ten_khach_hang || tenKHInput.value.trim() || ''
  }

  const contractTotals = {
    truoc: isUsdExport ? Number(totalsUSD.value.truoc) || 0 : Number(totals.value.truoc) || 0,
    vat: isUsdExport ? Number(totalsUSD.value.vat) || 0 : Number(totals.value.vat) || 0,
    sau: isUsdExport ? Number(totalsUSD.value.sau) || 0 : Number(totals.value.sau) || 0,
    off: isUsdExport ? Number(totalsUSD.value.off) || 0 : Number(totals.value.off) || 0
  }
  const customerTotals = {
    truoc: isUsdExport ? Number(totalsContractUSD.value.truoc) || 0 : Number(totalsContract.value.truoc) || 0,
    vat: isUsdExport ? Number(totalsContractUSD.value.vat) || 0 : Number(totalsContract.value.vat) || 0,
    sau: isUsdExport ? Number(totalsContractUSD.value.sau) || 0 : Number(totalsContract.value.sau) || 0,
    off: isUsdExport ? Number(totalsContractUSD.value.off) || 0 : Number(totalsContract.value.off) || 0
  }
  const originTotals = {
    truoc: isUsdExport ? Number(totalsOriginUSD.value.truoc) || 0 : Number(totalsOrigin.value.truoc) || 0,
    vat: isUsdExport ? Number(totalsOriginUSD.value.vat) || 0 : Number(totalsOrigin.value.vat) || 0,
    sau: isUsdExport ? Number(totalsOriginUSD.value.sau) || 0 : Number(totalsOrigin.value.sau) || 0,
    off: isUsdExport ? Number(totalsOriginUSD.value.off) || 0 : Number(totalsOrigin.value.off) || 0
  }

  return {
    khach: effectiveKhach,
    maHopDong: maHopDong.value || '',
    soHopDong: soHopDong.value || '',
    soPO: currentPO.value || '',
    noiDungPO: contentOfContractPO.value.trim() || '',
    currency: isUsdExport ? 'USD' : 'VND',
    vndRoundingMode: vndRoundingMode.value,
    tiGia: mainTiGia.value || 1,
    rows: customerRows,
    totals: customerTotals,
    contractRows,
    contractTotals,
    customerRows,
    customerTotals,
    originRows,
    originTotals,
    itemSttFormat: quoteItemSttFormat.value,
    termsHtml: selectedTermId.value ? (editableTermContent.value || '') : '',
    noTerms: !selectedTermId.value,
    customDefaultFont: previewEditor.value?.getToolbarFont(),
    dealReg: dealRegCtx,
    previewCellOverrides: { ...previewCellOverridesMap },
    previewColWidthOverrides: { ...previewColWidthOverrides },
    previewRowHeightOverrides: { ...previewRowHeightOverrides }
  }
}

