  createdAt: number
  maHopDong: string
  soHopDong: string
  currentPO: string
  loadedMaHopDong: string | null
  loadedMaHopDongGoc: string | null
  ghiChuHopDong: string
  contentOfContractPO: string
  quoteCurrency: string
  selectedPriceListId: string
  selectedItems: any[]
  khach: KhachHang
  maKHInput: string
  tenKHInput: string
  isExistingCustomer: boolean
  originalKhach: KhachHang | null
  hasImportedCustomerPendingSave: boolean
  thueChenhLechPct: number
  chietKhauTruocThuePct: number
  selectedTermId: string
  editableTermContent: string
  importedTermsHtml: string
  excelMappingConfig: any[]
  loadedPipelineExtraData: any
  cmpSrOverridesMap?: {
    contract: CmpSrOverrideBucket
