function genUniqueMaHopDong(excludeTabId?: string): string {
  const base = `HD${new Date().toISOString().replace(/\D/g, '')}`
  const used = new Set(
    quoteTabs.value
      .filter(t => t.id !== excludeTabId)
      .map(t => String(t.maHopDong || '').trim())
      .filter(Boolean)
  )
  if (!used.has(base)) return base
  let suffix = 1
  while (used.has(`${base}${suffix}`)) {
    suffix++
  }
  return `${base}${suffix}`
}

function getNextTabNumber(): number {
  if (!quoteTabs.value.length) return 1
  let maxNum = 0
  quoteTabs.value.forEach(t => {
    const n = Number(t.tabNumber) || 0
    if (n > maxNum) maxNum = n
  })
  return maxNum + 1
}

function computeNextLocalSoHopDongAndPO(excludeTabId?: string): { soHopDong: string, currentPO: string } {
  let nextHdNum = (contractsRaw.value?.length || 0) + 1
  quoteTabs.value.forEach(t => {
    if (t.id === excludeTabId) return
    if (t.loadedMaHopDong) return
    const m = String(t.soHopDong || '').trim().match(/^(?:HĐ|HD)(\d+)$/i)
    if (m) {
      const n = parseInt(m[1], 10)
      if (!isNaN(n) && n >= nextHdNum) {
        nextHdNum = n + 1
      }
    }
  })

  let maxPo = latestMaxPoFromDb.value || 0
  quoteTabs.value.forEach(t => {
    if (t.id === excludeTabId) return
    if (t.loadedMaHopDong) return
    const pNum = parseInt(String(t.currentPO || '').replace(/\D/g, ''), 10)
    if (!isNaN(pNum) && pNum > maxPo) {
      maxPo = pNum
    }
  })

  return {
    soHopDong: contractsRaw.value?.length ? `HĐ${nextHdNum}` : '',
    currentPO: maxPo > 0 ? String(maxPo + 1) : ''
  }
}

function getDefaultTermSelection(): { id: string, content: string } {
  if (contractTerms.value.length > 0) {
    const defaultTerm = contractTerms.value.find(t => {
      const m = (t.mau || '').toLowerCase()
      return m.includes('mặc định') || m.includes('mac dinh')
    }) || contractTerms.value[0]
    if (defaultTerm) {
      return { id: defaultTerm.id, content: defaultTerm.noiDung || '' }
    }
  }
  return { id: '', content: '' }
}

function createBlankTabSession(customTabNum?: number): QuoteTabSession {
  const id = `qtab_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`
  const tabNumber = customTabNum ?? getNextTabNumber()
  const nextIds = computeNextLocalSoHopDongAndPO(id)
  const defTerm = getDefaultTermSelection()
  return {
    id,
    tabNumber,
    createdAt: Date.now(),
    maHopDong: genUniqueMaHopDong(id),
    soHopDong: nextIds.soHopDong,
    currentPO: nextIds.currentPO,
    loadedMaHopDong: null,
    loadedMaHopDongGoc: null,
    ghiChuHopDong: '',
    contentOfContractPO: '',
    quoteCurrency: 'VND',
    selectedPriceListId: '',
    selectedItems: [],
    khach: createEmptyKhachObj(),
    maKHInput: '',
    tenKHInput: '',
    isExistingCustomer: false,
    originalKhach: null,
    hasImportedCustomerPendingSave: false,
    thueChenhLechPct: 25,
    chietKhauTruocThuePct: 0,
    selectedTermId: defTerm.id,
    editableTermContent: defTerm.content,
    importedTermsHtml: '',
    excelMappingConfig: JSON.parse(JSON.stringify(defaultExcelConfig)),
    loadedPipelineExtraData: null,
    cmpSrOverridesMap: {
      contract: createEmptyCmpSrBucket(),
      customer: createEmptyCmpSrBucket()
    },
    historyLogs: createEmptyHistoryLogs(),
    actionHistory: []
  }
}

function snapshotCurrentStateToTab(tab: QuoteTabSession) {
  if (!tab) return
  tab.maHopDong = maHopDong.value || ''
  tab.soHopDong = soHopDong.value || ''
  tab.currentPO = currentPO.value || ''
  tab.loadedMaHopDong = loadedMaHopDong.value || null
  tab.loadedMaHopDongGoc = loadedMaHopDongGoc.value || null
  tab.ghiChuHopDong = ghiChuHopDong.value || ''
  tab.contentOfContractPO = contentOfContractPO.value || ''
  tab.quoteCurrency = quoteCurrency.value || 'VND'
  tab.selectedPriceListId = selectedPriceListId.value || ''
  tab.selectedItems = JSON.parse(JSON.stringify(selectedItems.value || []))
  tab.khach = JSON.parse(JSON.stringify(khach.value || createEmptyKhachObj()))
  tab.maKHInput = maKHInput.value || ''
  tab.tenKHInput = tenKHInput.value || ''
  tab.isExistingCustomer = !!isExistingCustomer.value
  tab.originalKhach = originalKhach.value ? JSON.parse(JSON.stringify(originalKhach.value)) : null
  tab.hasImportedCustomerPendingSave = !!hasImportedCustomerPendingSave.value
  tab.thueChenhLechPct = toNum(thueChenhLechPct.value, 0)
  tab.chietKhauTruocThuePct = toNum(chietKhauTruocThuePct.value, 0)
  tab.selectedTermId = selectedTermId.value || ''
  tab.editableTermContent = editableTermContent.value || ''
  tab.importedTermsHtml = importedTermsHtml.value || ''
  tab.excelMappingConfig = JSON.parse(JSON.stringify(excelMappingConfig.value || defaultExcelConfig))
  tab.loadedPipelineExtraData = loadedPipelineExtraData.value
    ? JSON.parse(JSON.stringify(loadedPipelineExtraData.value))
    : null
  tab.cmpSrOverridesMap = {
    contract: JSON.parse(JSON.stringify(cmpSrOverridesMap.contract || createEmptyCmpSrBucket())),
    customer: JSON.parse(JSON.stringify(cmpSrOverridesMap.customer || createEmptyCmpSrBucket()))
  }
  tab.historyLogs = JSON.parse(JSON.stringify(historyLogs.value || createEmptyHistoryLogs()))
  tab.actionHistory = JSON.parse(JSON.stringify(actionHistory.value || []))
}

function snapshotCurrentStateToActiveTab() {
  if (!activeQuoteTabId.value) return
  const cur = quoteTabs.value.find(t => t.id === activeQuoteTabId.value)
  if (cur) {
    snapshotCurrentStateToTab(cur)
  }
}

let isApplyingTabStateSync = false

function applyTabSessionToCurrentState(tab: QuoteTabSession) {
  if (!tab) return
  isSwitchingQuoteTab.value = true
  isApplyingTabStateSync = true
  try {
    closeQuoteEdit()
    closeQuoteEditRaw()

    maHopDong.value = tab.maHopDong || genUniqueMaHopDong(tab.id)
    soHopDong.value = tab.soHopDong || ''
    currentPO.value = tab.currentPO || ''
    loadedMaHopDong.value = tab.loadedMaHopDong || null
    loadedMaHopDongGoc.value = tab.loadedMaHopDongGoc || null
    ghiChuHopDong.value = tab.ghiChuHopDong || ''
    contentOfContractPO.value = tab.contentOfContractPO || ''
    quoteCurrency.value = tab.quoteCurrency || 'VND'
    selectedPriceListId.value = tab.selectedPriceListId || ''

    isExistingCustomer.value = !!tab.isExistingCustomer
    originalKhach.value = tab.originalKhach ? JSON.parse(JSON.stringify(tab.originalKhach)) : null
    hasImportedCustomerPendingSave.value = !!tab.hasImportedCustomerPendingSave
    khach.value = tab.khach
      ? { ...createEmptyKhachObj(), ...JSON.parse(JSON.stringify(tab.khach)) }
      : createEmptyKhachObj()
    maKHInput.value = tab.maKHInput ?? khach.value.Ma_khach_hang ?? ''
    tenKHInput.value = tab.tenKHInput ?? khach.value.Ten_khach_hang ?? ''

    thueChenhLechPct.value =
      tab.thueChenhLechPct !== undefined && tab.thueChenhLechPct !== null
        ? toNum(tab.thueChenhLechPct, 25)
        : 25
    chietKhauTruocThuePct.value = toNum(tab.chietKhauTruocThuePct, 0)

    importedTermsHtml.value = tab.importedTermsHtml || ''
    if (tab.selectedTermId) {
      selectedTermId.value = tab.selectedTermId
      editableTermContent.value = tab.editableTermContent || ''
    } else {
      const defTerm = getDefaultTermSelection()
      selectedTermId.value = defTerm.id
      editableTermContent.value = tab.editableTermContent || defTerm.content
    }

    excelMappingConfig.value =
      Array.isArray(tab.excelMappingConfig) && tab.excelMappingConfig.length
        ? JSON.parse(JSON.stringify(tab.excelMappingConfig))
        : JSON.parse(JSON.stringify(defaultExcelConfig))

    loadedPipelineExtraData.value = tab.loadedPipelineExtraData
      ? JSON.parse(JSON.stringify(tab.loadedPipelineExtraData))
      : null

    Object.assign(
      cmpSrOverridesMap.contract,
      createEmptyCmpSrBucket(),
      tab.cmpSrOverridesMap?.contract
        ? JSON.parse(JSON.stringify(tab.cmpSrOverridesMap.contract))
        : {}
    )
    Object.assign(
      cmpSrOverridesMap.customer,
      createEmptyCmpSrBucket(),
      tab.cmpSrOverridesMap?.customer
        ? JSON.parse(JSON.stringify(tab.cmpSrOverridesMap.customer))
        : {}
    )

    historyLogs.value = tab.historyLogs
      ? { ...createEmptyHistoryLogs(), ...JSON.parse(JSON.stringify(tab.historyLogs)) }
      : createEmptyHistoryLogs()
    actionHistory.value = Array.isArray(tab.actionHistory)
      ? JSON.parse(JSON.stringify(tab.actionHistory))
      : []

    selectedItems.value = Array.isArray(tab.selectedItems)
      ? JSON.parse(JSON.stringify(tab.selectedItems))
      : []

    products.value.forEach(p => {
      qtyMap[p.Ma_hang] = 1
    })
    selectedItems.value.forEach(it => {
      if (it.Ma_hang) qtyMap[it.Ma_hang] = Math.max(1, toNum(it.So_luong, 1))
    })

    syncFlatRows()
  } finally {
    isApplyingTabStateSync = false
  }

  nextTick(() => {
    isSwitchingQuoteTab.value = false
  })
}

function hasQuoteTabData(tab?: QuoteTabSession | null): boolean {
  if (!tab) return false
  if (Array.isArray(tab.selectedItems) && tab.selectedItems.length > 0) return true
  if (String(tab.loadedMaHopDong || '').trim() !== '') return true
  if (String(tab.tenKHInput || tab.khach?.Ten_khach_hang || '').trim() !== '') return true
  if (String(tab.maKHInput || tab.khach?.Ma_khach_hang || '').trim() !== '') return true
  if (String(tab.khach?.Ten_cong_ty || '').trim() !== '') return true
  if (String(tab.ghiChuHopDong || '').trim() !== '') return true
  if (String(tab.contentOfContractPO || '').trim() !== '') return true
  return false
}

function hasCurrentActiveQuoteData(): boolean {
  snapshotCurrentStateToActiveTab()
  const cur = quoteTabs.value.find(t => t.id === activeQuoteTabId.value)
  return hasQuoteTabData(cur)
}

function flushQuoteTabsToStorageNow() {
  if (!quoteTabs.value.length) return
  if (saveTabsDebounceTimer) {
    clearTimeout(saveTabsDebounceTimer)
    saveTabsDebounceTimer = null
  }
  if (!isApplyingTabStateSync) {
    snapshotCurrentStateToActiveTab()
  }
  try {
    const payload = {
      activeTabId: activeQuoteTabId.value,
      tabs: quoteTabs.value
    }
    localStorage.setItem(QUOTE_TABS_STORAGE_KEY, JSON.stringify(payload))
  } catch (err) {
    console.warn('Không thể lưu quoteTabs vào localStorage:', err)
  }
}

function scheduleSaveQuoteTabsToStorage() {
  if (isSwitchingQuoteTab.value || !quoteTabs.value.length) return
  snapshotCurrentStateToActiveTab()
  if (saveTabsDebounceTimer) clearTimeout(saveTabsDebounceTimer)
  saveTabsDebounceTimer = setTimeout(() => {
    flushQuoteTabsToStorageNow()
  }, 200)
}

function restoreQuoteTabsFromStorage(): boolean {
  try {
    const raw = localStorage.getItem(QUOTE_TABS_STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw)
      if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length > 0) {
        quoteTabs.value = parsed.tabs.map((t: any, idx: number) => ({
          ...createBlankTabSession(idx + 1),
          ...t,
          thueChenhLechPct:
            toNum(t.thueChenhLechPct, 0) > 0 ? toNum(t.thueChenhLechPct, 25) : 25,
          tabNumber: Number(t.tabNumber) || idx + 1
        }))
        const foundActive =
          quoteTabs.value.find(t => t.id === parsed.activeTabId) || quoteTabs.value[0]
        activeQuoteTabId.value = foundActive.id
        applyTabSessionToCurrentState(foundActive)
        return true
      }
    }
  } catch (err) {
    console.warn('Lỗi khôi phục quoteTabs từ localStorage:', err)
  }

  const firstTab = createBlankTabSession(1)
  quoteTabs.value = [firstTab]
  activeQuoteTabId.value = firstTab.id
  applyTabSessionToCurrentState(firstTab)
  flushQuoteTabsToStorageNow()
  return false
}

function scrollActiveTabIntoView() {
  nextTick(() => {
    const wrap = quoteTabsScrollRef.value
    if (!wrap) return
    const activeEl = wrap.querySelector('.quote-tab-item.active') as HTMLElement | null
    if (activeEl) {
      const targetLeft = activeEl.offsetLeft - wrap.clientWidth / 2 + activeEl.offsetWidth / 2
      wrap.scrollTo({ left: Math.max(0, targetLeft), behavior: 'smooth' })
    }
  })
}

async function createNewQuoteTab(options?: { silent?: boolean; skipGenerateIds?: boolean }) {
  snapshotCurrentStateToActiveTab()

  const newTab = createBlankTabSession()
  quoteTabs.value.push(newTab)
  activeQuoteTabId.value = newTab.id
  applyTabSessionToCurrentState(newTab)
  flushQuoteTabsToStorageNow()
  scrollActiveTabIntoView()

  if (!options?.skipGenerateIds) {
    await generateNewQuoteIds()
    flushQuoteTabsToStorageNow()
  }

  if (!options?.silent) {
    triggerToast(`Đã tạo Báo giá ${newTab.tabNumber}`)
  }
}

function switchQuoteTab(tabId: string) {
  if (!tabId || tabId === activeQuoteTabId.value) return
  const target = quoteTabs.value.find(t => t.id === tabId)
  if (!target) return

  snapshotCurrentStateToActiveTab()
  activeQuoteTabId.value = target.id
  applyTabSessionToCurrentState(target)
  flushQuoteTabsToStorageNow()
  scrollActiveTabIntoView()
}

async function closeQuoteTab(tabId: string, forceWithoutConfirm = false) {
  const idx = quoteTabs.value.findIndex(t => t.id === tabId)
  if (idx === -1) return

  if (tabId === activeQuoteTabId.value && !isSwitchingQuoteTab.value) {
    snapshotCurrentStateToActiveTab()
  }

  const tabToClose = quoteTabs.value[idx]
  if (!forceWithoutConfirm && hasQuoteTabData(tabToClose)) {
    const title = getQuoteTabDisplayTitle(tabToClose, idx)
    const ok = await openBaogiaConfirm({
      variant: 'danger',
      eyebrow: 'Quản lý Tab báo giá',
      title: 'Xác nhận đóng & xóa Tab',
      highlightLabel: 'Tab báo giá đang chọn',
      highlightValue: title,
      message: `Bạn có chắc chắn muốn xóa tab "${title}" không?`,
      subNote: 'Dữ liệu chưa lưu trong tab này sẽ bị xóa vĩnh viễn và không thể khôi phục.',
      cancelText: 'Giữ lại Tab',
      confirmText: 'Xóa Tab này'
    })
    if (!ok) return
  }

  const wasActive = tabId === activeQuoteTabId.value
  quoteTabs.value.splice(idx, 1)

  if (quoteTabs.value.length === 0) {
    const freshTab = createBlankTabSession(1)
    quoteTabs.value.push(freshTab)
    activeQuoteTabId.value = freshTab.id
    applyTabSessionToCurrentState(freshTab)
    flushQuoteTabsToStorageNow()
    await generateNewQuoteIds()
    flushQuoteTabsToStorageNow()
    return
  }

  if (wasActive) {
    const nextIdx = Math.min(idx, quoteTabs.value.length - 1)
    const nextTab = quoteTabs.value[nextIdx]
    activeQuoteTabId.value = nextTab.id
    applyTabSessionToCurrentState(nextTab)
  }

  flushQuoteTabsToStorageNow()
  scrollActiveTabIntoView()
}

async function closeQuoteTabAfterSave(savedTabId?: string) {
  const targetId = savedTabId || activeQuoteTabId.value
  if (route.query.ma || route.query.clone) {
    router.replace('/baogiafirebase')
  }
  await closeQuoteTab(targetId, true)
  // Đồng bộ lại danh sách hợp đồng và PO mới nhất ở nền
  Promise.all([
    fetchHopDongTongQuatFromFirebase(),
    fetchPoDxmhFromFirebase()
  ])
    .then(([hdRows, poData]) => {
      if (Array.isArray(hdRows)) contractsRaw.value = hdRows
      let maxPO = 0
      if (Array.isArray(poData)) {
        poData.forEach((row: any) => {
          const soPo = parseInt(String(row[2] || '').replace(/\D/g, ''), 10)
          if (!isNaN(soPo) && soPo > maxPO) maxPO = soPo
        })
      }
      latestMaxPoFromDb.value = maxPO
      const curTab = quoteTabs.value.find(t => t.id === activeQuoteTabId.value)
      if (curTab && !curTab.loadedMaHopDong && !hasQuoteTabData(curTab)) {
        const nextIds = computeNextLocalSoHopDongAndPO(curTab.id)
        if (nextIds.soHopDong) soHopDong.value = nextIds.soHopDong
        if (nextIds.currentPO) currentPO.value = nextIds.currentPO
        flushQuoteTabsToStorageNow()
      }
    })
    .catch(() => {})
}

function getTabItemCount(tab: QuoteTabSession): number {
  if (tab.id === activeQuoteTabId.value) {
    return selectedItems.value.length
  }
  return Array.isArray(tab.selectedItems) ? tab.selectedItems.length : 0
}

function getTabCustomerName(tab: QuoteTabSession): string {
  const isCurrent = tab.id === activeQuoteTabId.value
  const rawCus = isCurrent
    ? (khach.value?.Ten_khach_hang || tenKHInput.value || khach.value?.Ten_cong_ty || '')
    : (tab.khach?.Ten_khach_hang || tab.tenKHInput || tab.khach?.Ten_cong_ty || '')
  return String(rawCus || '').trim()
}

function getCurrentDockCustomerName(): string {
  return String(khach.value?.Ten_khach_hang || tenKHInput.value || khach.value?.Ten_cong_ty || '').trim()
}

function onClickQuoteTabCustomerBadge(tab: QuoteTabSession, e: MouseEvent) {
  if (tab.id === activeQuoteTabId.value) {
    e.stopPropagation()
    showCustomerDetailModal.value = true
  }
}

function getQuoteTabDisplayTitle(tab: QuoteTabSession, idx: number): string {
  const isCurrent = tab.id === activeQuoteTabId.value
  const loadedMa = isCurrent ? loadedMaHopDong.value : tab.loadedMaHopDong
  const soHD = isCurrent ? soHopDong.value : tab.soHopDong
  const num = tab.tabNumber || idx + 1

  return loadedMa ? `Sửa ${soHD || loadedMa}` : `Báo giá ${num}`
}

function getQuoteTabFullTooltip(tab: QuoteTabSession): string {
  const isCurrent = tab.id === activeQuoteTabId.value
  const maHD = isCurrent ? maHopDong.value : tab.maHopDong
  const soHD = isCurrent ? soHopDong.value : tab.soHopDong
  const po = isCurrent ? currentPO.value : tab.currentPO
  const loadedMa = isCurrent ? loadedMaHopDong.value : tab.loadedMaHopDong
  const cus = isCurrent
    ? (khach.value?.Ten_cong_ty || khach.value?.Ten_khach_hang || tenKHInput.value || 'Chưa chọn KH')
    : (tab.khach?.Ten_cong_ty || tab.khach?.Ten_khach_hang || tab.tenKHInput || 'Chưa chọn KH')
  const count = getTabItemCount(tab)
  const parts = [
    `Báo giá ${tab.tabNumber}`,
    `Số HĐ: ${soHD || '—'}`,
    `Số PO: ${po || '—'}`,
    `Mã HĐ: ${maHD || '—'}`
  ]
  if (loadedMa) parts.push(`Mã HĐ cũ: ${loadedMa}`)
  parts.push(`Khách hàng: ${cus}`)
  parts.push(`Số SP: ${count}`)
  return parts.join(' | ')
}

