  flex-shrink: 0 !important;
  transition: all 0.3s !important;
  position: relative !important;
  z-index: 1 !important;
  padding: 0 !important;
  margin: 0 !important;
}

.export-vip-btn-text {
  flex: 1 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 3px !important;
  position: relative !important;
  z-index: 1 !important;
  margin: 0 !important;
  padding: 0 !important;
}

.export-vip-btn-label {
  font-size: 17px !important;
  font-weight: 800 !important;
  letter-spacing: 0.3px !important;
}

.export-vip-btn-desc {
  font-size: 12px !important;
  font-weight: 500 !important;
  opacity: 0.6 !important;
}

.export-vip-btn-arrow {
  opacity: 0.3;
  transform: translateX(-4px);
  transition: all 0.3s;
  position: relative;
  z-index: 1;
}
.export-vip-btn:hover .export-vip-btn-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* -- Excel Button -- */
.export-vip-btn-excel {
  border-color: rgba(16,185,129,0.15) !important;
}
.export-vip-btn-excel::before {
  background: linear-gradient(135deg, rgba(16,185,129,0.08) 0%, rgba(52,211,153,0.02) 100%);
}
.export-vip-btn-excel .export-vip-btn-icon {
  background: rgba(16,185,129,0.1) !important;
  color: #34d399 !important;
}
.export-vip-btn-excel .export-vip-btn-label { color: #34d399 !important; }
.export-vip-btn-excel .export-vip-btn-desc { color: #a7f3d0 !important; }
.export-vip-btn-excel .export-vip-btn-arrow { color: #34d399 !important; }
.export-vip-btn-excel:hover {
  border-color: rgba(16,185,129,0.4) !important;
  box-shadow: 0 12px 30px rgba(16,185,129,0.15) !important;
}
.export-vip-btn-excel:hover .export-vip-btn-icon {
  background: rgba(16,185,129,0.2) !important;
  transform: scale(1.05) rotate(-5deg) !important;
}

/* -- Agency Button -- */
.export-vip-btn-agency {
  border-color: rgba(234,179,8,0.15) !important;
}
.export-vip-btn-agency::before {
  background: linear-gradient(135deg, rgba(234,179,8,0.08) 0%, rgba(250,204,21,0.02) 100%);
}
.export-vip-btn-agency .export-vip-btn-icon {
  background: rgba(234,179,8,0.1) !important;
  color: #fbbf24 !important;
}
.export-vip-btn-agency .export-vip-btn-label { color: #fbbf24 !important; }
.export-vip-btn-agency .export-vip-btn-desc { color: #fde047 !important; }
.export-vip-btn-agency .export-vip-btn-arrow { color: #fbbf24 !important; }
.export-vip-btn-agency:hover {
  border-color: rgba(234,179,8,0.4) !important;
  box-shadow: 0 12px 30px rgba(234,179,8,0.12) !important;
}
.export-vip-btn-agency:hover .export-vip-btn-icon {
  background: rgba(234,179,8,0.2) !important;
  transform: scale(1.05) rotate(5deg) !important;
}

/* -- Pipeline Button -- */
.export-vip-btn-pipeline {
  border-color: rgba(59,130,246,0.15) !important;
}
.export-vip-btn-pipeline::before {
  background: linear-gradient(135deg, rgba(59,130,246,0.08) 0%, rgba(96,165,250,0.02) 100%);
}
.export-vip-btn-pipeline .export-vip-btn-icon {
  background: rgba(59,130,246,0.1) !important;
  color: #60a5fa !important;
}
.export-vip-btn-pipeline .export-vip-btn-label { color: #60a5fa !important; }
.export-vip-btn-pipeline .export-vip-btn-desc { color: #93c5fd !important; }
.export-vip-btn-pipeline .export-vip-btn-arrow { color: #60a5fa !important; }
.export-vip-btn-pipeline:hover {
  border-color: rgba(59,130,246,0.4) !important;
  box-shadow: 0 12px 30px rgba(59,130,246,0.12) !important;
}
.export-vip-btn-pipeline:hover .export-vip-btn-icon {
  background: rgba(59,130,246,0.2) !important;
  transform: scale(1.05) translateY(-2px) !important;
}

/* -- Image Button -- */
.export-vip-btn-image {
  border-color: rgba(236,72,153,0.15) !important;
}
.export-vip-btn-image::before {
  background: linear-gradient(135deg, rgba(236,72,153,0.08) 0%, rgba(244,114,182,0.02) 100%);
}
.export-vip-btn-image .export-vip-btn-icon {
  background: rgba(236,72,153,0.1) !important;
  color: #ec4899 !important;
}
.export-vip-btn-image .export-vip-btn-label { color: #ec4899 !important; }
.export-vip-btn-image .export-vip-btn-desc { color: #f472b6 !important; }
.export-vip-btn-image .export-vip-btn-arrow { color: #ec4899 !important; }
.export-vip-btn-image:hover {
  border-color: rgba(236,72,153,0.4) !important;
  box-shadow: 0 12px 30px rgba(236,72,153,0.12) !important;
}
.export-vip-btn-image:hover .export-vip-btn-icon {
  background: rgba(236,72,153,0.2) !important;
  transform: scale(1.05) translateY(-2px) !important;
}

/* ── Responsive: Stack columns on small screens ── */
@media (max-width: 580px) {
  .export-vip-body {
    grid-template-columns: 1fr;
  }
  .export-vip-col-upload {
    border-right: none;
    border-bottom: 1px solid rgba(16, 185, 129, 0.15);
  }
  .export-tpl-dropzone {
    padding: 20px 14px;
  }
}
/* ================== MOBILE 3-SCREEN FLOW (KHO SP -> BÁO GIÁ -> TỔNG KẾT -> MODAL KHÁCH HÀNG) ================== */
.mobile-progress-wrapper,
.mobile-top-display-btn,
.mobile-top-guide-btn,
.mobile-top-util-btn,
.mobile-screen1-cart-bar,
.mobile-back-to-store-btn,
.mobile-quote-customer-card,
.mobile-quote-empty-card,
.mobile-quote-item-cell,
.mobile-quote-summary-card,
.mobile-screen2-action-bar,
.m-quote-mode-mini-dock,
.qmode-mobile-sheet-overlay,
.card-mobile-top-meta,
.cust-mobile-mini-actions,
.cust-import-btn .mb-lbl,
.mobile-cust-accordion-btn,
.export-tpl-radio-dot,
.export-tpl-mb-badge,
.export-tpl-setup-btn .mb-lbl,
.export-tpl-change-btn .mb-lbl,
.export-multi-setup-mobile-btn,
.export-multi-mobile-tabs,
.export-multi-head-title .mb-lbl,
.export-zoom-title-wrap .mb-lbl,
.pv-mode-toggle-btn .mb-lbl,
.pv-reset-btn .mb-lbl,
.m-grab-head-stack,
.m-grab-back-only {
  display: none !important;
}

@media (min-width: 1101px) {
  .btn-reset-quote:hover {
    background: #dc2626 !important;
    box-shadow: 0 2px 5px rgba(239, 68, 68, 0.5) !important;
  }
}

.btn-quote-col-setting,
.btn-quote-guide {
  width: auto !important;
  min-width: 0 !important;
  flex-shrink: 0 !important;
}

@media (max-width: 1100px) {
  .mobile-progress-wrapper,
  .hide-on-mobile-quote,
  .open-tab,
  .main-grid .bottom-totals.left-sidebar-dock,
  .mobile-quote-customer-card {
    display: none !important;
  }

  .mobile-top-display-btn,
  .mobile-top-guide-btn {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 30px !important;
    min-width: 30px !important;
    height: 30px !important;
    min-height: 30px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 8px !important;
    background: #1e293b !important;
    border: 1px solid #334155 !important;
    color: #cbd5e1 !important;
    flex-shrink: 0 !important;
    cursor: pointer !important;
    box-shadow: none !important;
    transition: all 0.18s ease !important;
  }

  .mobile-top-display-btn.is-active,
  .mobile-top-guide-btn.is-active {
    border-color: rgba(56, 189, 248, 0.55) !important;
    color: #38bdf8 !important;
    background: rgba(30, 41, 59, 0.98) !important;
  }

  .sidebar-head-product select,
  .sidebar-head-product .btn-pricelist-toggle {
    height: 30px !important;
    min-height: 30px !important;
    box-sizing: border-box !important;
  }

  .mobile-top-util-btn {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 30px !important;
    min-width: 30px !important;
    height: 30px !important;
    min-height: 30px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 8px !important;
    background: rgba(30, 41, 59, 0.92) !important;
    border: 1px solid rgba(56, 189, 248, 0.38) !important;
    color: #38bdf8 !important;
    flex-shrink: 0 !important;
    cursor: pointer !important;
    box-shadow: none !important;
  }

  /* QUAN TRỌNG: Tắt backdrop-filter/transform trên các vùng cuộn cha để thanh position: fixed không bị kẹt bên trong container */
  .sidebar-left,
  .product-sidebar,
  .quote-center,
  .quote-table-container {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    transform: none !important;
    filter: none !important;
  }

  /* LOGIC 3 MÀN HÌNH: SCREEN 1 (KHO SẢN PHẨM), SCREEN 2 (BÁO GIÁ) & SCREEN 3 (TỔNG KẾT CUỘN MƯỢT LIỀN MẠCH) */
  .main-grid.mobile-step-1 .quote-center {
    display: none !important;
  }
  .main-grid.mobile-step-1 .sidebar-left {
    display: flex !important;
    flex-direction: column !important;
    max-height: unset !important;
    margin-left: 0 !important;
    opacity: 1 !important;
    pointer-events: auto !important;
  }

  .main-grid:not(.mobile-step-1) .sidebar-left {
    display: none !important;
  }
  .main-grid:not(.mobile-step-1) .quote-center {
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    overflow: hidden !important;
  }
  .main-grid:not(.mobile-step-1) .quote-table-container {
    display: block !important;
    flex: none !important;
    width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    overscroll-behavior-y: contain !important;
  }

  /* Screen 2: Trang Báo giá riêng biệt (Chỉ hiện danh sách hàng hóa trong báo giá, ẩn phần Tổng kết) */
  .main-grid.mobile-step-2 .quote-center .quote-table-wrap {
    display: block !important;
    flex: none !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow: visible !important;
  }
  .main-grid.mobile-step-2 .mobile-quote-summary-card {
    display: none !important;
  }

  /* Screen 3: Trang Tổng kết riêng biệt (Chỉ hiện Chiết khấu + Tài chính, ẩn danh sách hàng hóa) */
  .main-grid.mobile-step-3 .quote-center .quote-table-wrap {
    display: none !important;
  }
  .main-grid.mobile-step-3 .mobile-quote-summary-card {
    display: block !important;
  }

  /* ================= NATIVE APP MOBILE LAYOUT ================= */
  .page.baogia-firebase-page {
    --mobile-modal-head-top: max(calc(env(safe-area-inset-top, 0px) + 6px), 52px);
    padding: 0 !important;
    margin: 0 !important;
    width: 100% !important;
    height: 100% !important;
    min-height: 0 !important;
    max-height: 100% !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
  }

  .main-grid {
    gap: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    display: block !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
  }

  .sidebar-left, .quote-center, .bottom-totals, .totals-box {
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    margin: 0 !important;
    box-sizing: border-box !important;
    border-radius: 0 !important;
  }

  /* ═══════════════════════════════════════════════════
     MÀN HÌNH 1: KHO SẢN PHẨM (.sidebar-left)
     ═══════════════════════════════════════════════════ */
  .sidebar-left {
    height: 100% !important;
    max-height: 100% !important;
    padding: 12px 12px calc(156px + env(safe-area-inset-bottom, 0px)) 12px !important;
    background: transparent !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    overscroll-behavior-y: contain !important;
    border: none !important;
    box-shadow: none !important;
  }

  .product-catalog-sticky-head {
    display: block !important;
    position: sticky !important;
    top: -12px !important;
    z-index: 45 !important;
    margin: -12px -12px 10px -12px !important;
    padding: 12px 12px 10px 12px !important;
    background: rgba(11, 17, 24, 0.9) !important;
    border-bottom: 1px solid rgba(51, 65, 85, 0.45) !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.32) !important;
    backdrop-filter: blur(18px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(180%) !important;
    transition:
      transform 0.36s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.25s ease,
      box-shadow 0.25s ease !important;
    will-change: transform, opacity;
  }

  .product-catalog-sticky-head.is-header-hidden {
    transform: translateY(-112%) !important;
    opacity: 0 !important;
    pointer-events: none !important;
    box-shadow: none !important;
  }

  .sidebar-head-product {
    padding: 10px 12px !important;
    border-radius: 12px !important;
    background: rgba(15, 23, 42, 0.78) !important;
    border: 1px solid rgba(51, 65, 85, 0.7) !important;
    margin-bottom: 8px !important;
  }

  .sidebar-left .top-bar {
    position: relative !important;
    top: 0 !important;
    z-index: 2 !important;
    padding: 0 !important;
    margin-bottom: 0 !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  .product-grid {
    grid-template-columns: 1fr !important;
    gap: 10px !important;
    padding-bottom: 32px !important;
    overflow: visible !important;
  }

  /* Product Card gọn gàng, sạch sẽ trên Mobile */
  .product-grid .card {
    padding: 12px 14px !important;
    border-radius: 14px !important;
    gap: 8px !important;
  }

  .product-grid .card.card-in-quote {
    border-color: rgba(16, 185, 129, 0.6) !important;
    box-shadow: 0 0 0 1px rgba(16, 185, 129, 0.25), 0 6px 16px rgba(0, 0, 0, 0.18) !important;
  }

  .card-mobile-top-meta {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    margin-bottom: 4px !important;
  }

  .card-code-tag {
    font-size: 10.5px !important;
    font-weight: 700 !important;
    color: #94a3b8 !important;
    background: rgba(30, 41, 59, 0.85) !important;
    border: 1px solid rgba(71, 85, 105, 0.45) !important;
    padding: 2px 7px !important;
    border-radius: 5px !important;
    max-width: 65% !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }

  .card-selected-badge {
    display: inline-flex !important;
    align-items: center !important;
    gap: 4px !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    color: #10b981 !important;
    background: rgba(16, 185, 129, 0.14) !important;
    border: 1px solid rgba(16, 185, 129, 0.38) !important;
    padding: 2px 8px !important;
    border-radius: 999px !important;
    white-space: nowrap !important;
    margin-left: auto !important;
  }

  /* Hiển thị tên bảng giá trên từng card ở kho sản phẩm để người dùng dễ nhận biết */
  .card-pl-prefix {
    display: inline !important;
    font-size: 12.5px !important;
    font-weight: 800 !important;
  }

  /* Giá gốc gạch ngang màu dịu để không tranh chấp với giá bán chính */
  .card-sys-orig-price,
  .card-sys-orig-price span {
    color: #64748b !important;
    font-weight: 600 !important;
  }

  .product-grid .card .price {
    font-size: 15.5px !important;
    font-weight: 800 !important;
    letter-spacing: -0.2px !important;
  }

  /* FLOATING GLASS BAR NỔI TRÊN PILL BOTTOM NAVIGATION (MÀN HÌNH 1, 2 & 3) */
  .mobile-screen1-cart-bar,
  .mobile-screen2-action-bar {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 10px !important;
    position: fixed !important;
    left: 12px !important;
    right: 12px !important;
    bottom: calc(74px + env(safe-area-inset-bottom, 0px)) !important;
    width: auto !important;
    max-width: calc(100vw - 24px) !important;
    margin: 0 auto !important;
    border-radius: 20px !important;
    z-index: 950 !important;
    padding: 8px 12px !important;
    background: rgba(15, 23, 42, 0.78) !important;
    border: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-top: 1px solid rgba(56, 189, 248, 0.38) !important;
    box-shadow:
      0 12px 30px rgba(0, 0, 0, 0.5),
      inset 0 1px 0 rgba(255, 255, 255, 0.16) !important;
    backdrop-filter: blur(22px) saturate(185%) !important;
    -webkit-backdrop-filter: blur(22px) saturate(185%) !important;
    transition:
      bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.24s ease,
      box-shadow 0.3s ease !important;
  }

  .mobile-screen1-cart-bar.is-modal-hidden,
  .mobile-screen2-action-bar.is-modal-hidden,
  .page.has-open-modal .mobile-screen1-cart-bar,
  .page.has-open-modal .mobile-screen2-action-bar {
    transform: translateY(calc(100% + 96px + env(safe-area-inset-bottom, 0px))) scale(0.96) !important;
    opacity: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
  }

  .app-layout.mobile-nav-hidden .mobile-screen1-cart-bar,
  .app-layout.mobile-nav-hidden .mobile-screen2-action-bar {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px)) !important;
  }

  /* DOCK NHỎ KIỂU A (FLOATING PILL) NẰM NGAY PHÍA TRÊN DOCK CHA Ở BƯỚC 2: BÁO GIÁ */
  #app .page button.m-quote-mode-mini-dock {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 6px !important;
    position: fixed !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    bottom: calc(130px + env(safe-area-inset-bottom, 0px)) !important;
    width: max-content !important;
    max-width: calc(100vw - 32px) !important;
    height: 30px !important;
    min-height: 30px !important;
    margin: 0 !important;
    padding: 0 13px !important;
    border-radius: 999px !important;
    z-index: 952 !important;
    background: rgba(15, 23, 42, 0.88) !important;
    border: 1px solid rgba(148, 163, 184, 0.32) !important;
    color: #f8fafc !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
    white-space: nowrap !important;
    cursor: pointer !important;
    box-shadow:
      0 8px 20px rgba(2, 6, 23, 0.48),
      inset 0 1px 0 rgba(255, 255, 255, 0.14) !important;
    backdrop-filter: blur(20px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
    transition:
      bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.24s ease,
      border-color 0.2s ease !important;
  }

  #app .page button.m-quote-mode-mini-dock:active {
    transform: translateX(-50%) scale(0.95) !important;
  }

  #app .page button.m-quote-mode-mini-dock.is-modal-hidden,
  .page.has-open-modal #app .page button.m-quote-mode-mini-dock:not(.is-in-quote-edit-modal),
  #app .page.has-open-modal button.m-quote-mode-mini-dock:not(.is-in-quote-edit-modal) {
    transform: translateX(-50%) translateY(calc(100% + 140px + env(safe-area-inset-bottom, 0px))) scale(0.95) !important;
    opacity: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
  }

  #app .app-layout.mobile-nav-hidden .page button.m-quote-mode-mini-dock:not(.is-in-quote-edit-modal),
  .app-layout.mobile-nav-hidden .page button.m-quote-mode-mini-dock:not(.is-in-quote-edit-modal) {
    bottom: calc(66px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .m-quote-mode-mini-dock .m-qmd-dot {
    width: 7.5px !important;
    height: 7.5px !important;
    border-radius: 999px !important;
    flex-shrink: 0 !important;
    background: #3b82f6 !important;
    box-shadow: 0 0 6px rgba(59, 130, 246, 0.65) !important;
  }

  .m-quote-mode-mini-dock .m-qmd-prefix {
    font-size: 10.5px !important;
    font-weight: 600 !important;
    color: #94a3b8 !important;
  }

  .m-quote-mode-mini-dock .m-qmd-label {
    font-size: 11.5px !important;
    font-weight: 800 !important;
    letter-spacing: 0.15px !important;
  }

  .m-quote-mode-mini-dock .m-qmd-chevron {
    flex-shrink: 0 !important;
    opacity: 0.85 !important;
  }

  /* Màu nhấn theo 4 chế độ trên Mini Dock */
  #app .page button.m-quote-mode-mini-dock.is-mode-origin {
    border-color: rgba(245, 158, 11, 0.5) !important;
  }
