  /* CỤM 4 NÚT QUY TRÌNH BÊN PHẢI DOCK (.m-dock-steps) */
  .m-dock-steps {
    display: flex !important;
    align-items: center !important;
    gap: 3px !important;
    flex-shrink: 0 !important;
  }

  .m-step-arrow {
    font-size: 10px !important;
    font-weight: 800 !important;
    color: rgba(148, 163, 184, 0.55) !important;
    user-select: none !important;
    line-height: 1 !important;
    margin: 0 1px !important;
  }

  .m-step-pill {
    position: relative !important;
    height: 32px !important;
    min-width: 28px !important;
    width: auto !important;
    padding: 0 8px !important;
    margin: 0 !important;
    border-radius: 999px !important;
    background: rgba(30, 41, 59, 0.85) !important;
    border: 1px solid rgba(148, 163, 184, 0.25) !important;
    color: #94a3b8 !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 0 !important;
    cursor: pointer !important;
    box-shadow: none !important;
    -webkit-tap-highlight-color: transparent;
    transition:
      background 0.32s cubic-bezier(0.22, 1, 0.36, 1),
      color 0.25s ease,
      padding 0.32s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
      border-color 0.3s ease,
      box-shadow 0.32s cubic-bezier(0.22, 1, 0.36, 1) !important;
  }

  .m-step-pill:active {
    transform: scale(0.91) !important;
  }

  .m-step-pill.is-done {
    background: rgba(16, 185, 129, 0.09) !important;
    border: 1px solid rgba(16, 185, 129, 0.25) !important;
    color: rgba(52, 211, 153, 0.78) !important;
  }

  .m-step-pill.is-current:not(.is-active) {
    background: rgba(16, 185, 129, 0.24) !important;
    border: 1.8px solid #34d399 !important;
    color: #ffffff !important;
    box-shadow:
      0 0 0 2px rgba(52, 211, 153, 0.18),
      inset 0 1px 0 rgba(255, 255, 255, 0.18) !important;
  }

  .m-step-pill.is-active {
    padding: 0 11px !important;
    background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
    border-color: rgba(110, 231, 183, 0.65) !important;
    color: #ffffff !important;
    box-shadow:
      0 4px 12px rgba(16, 185, 129, 0.38),
      inset 0 1px 0 rgba(255, 255, 255, 0.25) !important;
  }

  .m-step-pill.m-step-save.is-active {
    background: linear-gradient(135deg, #2563eb 0%, #059669 100%) !important;
    border-color: rgba(147, 197, 253, 0.65) !important;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.38) !important;
  }

  @keyframes mDockNextStepPulse {
    0%, 100% {
      transform: scale(1);
    }
    50% {
      transform: scale(1.065);
    }
  }

  .m-step-pill.is-next-pulse {
    animation: mDockNextStepPulse 2.1s cubic-bezier(0.4, 0, 0.2, 1) infinite !important;
    transform-origin: center center !important;
    will-change: transform;
  }

  .m-step-pill.is-next-pulse:active {
    animation: none !important;
    transform: scale(0.91) !important;
  }

  .m-step-num {
    font-size: 11.5px !important;
    font-weight: 900 !important;
    line-height: 1 !important;
  }

  .m-step-label {
    display: inline-block !important;
    max-width: 0 !important;
    opacity: 0 !important;
    overflow: hidden !important;
    white-space: nowrap !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
    line-height: 1 !important;
    transition:
      max-width 0.34s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.22s ease !important;
  }

  .m-step-pill.is-active .m-step-label {
    max-width: 85px !important;
    opacity: 1 !important;
  }

  .m-step-mini-badge {
