    border: none !important;
    color: #ffffff !important;
    box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3) !important;
  }

  .m-empty-btn.secondary {
    background: rgba(30, 41, 59, 0.9) !important;
    border: 1px solid rgba(71, 85, 105, 0.7) !important;
    color: #e2e8f0 !important;
    box-shadow: none !important;
  }

  .quote-center .quote-table-wrap table,
  .quote-center .quote-table-wrap tbody,
  .preview-raw-quote-wrap table,
  .preview-raw-quote-wrap tbody {
    display: block !important;
    width: 100% !important;
    min-width: 0 !important;
    height: auto !important;
    background: transparent !important;
  }

  .quote-center .quote-table-wrap thead,
  .quote-center .quote-table-wrap tfoot,
  .quote-center .quote-table-wrap tr.spacer-row,
  .preview-raw-quote-wrap thead,
  .preview-raw-quote-wrap tfoot,
  .preview-raw-quote-wrap tr.spacer-row {
    display: none !important;
  }

  /* Ẩn toàn bộ các ô td của Desktop trên Mobile, chỉ hiện duy nhất .mobile-quote-item-cell */
  .quote-center .quote-table-wrap tr.quote-item-row,
  .preview-raw-quote-wrap tr.quote-item-row {
    display: block !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 0 10px 0 !important;
    width: 100% !important;
    height: auto !important;
    touch-action: pan-y !important;
  }

  .quote-center .quote-table-wrap tr.quote-item-row > td:not(.mobile-quote-item-cell),
  .preview-raw-quote-wrap tr.quote-item-row > td:not(.mobile-quote-item-cell) {
    display: none !important;
  }

  .quote-center .quote-table-wrap tr.quote-item-row > td.mobile-quote-item-cell,
  .preview-raw-quote-wrap tr.quote-item-row > td.mobile-quote-item-cell {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    border: none !important;
    background: transparent !important;
  }

  .quote-center .quote-table-wrap tr.quote-item-row > td.mobile-quote-item-cell::before,
  .preview-raw-quote-wrap tr.quote-item-row > td.mobile-quote-item-cell::before {
    display: none !important;
    content: none !important;
  }

  /* Card 3 tầng cho từng mặt hàng trong báo giá */
  .m-qcard {
    background: rgba(30, 41, 59, 0.85) !important;
    border: 1px solid rgba(71, 85, 105, 0.55) !important;
    border-left: 3px solid #10b981 !important;
    border-radius: 12px !important;
    padding: 11px 12px !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.2) !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 7px !important;
  }

  .m-qcard-top {
    display: flex !important;
    align-items: flex-start !important;
    gap: 8px !important;
  }

  .m-qcard-stt {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    min-width: 24px !important;
    height: 22px !important;
    padding: 0 6px !important;
    border-radius: 6px !important;
    background: rgba(16, 185, 129, 0.16) !important;
    border: 1px solid rgba(16, 185, 129, 0.38) !important;
    color: #34d399 !important;
    font-size: 11px !important;
    font-weight: 800 !important;
    flex-shrink: 0 !important;
    margin-top: 1px !important;
  }

  .m-qcard-title {
    flex: 1 !important;
    min-width: 0 !important;
    font-size: 13.5px !important;
    font-weight: 800 !important;
    color: #f8fafc !important;
    line-height: 1.35 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    word-break: break-word !important;
  }

  .m-qcard.is-move-active {
    border-color: rgba(56, 189, 248, 0.72) !important;
    box-shadow: 0 0 0 1px rgba(56, 189, 248, 0.28), 0 6px 18px rgba(2, 132, 199, 0.22) !important;
  }

  .m-qcard-top-actions {
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    flex-shrink: 0 !important;
    margin: -2px -2px 0 0 !important;
  }

  .m-qcard-del {
    width: 28px !important;
    min-width: 28px !important;
    height: 28px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 7px !important;
    background: rgba(239, 68, 68, 0.14) !important;
    border: 1px solid rgba(239, 68, 68, 0.35) !important;
    color: #f87171 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    cursor: pointer !important;
    box-shadow: none !important;
  }

  .m-qcard-move-toggle {
    width: 28px !important;
    min-width: 28px !important;
    height: 28px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 7px !important;
    background: rgba(56, 189, 248, 0.14) !important;
    border: 1px solid rgba(56, 189, 248, 0.38) !important;
    color: #38bdf8 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    cursor: pointer !important;
    box-shadow: none !important;
    transition: all 0.16s ease !important;
  }

  .m-qcard-move-toggle.is-active {
    background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
    border-color: #7dd3fc !important;
    color: #ffffff !important;
    box-shadow: 0 2px 8px rgba(14, 165, 233, 0.38) !important;
  }

  .m-qcard-move-stepper {
    display: inline-flex !important;
    align-items: center !important;
    gap: 3px !important;
    padding: 2px !important;
    border-radius: 8px !important;
    background: rgba(15, 23, 42, 0.94) !important;
    border: 1px solid rgba(56, 189, 248, 0.48) !important;
    box-shadow: 0 3px 10px rgba(2, 6, 23, 0.35) !important;
  }

  button.m-qcard-move-step-btn {
    width: 24px !important;
    min-width: 24px !important;
    height: 24px !important;
    min-height: 24px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 6px !important;
    background: rgba(56, 189, 248, 0.18) !important;
    border: 1px solid rgba(56, 189, 248, 0.38) !important;
    color: #7dd3fc !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    box-shadow: none !important;
    transition: all 0.14s ease !important;
  }

  button.m-qcard-move-step-btn:active:not(:disabled) {
    background: #0284c7 !important;
    border-color: #38bdf8 !important;
    color: #ffffff !important;
    transform: scale(0.92) !important;
  }

  button.m-qcard-move-step-btn:disabled {
    opacity: 0.32 !important;
    cursor: not-allowed !important;
    background: rgba(51, 65, 85, 0.35) !important;
    border-color: rgba(71, 85, 105, 0.35) !important;
    color: #64748b !important;
  }

  .m-qcard-move-slide-enter-active,
  .m-qcard-move-slide-leave-active {
    transition: opacity 0.15s ease, transform 0.15s ease !important;
  }

  .m-qcard-move-slide-enter-from,
  .m-qcard-move-slide-leave-to {
    opacity: 0 !important;
    transform: translateX(6px) scale(0.92) !important;
  }

  .m-qcard-meta {
    display: flex !important;
    flex-direction: column !important;
    gap: 4px !important;
  }

  .m-qcard-pills {
    display: flex !important;
    align-items: center !important;
    flex-wrap: wrap !important;
    gap: 5px !important;
  }

  .m-qcard-pill {
    font-size: 10.5px !important;
    font-weight: 600 !important;
    color: #cbd5e1 !important;
    background: rgba(15, 23, 42, 0.75) !important;
    border: 1px solid rgba(71, 85, 105, 0.5) !important;
    padding: 1px 7px !important;
    border-radius: 5px !important;
    max-width: 100% !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }

  .m-qcard-pill.sku {
    color: #38bdf8 !important;
    border-color: rgba(56, 189, 248, 0.35) !important;
  }

  .m-qcard-pill.brand {
    color: #a78bfa !important;
    border-color: rgba(167, 139, 250, 0.35) !important;
  }

  .m-qcard-desc {
    font-size: 11.5px !important;
    color: #94a3b8 !important;
    line-height: 1.35 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    word-break: break-word !important;
  }

  .m-qcard-bottom {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    padding-top: 6px !important;
    border-top: 1px dashed rgba(71, 85, 105, 0.5) !important;
  }

  .m-qcard-calc {
    display: flex !important;
    align-items: center !important;
    flex-wrap: wrap !important;
    gap: 4px !important;
    font-size: 12px !important;
    min-width: 0 !important;
  }

  .m-qcard-qty {
    font-weight: 800 !important;
    color: #f8fafc !important;
    background: rgba(15, 23, 42, 0.8) !important;
    border: 1px solid rgba(71, 85, 105, 0.6) !important;
    padding: 1px 6px !important;
    border-radius: 5px !important;
    font-size: 11px !important;
  }

  .m-qcard-x {
    color: #64748b !important;
    font-weight: 700 !important;
  }

  .m-qcard-unit {
    font-weight: 700 !important;
    color: #cbd5e1 !important;
  }

  .m-qcard-total {
    font-size: 14.5px !important;
    font-weight: 900 !important;
    color: #10b981 !important;
    line-height: 1.2 !important;
    letter-spacing: -0.2px !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
  }

  /* Danh mục cha (Group Row) nhỏ gọn 1 dòng trên Mobile, nút chỉ hiện icon */
  .quote-table-wrap tr.group-row {
    display: flex !important;
    align-items: center !important;
    background: linear-gradient(90deg, rgba(16, 185, 129, 0.16) 0%, rgba(15, 23, 42, 0.85) 100%) !important;
    border: 1px solid rgba(16, 185, 129, 0.35) !important;
    border-left: 3px solid #10b981 !important;
    border-radius: 8px !important;
    margin: 4px 0 8px 0 !important;
    padding: 5px 10px !important;
    gap: 6px !important;
    touch-action: pan-y !important;
  }
  .quote-table-wrap tr.group-row td {
    display: flex !important;
    align-items: center !important;
    border: none !important;
    padding: 0 !important;
    background: transparent !important;
    font-size: 12px !important;
  }
  .quote-table-wrap tr.group-row td.group-stt {
    width: auto !important;
    flex-shrink: 0 !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
  }
  .quote-table-wrap tr.group-row td.group-stt i {
    display: none !important;
  }
  .quote-table-wrap tr.group-row td.group-title {
    flex: 1 !important;
    min-width: 0 !important;
    width: auto !important;
  }
  .quote-table-wrap tr.group-row .group-title-bar {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    width: 100% !important;
    min-width: 0 !important;
  }
  .quote-table-wrap tr.group-row .group-title-text {
    font-size: 11.5px !important;
    font-weight: 800 !important;
    line-height: 1.3 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    flex: 1 !important;
    min-width: 0 !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions {
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    flex-shrink: 0 !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions button {
    width: 26px !important;
    min-width: 26px !important;
    height: 26px !important;
    min-height: 26px !important;
    padding: 0 !important;
    margin: 0 !important;
    border-radius: 6px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 13px !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions button span {
    display: none !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions button.m-group-move-toggle {
    display: inline-flex !important;
    background: rgba(56, 189, 248, 0.16) !important;
    border: 1px solid rgba(56, 189, 248, 0.42) !important;
    color: #38bdf8 !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions button.m-group-move-toggle.is-active {
    background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
    border-color: #7dd3fc !important;
    color: #ffffff !important;
    box-shadow: 0 2px 8px rgba(14, 165, 233, 0.38) !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions .m-qcard-move-stepper.is-group-stepper {
    display: inline-flex !important;
  }
  .quote-table-wrap tr.group-row .group-row-actions .m-qcard-move-stepper.is-group-stepper button.m-qcard-move-step-btn {
    width: 23px !important;
    min-width: 23px !important;
    height: 23px !important;
    min-height: 23px !important;
  }
  .quote-table-wrap tr.group-row.is-move-active {
    border-color: rgba(56, 189, 248, 0.75) !important;
    box-shadow: 0 0 0 1px rgba(56, 189, 248, 0.28) !important;
  }

  /* KHỐI TỔNG KẾT MOBILE: TÁCH 2 CARD ĐỘC LẬP (CHIẾT KHẤU & TÀI CHÍNH) (.mobile-quote-summary-card) */
  .mobile-quote-summary-card {
    display: block !important;
    margin: 8px 12px 24px 12px !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
  }

  .m-sum-card {
    border-radius: 16px !important;
    background: rgba(15, 23, 42, 0.9) !important;
    border: 1px solid rgba(51, 65, 85, 0.85) !important;
    overflow: hidden !important;
    box-shadow: 0 10px 26px rgba(0, 0, 0, 0.24) !important;
  }

  .m-sum-card + .m-sum-card {
    margin-top: 12px !important;
  }

  .m-sum-card.is-discount {
    border-color: rgba(245, 158, 11, 0.34) !important;
  }

  .m-sum-card.is-finance {
    border-color: rgba(16, 185, 129, 0.36) !important;
  }

  .m-sum-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    padding: 11px 13px !important;
    background: rgba(30, 41, 59, 0.88) !important;
    border-bottom: 1px solid rgba(51, 65, 85, 0.7) !important;
  }

  .m-sum-discount-header {
    background: linear-gradient(90deg, rgba(245, 158, 11, 0.14) 0%, rgba(30, 41, 59, 0.88) 100%) !important;
    border-bottom-color: rgba(245, 158, 11, 0.25) !important;
  }

  .m-sum-finance-header {
    background: linear-gradient(90deg, rgba(16, 185, 129, 0.15) 0%, rgba(30, 41, 59, 0.88) 100%) !important;
    border-bottom-color: rgba(16, 185, 129, 0.26) !important;
  }

  .m-sum-title-group {
    display: inline-flex !important;
    align-items: center !important;
    gap: 8px !important;
    font-size: 12px !important;
    font-weight: 800 !important;
    color: #34d399 !important;
    letter-spacing: 0.35px !important;
    min-width: 0 !important;
  }

  .m-sum-discount-header .m-sum-title-group {
    color: #fbbf24 !important;
  }

  .m-sum-head-icon {
    width: 26px !important;
    height: 26px !important;
    border-radius: 7px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 13.5px !important;
    flex-shrink: 0 !important;
  }

  .m-sum-head-icon.is-amber {
    background: rgba(245, 158, 11, 0.18) !important;
    border: 1px solid rgba(245, 158, 11, 0.38) !important;
    color: #fbbf24 !important;
  }

  .m-sum-head-icon.is-emerald,
  .m-sum-head-icon.is-blue {
    background: rgba(16, 185, 129, 0.18) !important;
    border: 1px solid rgba(16, 185, 129, 0.4) !important;
    color: #34d399 !important;
  }

  .m-sum-currency-badge {
    font-size: 10.5px !important;
    font-weight: 800 !important;
    padding: 2px 8px !important;
    border-radius: 999px !important;
    letter-spacing: 0.4px !important;
    flex-shrink: 0 !important;
  }

  .m-sum-currency-badge.is-amber {
    background: rgba(245, 158, 11, 0.14) !important;
    border: 1px solid rgba(245, 158, 11, 0.32) !important;
    color: #fcd34d !important;
  }

  .m-sum-currency-badge.is-emerald,
  .m-sum-currency-badge.is-blue {
    background: rgba(16, 185, 129, 0.15) !important;
    border: 1px solid rgba(16, 185, 129, 0.35) !important;
    color: #6ee7b7 !important;
  }

  .m-sum-discount-badge {
    font-size: 11.5px !important;
    font-weight: 800 !important;
    font-variant-numeric: tabular-nums !important;
    color: #fbbf24 !important;
    background: rgba(245, 158, 11, 0.18) !important;
    border: 1px solid rgba(245, 158, 11, 0.4) !important;
    padding: 2px 9px !important;
    border-radius: 999px !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
  }

  .m-sum-body,
  .m-sum-discount-body {
    padding: 8px 13px 13px 13px !important;
    background: transparent !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 2px !important;
  }

  .m-sum-row {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    padding: 8px 0 !important;
    border-bottom: 1px solid rgba(51, 65, 85, 0.38) !important;
    font-size: 13.5px !important;
  }

  .m-sum-row.is-input-row {
    padding: 6px 0 !important;
  }

  .m-sum-row.is-last-plain,
  .m-sum-row:last-child {
    border-bottom: none !important;
  }

  .m-sum-label {
    color: #cbd5e1 !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    line-height: 1.3 !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 6px !important;
    flex-wrap: wrap !important;
    min-width: 0 !important;
  }

  .m-sum-val {
    color: #f8fafc !important;
    font-weight: 800 !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
  }

  .m-sum-num {
    font-size: 14px !important;
    font-weight: 800 !important;
    font-variant-numeric: tabular-nums !important;
    letter-spacing: -0.1px !important;
  }

  .m-sum-val.warn,
  .m-sum-val.warn .m-sum-num {
    color: #fbbf24 !important;
  }

  .m-sum-val.pos,
  .m-sum-val.pos .m-sum-num {
    color: #34d399 !important;
  }

  .m-sum-val.neg,
  .m-sum-val.neg .m-sum-num {
    color: #f87171 !important;
  }

  .m-sum-pct-pill {
    position: relative !important;
    display: inline-flex !important;
    align-items: center !important;
    width: 72px !important;
    height: 34px !important;
    flex-shrink: 0 !important;
  }

  input.m-sum-pct-input {
    width: 100% !important;
    height: 34px !important;
    min-height: 34px !important;
    padding: 0 21px 0 8px !important;
    margin: 0 !important;
    text-align: right !important;
    border-radius: 8px !important;
    border: 1px solid rgba(245, 158, 11, 0.38) !important;
    background: rgba(9, 14, 23, 0.85) !important;
    color: #fbbf24 !important;
    font-size: 16px !important;
    font-weight: 800 !important;
    font-variant-numeric: tabular-nums !important;
    box-sizing: border-box !important;
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.3) !important;
