  /* MODAL CHỌN KHÁCH HÀNG • LƯU & XUẤT BÁO GIÁ TRÊN MOBILE */
  .modal-card.save-export-cust-modal {
    display: flex !important;
    flex-direction: column !important;
    height: 100% !important;
    max-height: 100% !important;
    border-radius: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
  }

  .save-export-cust-modal .modal-head-themed {
    padding: 10px 42px 10px 12px !important;
    justify-content: flex-start !important;
    margin-bottom: 0 !important;
    flex-shrink: 0 !important;
  }

  .save-export-cust-modal .save-modal-head-title {
    font-size: 12.5px !important;
    line-height: 1.3 !important;
    text-align: left !important;
  }

  /* Thanh công cụ đầu Modal Khách hàng: Hàng 1 (Trạng thái + Reset), Hàng 2 (3 nút Import ngang nhau) */
  .save-export-cust-modal .cust-top-toolbar {
    padding: 8px 12px !important;
    gap: 7px !important;
    flex-direction: column !important;
    align-items: stretch !important;
    flex-shrink: 0 !important;
  }

  .save-export-cust-modal .cust-toolbar-status-row {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 6px !important;
    width: 100% !important;
    flex-wrap: wrap !important;
  }

  .save-export-cust-modal .cust-db-badge {
    padding: 3px 8px !important;
    font-size: 10px !important;
  }

  .save-export-cust-modal .cust-meta-chip {
    font-size: 11px !important;
  }

  .save-export-cust-modal .cust-last-updated-inline,
  .save-export-cust-modal .cust-dt-only-btn,
  .save-export-cust-modal .cust-import-btn .dt-lbl {
    display: none !important;
  }

  .save-export-cust-modal .cust-mobile-mini-actions {
    display: inline-flex !important;
    align-items: center !important;
    gap: 5px !important;
    margin-left: auto !important;
  }

  .save-export-cust-modal .cust-mini-btn {
    width: auto !important;
    min-width: max-content !important;
    height: 26px !important;
    min-height: 26px !important;
    padding: 0 9px !important;
    margin: 0 !important;
    border-radius: 6px !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    text-transform: uppercase !important;
    box-shadow: none !important;
  }

  .save-export-cust-modal .cust-mini-btn.save-db {
    background: #10b981 !important;
    color: #ffffff !important;
    border: none !important;
  }

  .save-export-cust-modal .cust-mini-btn.reset {
    background: rgba(239, 68, 68, 0.14) !important;
    color: #ef4444 !important;
    border: 1px solid rgba(239, 68, 68, 0.4) !important;
  }

  .save-export-cust-modal .cust-toolbar-import-row {
    display: grid !important;
    grid-template-columns: repeat(3, 1fr) !important;
    gap: 6px !important;
    width: 100% !important;
  }

  .save-export-cust-modal .cust-import-btn {
    width: 100% !important;
    height: 32px !important;
    min-height: 32px !important;
    padding: 0 6px !important;
    margin: 0 !important;
    border-radius: 7px !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 4px !important;
    white-space: nowrap !important;
  }

  .save-export-cust-modal .cust-import-btn .mb-lbl {
    display: inline !important;
  }

  /* Vùng cuộn Form Khách hàng */
  .modal-card.save-export-cust-modal > .save-modal-body-scroll {
    flex: 1 !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow-y: auto !important;
    padding: 10px 12px 16px 12px !important;
    gap: 10px !important;
  }

  .save-export-cust-modal .cust-group-box {
    padding: 12px !important;
    gap: 10px !important;
  }

  .save-export-cust-modal input,
  .save-export-cust-modal select {
    height: 38px !important;
    min-height: 38px !important;
    font-size: 13px !important;
    border-radius: 8px !important;
  }

  /* Sửa dứt điểm lỗi nút CHỌN (.inline-picker-btn) bị ép width: 100% đè lên ô input */
  .modal-card button.inline-picker-btn {
    position: absolute !important;
    right: 5px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: auto !important;
    min-width: max-content !important;
    height: 28px !important;
    min-height: 28px !important;
    padding: 0 10px !important;
    margin: 0 !important;
    border-radius: 6px !important;
    font-size: 11px !important;
    font-weight: 800 !important;
    line-height: 1 !important;
    z-index: 5 !important;
    box-shadow: none !important;
  }

  .modal-card .input-with-picker input {
    padding-right: 64px !important;
  }

  /* Accordion thu gọn các mục phụ (KH phụ, PO Tiếng Anh, Công nợ & Ghi chú HĐ) trên Mobile */
  .save-export-cust-modal .mobile-cust-accordion-btn {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    height: 36px !important;
    min-height: 36px !important;
    padding: 0 12px !important;
    margin: 0 !important;
    border-radius: 8px !important;
    background: rgba(30, 41, 59, 0.7) !important;
    border: 1px dashed rgba(148, 163, 184, 0.4) !important;
    color: #cbd5e1 !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
    box-shadow: none !important;
  }

  .page.theme-light-blue .save-export-cust-modal .mobile-cust-accordion-btn {
    background: #f1f5f9 !important;
    border-color: #94a3b8 !important;
    color: #1e3a8a !important;
  }

  .save-export-cust-modal .cust-collapsible-sub:not(.is-mobile-open),
  .save-export-cust-modal .cust-collapsible-debt:not(.is-mobile-open) {
    display: none !important;
  }

  /* Cụm 3 nút Footer xếp 2 hàng gọn gàng (Hàng 1: Lưu tạm | Xuất & In, Hàng 2: Chốt Deal) */
  .save-export-cust-modal .save-modal-actions {
    position: relative !important;
    bottom: auto !important;
    margin: 0 !important;
    width: 100% !important;
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px)) 12px !important;
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
    flex-shrink: 0 !important;
    box-sizing: border-box !important;
  }

  .save-export-cust-modal .save-modal-actions button {
    width: 100% !important;
    height: 40px !important;
    min-height: 40px !important;
    margin: 0 !important;
    padding: 0 10px !important;
    border-radius: 8px !important;
    font-size: 12px !important;
    white-space: nowrap !important;
  }

  .save-export-cust-modal .save-modal-actions-3btn .btn-save-temp {
    grid-column: 1 / 2 !important;
    order: 1 !important;
  }

  .save-export-cust-modal .save-modal-actions-3btn .btn-save-export {
    grid-column: 2 / 3 !important;
    order: 2 !important;
  }

  .save-export-cust-modal .save-modal-actions-3btn .btn-save-deal {
    grid-column: 1 / -1 !important;
    order: 3 !important;
    height: 42px !important;
    min-height: 42px !important;
    font-size: 12.5px !important;
  }

