  /* ================= MODALS TRÊN MOBILE ================= */
  .modal-card [style*="grid"]:not([style*="display: none"]):not([style*="display:none"]):not(.quote-edit-tab-panel):not(.quote-edit-tab-group):not(.qe-2col-mobile):not(.save-modal-actions-3btn):not(.cust-toolbar-import-row) {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px !important;
    align-items: stretch !important;
    width: 100% !important;
    box-sizing: border-box !important;
  }

  .modal-card input, .modal-card textarea, .modal-card select {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    height: 48px !important;
    font-size: 14.5px !important;
    border-radius: 10px !important;
    background: rgba(15, 23, 42, 0.6) !important;
    border: 1px solid rgba(255,255,255,0.1) !important;
    padding: 0 14px !important;
    color: #f8fafc !important;
    transition: all 0.25s ease !important;
  }
  .modal-card textarea:not(.m-wrap-input) {
    height: auto !important;
    min-height: 96px !important;
    padding: 14px !important;
  }
  .modal-card input:focus, .modal-card textarea:focus {
    border-color: #38bdf8 !important;
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2) !important;
    background: rgba(15, 23, 42, 0.9) !important;
  }

  .modal-card button {
    height: auto !important;
    min-height: 48px !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    border-radius: 12px !important;
    width: 100% !important;
    margin-bottom: 10px !important;
    letter-spacing: 0.2px;
    box-shadow: 0 4px 15px rgba(0,0,0,0.1);
    white-space: normal !important;
    line-height: 1.3 !important;
    padding: 10px 14px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
  }

  .modal-card .export-vip-btn {
    height: auto !important;
    min-height: 90px !important;
    padding: 16px 20px !important;
  }

  .modal-card .modal-head .x,
  .modal-card .export-vip-close,
  .modal-card .modal-close,
  .history-modal-header .x {
    width: 34px !important;
    min-width: 34px !important;
    max-width: 34px !important;
    height: 34px !important;
    min-height: 34px !important;
    max-height: 34px !important;
    margin-bottom: 0 !important;
    padding: 0 !important;
    flex-shrink: 0 !important;
  }
  .modal-head h3, .export-vip-title, .modal-header h3 {
    flex: 1 !important;
    white-space: normal !important;
    line-height: 1.4 !important;
    padding-right: 12px !important;
  }

  .mapping-config-table input,
  .mapping-config-table select {
    height: 34px !important;
    font-size: 13px !important;
    border-radius: 6px !important;
    background: #ffffff !important;
    color: #1e293b !important;
    padding: 0 10px !important;
  }
  .mapping-config-table button {
    width: 34px !important;
    min-width: 34px !important;
    height: 34px !important;
    margin-bottom: 0 !important;
    border-radius: 6px !important;
    padding: 0 !important;
    box-shadow: none !important;
  }

  .modal-card:not(.save-export-cust-modal):not(.modal-fullscreen-card) > div[style*="overflow-y: auto"] {
    max-height: none !important;
    overflow: visible !important;
  }

  .modal-card:not(.save-export-cust-modal):not(.modal-fullscreen-card) .save-modal-actions {
    position: sticky !important;
    bottom: calc(-16px - env(safe-area-inset-bottom, 24px)) !important;
    background: #0f172a !important;
    z-index: 20 !important;
    margin: 0 -16px calc(-16px - env(safe-area-inset-bottom, 24px)) -16px !important;
    padding: 16px !important;
    padding-bottom: calc(16px + env(safe-area-inset-bottom, 24px)) !important;
    border-top: 1px solid rgba(255,255,255,0.1) !important;
  }

  /* FULLSCREEN MODAL TRÊN ĐIỆN THOẠI (NỀN HEADER TRÀN LÊN MÉP TRÊN NHƯ GRAB) */
  .modal,
  .vip-modal-overlay,
  .load-invoice-modal-overlay,
  .modal-overlay,
  .modal.modal-fullscreen-overlay {
    position: fixed !important;
    inset: 0 !important;
    padding: 0 !important;
    align-items: center !important;
    justify-content: center !important;
    width: 100% !important;
    height: auto !important;
    max-height: none !important;
    transform: none !important;
    overscroll-behavior: contain !important;
    box-sizing: border-box !important;
  }

  .modal-card,
  .vip-modal-card,
  .load-invoice-modal,
  .modal-content {
    width: 100% !important;
    max-width: 100% !important;
    height: 100% !important;
    max-height: 100% !important;
    margin: 0 !important;
    padding: 16px !important;
    padding-bottom: calc(16px + env(safe-area-inset-bottom, 24px)) !important;
    box-sizing: border-box;
    border-radius: 0 !important;
    background: #0f172a !important;
    border: none !important;
    box-shadow: none !important;
    animation: slideInLeftMobile 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) forwards !important;
    overflow-y: auto !important;
    overscroll-behavior: contain !important;
  }
  @keyframes slideInLeftMobile {
    from { transform: translateX(-100%); opacity: 0.5; }
    to { transform: translateX(0); opacity: 1; }
  }

  .modal-card > div[style*="padding: 24px"] {
    padding: 0 !important;
  }

  /* ═══════════════════════════════════════════════════
     GHI ĐÈ CUỐI CÙNG CHO MODAL KHÁCH HÀNG & NÚT CHỌN (.inline-picker-btn)
     ═══════════════════════════════════════════════════ */
  .modal-card .input-with-picker button.inline-picker-btn,
  .modal-card button.inline-picker-btn {
    position: absolute !important;
    right: 5px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: auto !important;
    min-width: max-content !important;
    height: 28px !important;
    min-height: 28px !important;
    padding: 0 10px !important;
    margin: 0 !important;
    border-radius: 6px !important;
    font-size: 11px !important;
    font-weight: 800 !important;
    line-height: 1 !important;
    z-index: 5 !important;
    box-shadow: none !important;
  }

  .modal-card .input-with-picker input {
    padding-right: 64px !important;
  }

  .modal .modal-card.save-export-cust-modal {
    display: flex !important;
    flex-direction: column !important;
    height: 100% !important;
    max-height: 100% !important;
    border-radius: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
  }

  .modal .modal-card.save-export-cust-modal > .save-modal-body-scroll {
    flex: 1 !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow-y: auto !important;
    padding: 10px 12px 16px 12px !important;
    gap: 10px !important;
  }

  .modal .modal-card.save-export-cust-modal .cust-mini-btn {
    width: auto !important;
    min-width: max-content !important;
    height: 26px !important;
    min-height: 26px !important;
    padding: 0 9px !important;
    margin: 0 !important;
    border-radius: 6px !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    box-shadow: none !important;
  }

  .modal .modal-card.save-export-cust-modal .cust-toolbar-import-row {
    display: grid !important;
    grid-template-columns: repeat(3, 1fr) !important;
    gap: 6px !important;
    width: 100% !important;
  }

  .modal .modal-card.save-export-cust-modal .cust-import-btn {
    width: 100% !important;
    height: 32px !important;
    min-height: 32px !important;
    padding: 0 6px !important;
    margin: 0 !important;
    border-radius: 7px !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
  }

  .modal .modal-card.save-export-cust-modal .mobile-cust-accordion-btn {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    height: 36px !important;
    min-height: 36px !important;
    padding: 0 12px !important;
    margin: 0 !important;
    border-radius: 8px !important;
    font-size: 11.5px !important;
    font-weight: 800 !important;
    box-shadow: none !important;
  }

  .modal .modal-card.save-export-cust-modal .save-modal-actions {
    position: relative !important;
    bottom: auto !important;
    margin: 0 !important;
    width: 100% !important;
    padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px)) 12px !important;
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
    flex-shrink: 0 !important;
    box-sizing: border-box !important;
  }

  .modal .modal-card.save-export-cust-modal .save-modal-actions button {
    width: 100% !important;
    height: 40px !important;
    min-height: 40px !important;
    margin: 0 !important;
    padding: 0 10px !important;
    border-radius: 8px !important;
    font-size: 12px !important;
    white-space: nowrap !important;
  }

  .modal .modal-card.save-export-cust-modal .save-modal-actions-3btn .btn-save-temp {
    grid-column: 1 / 2 !important;
    order: 1 !important;
  }

  .modal .modal-card.save-export-cust-modal .save-modal-actions-3btn .btn-save-export {
    grid-column: 2 / 3 !important;
    order: 2 !important;
  }

  .modal .modal-card.save-export-cust-modal .save-modal-actions-3btn .btn-save-deal {
    grid-column: 1 / -1 !important;
    order: 3 !important;
    height: 42px !important;
    min-height: 42px !important;
    font-size: 12.5px !important;
  }

  ::-webkit-scrollbar {
    width: 4px;
    height: 4px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 4px;
  }
}

/* ═══════════════════════════════════════════════════
   THANH QUẢN LÝ ĐA TAB BÁO GIÁ (TOP HEADER BAR)
   ═══════════════════════════════════════════════════ */
.quote-workspace-topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.96) 0%, rgba(9, 9, 11, 0.96) 100%);
  border-bottom: 1px solid rgba(56, 189, 248, 0.18);
  flex-shrink: 0;
  z-index: 36;
  min-width: 0;
}

.btn-add-quote-tab-circle {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  min-height: 28px !important;
  max-width: 28px !important;
  max-height: 28px !important;
  border-radius: 50% !important;
  background: #10b981 !important;
  background-image: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  color: #ffffff !important;
  border: 1px solid rgba(52, 211, 153, 0.5) !important;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.35) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  flex-shrink: 0 !important;
  flex-grow: 0 !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
}

.btn-add-quote-tab-circle:hover {
  background: #059669 !important;
  background-image: linear-gradient(135deg, #059669 0%, #047857 100%) !important;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.55) !important;
  transform: scale(1.08) !important;
}

.btn-add-quote-tab-circle:active {
  transform: scale(0.95) !important;
  box-shadow: 0 1px 4px rgba(16, 185, 129, 0.4) !important;
}

.quote-tabs-scroll {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  overflow-y: hidden;
  flex: 1;
  min-width: 0;
  padding-bottom: 2px;
  scrollbar-width: thin;
}

.quote-tabs-scroll::-webkit-scrollbar {
  height: 4px;
}

.quote-tabs-scroll::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.4);
  border-radius: 4px;
}

.quote-tab-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px 6px 12px;
  border-radius: 8px;
  background: rgba(30, 41, 59, 0.65);
  border: 1px solid rgba(51, 65, 85, 0.8);
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  flex-shrink: 0;
  transition: all 0.18s ease;
  position: relative;
}

.quote-tab-item:hover {
  background: rgba(30, 41, 59, 0.95);
  border-color: rgba(100, 116, 139, 0.8);
  color: #e2e8f0;
}

.quote-tab-item.active {
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.98) 0%, rgba(30, 41, 59, 0.98) 100%);
  border-color: #10b981;
  color: #ffffff;
  font-weight: 700;
  box-shadow: 0 2px 10px rgba(16, 185, 129, 0.18), inset 0 2px 0 #10b981;
}

.quote-tab-item.editing.active {
  border-color: #38bdf8;
  box-shadow: 0 2px 10px rgba(56, 189, 248, 0.2), inset 0 2px 0 #38bdf8;
}

.quote-tab-icon {
  flex-shrink: 0;
  color: #64748b;
  transition: color 0.18s ease;
}

.quote-tab-item.active .quote-tab-icon {
  color: #10b981;
}

.quote-tab-item.editing.active .quote-tab-icon {
  color: #38bdf8;
}

.quote-tab-title {
  max-width: 210px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.3;
}

.quote-tab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  background: rgba(148, 163, 184, 0.16);
  color: #cbd5e1;
  border: 1px solid rgba(148, 163, 184, 0.25);
  line-height: 1.3;
}

.quote-tab-item.active .quote-tab-badge {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.4);
  cursor: pointer;
  transition: all 0.15s ease;
}

.quote-tab-item.active .quote-tab-badge:hover {
  background: rgba(16, 185, 129, 0.32);
  color: #ffffff;
  border-color: #10b981;
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.35);
}

.quote-tab-close {
  width: 20px !important;
  min-width: 20px !important;
  height: 20px !important;
  padding: 0 !important;
  margin: 0 0 0 2px !important;
  border-radius: 5px !important;
  border: none !important;
  background: transparent !important;
  color: #64748b !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer;
  transition: all 0.15s ease !important;
  box-shadow: none !important;
}

.quote-tab-close:hover {
  background: rgba(239, 68, 68, 0.2) !important;
  color: #f87171 !important;
  transform: none !important;
}

