/* Mobile Card Mode Badge Above Product Name & Vertical 3-Price Comparison */
.m-qcard-head-col {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
  flex: 1;
  min-width: 0;
}
.m-qcard-mode-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
.m-qcard-mode-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.3px;
  line-height: 1.3;
  white-space: nowrap;
}
.m-qcard-mode-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  flex-shrink: 0;
}
.m-qcard-mode-badge.is-mode-origin {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.42);
  color: #fbbf24;
}
.m-qcard-mode-badge.is-mode-origin .m-qcard-mode-dot {
  background: #f59e0b;
  box-shadow: 0 0 5px rgba(245, 158, 11, 0.6);
}
.m-qcard-mode-badge.is-mode-customer {
  background: rgba(59, 130, 246, 0.16);
  border: 1px solid rgba(59, 130, 246, 0.42);
  color: #60a5fa;
}
.m-qcard-mode-badge.is-mode-customer .m-qcard-mode-dot {
  background: #3b82f6;
  box-shadow: 0 0 5px rgba(59, 130, 246, 0.6);
}
.m-qcard-mode-badge.is-mode-contract {
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(16, 185, 129, 0.42);
  color: #34d399;
}
.m-qcard-mode-badge.is-mode-contract .m-qcard-mode-dot {
  background: #10b981;
  box-shadow: 0 0 5px rgba(16, 185, 129, 0.6);
}
.m-qcard-mode-badge.is-mode-compare {
  background: rgba(139, 92, 246, 0.18);
  border: 1px solid rgba(139, 92, 246, 0.48);
  color: #c4b5fd;
}
.m-qcard-mode-badge.is-mode-compare .m-qcard-mode-dot {
  background: #8b5cf6;
  box-shadow: 0 0 5px rgba(139, 92, 246, 0.65);
}

.page.theme-light-blue .m-qcard-mode-badge.is-mode-origin {
  background: #fffbeb;
  border-color: #fcd34d;
  color: #b45309;
}
.page.theme-light-blue .m-qcard-mode-badge.is-mode-customer {
  background: #eff6ff;
  border-color: #93c5fd;
  color: #1d4ed8;
}
.page.theme-light-blue .m-qcard-mode-badge.is-mode-contract {
  background: #ecfdf5;
  border-color: #6ee7b7;
  color: #047857;
}
.page.theme-light-blue .m-qcard-mode-badge.is-mode-compare {
  background: #f5f3ff;
  border-color: #c4b5fd;
  color: #6d28d9;
}

.m-qcard-compare-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed rgba(148, 163, 184, 0.25);
}
.m-qcard-cmp-col {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 3px;
  padding: 7px 10px;
  border-radius: 7px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.m-qcard-cmp-col.is-list {
  background: rgba(59, 130, 246, 0.14);
  border: 1px solid rgba(59, 130, 246, 0.32);
}
.m-qcard-cmp-col.is-cust {
  background: rgba(16, 185, 129, 0.14);
  border: 1px solid rgba(16, 185, 129, 0.32);
}
.m-qcard-cmp-col.is-cont {
  background: rgba(245, 158, 11, 0.14);
  border: 1px solid rgba(245, 158, 11, 0.32);
}
.m-qcard-cmp-lbl {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2px;
  white-space: nowrap;
  margin-bottom: 1px;
}
.m-qcard-cmp-col.is-list .m-qcard-cmp-lbl { color: #93c5fd; }
.m-qcard-cmp-col.is-cust .m-qcard-cmp-lbl { color: #6ee7b7; }
.m-qcard-cmp-col.is-cont .m-qcard-cmp-lbl { color: #fcd34d; }
.m-qcard-cmp-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.m-qcard-cmp-k {
  font-size: 11px;
  font-weight: 600;
  color: #cbd5e1;
  white-space: nowrap;
}
.m-qcard-cmp-dg {
  font-size: 11.5px;
  font-weight: 700;
  color: #e2e8f0;
  white-space: nowrap;
}
.m-qcard-cmp-tt {
  font-size: 12px;
  font-weight: 800;
  color: #ffffff;
  white-space: nowrap;
}

.m-qcard-cmp-bottom-metrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  cursor: pointer;
}
.m-qcard-cmp-metric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 9px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(71, 85, 105, 0.5);
  font-variant-numeric: tabular-nums;
}
.m-qcard-cmp-metric.is-margin {
  align-items: flex-end;
  text-align: right;
}
.m-qcard-cmp-metric.is-margin.is-pos {
  background: rgba(16, 185, 129, 0.12);
  border-color: rgba(16, 185, 129, 0.35);
}
.m-qcard-cmp-metric.is-margin.is-neg {
  background: rgba(239, 68, 68, 0.12);
  border-color: rgba(239, 68, 68, 0.35);
}
.m-qcard-cmp-metric-lbl {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.3px;
  color: #94a3b8;
}
.m-qcard-cmp-metric-val {
  font-size: 11.5px;
  font-weight: 800;
  color: #10b981;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-wrap: wrap;
}
.m-qcard-cmp-metric-pct {
  font-style: normal;
  font-size: 10px;
  font-weight: 700;
  color: #34d399;
}
.m-qcard-cmp-metric.is-margin.is-pos .m-qcard-cmp-metric-val {
  color: #34d399;
}
.m-qcard-cmp-metric.is-margin.is-neg .m-qcard-cmp-metric-val {
  color: #f87171;
}
.m-qcard-cmp-arrow {
  font-size: 10px;
}

.page.theme-light-blue .m-qcard-cmp-col.is-list {
  background: #dbeafe;
  border-color: #93c5fd;
}
.page.theme-light-blue .m-qcard-cmp-col.is-cust {
  background: #dcfce7;
  border-color: #86efac;
}
.page.theme-light-blue .m-qcard-cmp-col.is-cont {
  background: #fef3c7;
