/* ==========================================================================
   COST VS SELLING PRICE DIFF PILL & QUICK MARKUP CALCULATOR
   ========================================================================== */
.cost-diff-pill {
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}

.cost-diff-pill.is-up {
  background: rgba(16, 185, 129, 0.14);
  border: 1px solid rgba(16, 185, 129, 0.36);
  color: #34d399;
}

.cost-diff-pill.is-down {
  background: rgba(244, 63, 94, 0.14);
  border: 1px solid rgba(244, 63, 94, 0.36);
  color: #fb7185;
}

.cost-diff-pill.is-neutral {
  background: rgba(148, 163, 184, 0.16);
  border: 1px solid rgba(148, 163, 184, 0.32);
  color: #cbd5e1;
}

.cost-markup-quick-box {
  margin-top: 2px;
  padding: 4px 8px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px dashed rgba(148, 163, 184, 0.28);
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-wrap: wrap;
}

.cost-markup-quick-label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.cost-markup-quick-controls {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-wrap: nowrap;
  margin-left: auto;
}

#app .page .modal-card .cost-markup-select.is-dir {
  height: 26px !important;
  min-height: 26px !important;
  padding: 0 6px !important;
  border-radius: 6px !important;
  background: rgba(30, 41, 59, 0.9) !important;
  border: 1px solid rgba(148, 163, 184, 0.28) !important;
  color: #f8fafc !important;
  font-size: 11.5px !important;
  font-weight: 700 !important;
  cursor: pointer;
  width: auto !important;
  margin: 0 !important;
}

#app .page .modal-card .cost-markup-select.is-dir.is-up {
  color: #34d399 !important;
  border-color: rgba(16, 185, 129, 0.35) !important;
  background: rgba(16, 185, 129, 0.1) !important;
}

#app .page .modal-card .cost-markup-select.is-dir.is-down {
  color: #fb7185 !important;
  border-color: rgba(244, 63, 94, 0.35) !important;
  background: rgba(244, 63, 94, 0.1) !important;
}

.cost-markup-input-group {
  display: inline-flex;
  align-items: center;
  height: 26px;
  border-radius: 6px;
  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(30, 41, 59, 0.9);
  overflow: hidden;
}

#app .page .modal-card .cost-markup-input-group input.cost-markup-num-input {
  width: 76px !important;
  height: 24px !important;
  min-height: 24px !important;
  padding: 0 6px !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: #f8fafc !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  text-align: right !important;
  font-variant-numeric: tabular-nums !important;
  box-shadow: none !important;
  margin: 0 !important;
}

#app .page .modal-card .cost-markup-input-group select.cost-markup-select.is-unit {
  width: auto !important;
  height: 24px !important;
  min-height: 24px !important;
  padding: 0 5px !important;
  border: none !important;
  border-left: 1px solid rgba(148, 163, 184, 0.25) !important;
  border-radius: 0 !important;
  background: rgba(15, 23, 42, 0.5) !important;
  color: #cbd5e1 !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  cursor: pointer;
  margin: 0 !important;
  box-shadow: none !important;
}

.cost-markup-select option {
  background: #1e293b;
  color: #f8fafc;
}

