/* ==========================================================================
   MODAL 1: TẢI FILE / DÁN ẢNH BÁO GIÁ (CTRL+V / DRAG & DROP / PICKER)
   ========================================================================== */
.tpl-upload-modal-card {
  max-width: 680px !important;
  width: 94vw !important;
  max-height: 90vh !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
  border-radius: 14px !important;
}

.tpl-upload-modal-body {
  padding: 18px 22px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
  min-height: 0;
}

.tpl-upload-dropzone {
  border: 2px dashed rgba(148, 163, 184, 0.35);
  border-radius: 12px;
  padding: 26px 20px;
  text-align: center;
  background: rgba(15, 23, 42, 0.45);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  transition: all 0.18s ease;
}

.tpl-upload-dropzone.is-compact {
  padding: 16px 16px;
}

.tpl-upload-dropzone:hover,
.tpl-upload-dropzone.is-dragging {
  border-color: #38bdf8;
  background: rgba(56, 189, 248, 0.08);
}

.tpl-upload-drop-icon {
  font-size: 32px;
  color: #38bdf8;
  line-height: 1;
}

.tpl-upload-dropzone.is-compact .tpl-upload-drop-icon {
  font-size: 24px;
}

.tpl-upload-drop-title {
  font-size: 13.5px;
  font-weight: 700;
  color: #f8fafc;
}

.tpl-upload-drop-title kbd {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 800;
  background: rgba(56, 189, 248, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.45);
  color: #38bdf8;
  font-family: inherit;
}

.tpl-upload-drop-sub {
  font-size: 12px;
  color: #94a3b8;
}

.tpl-upload-drop-actions {
  margin-top: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}

.tpl-upload-pick-btn {
  padding: 7px 14px !important;
  font-size: 12px !important;
  border-radius: 7px !important;
}

.tpl-upload-staged-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tpl-upload-staged-head {
  font-size: 12px;
  font-weight: 700;
  color: #cbd5e1;
}

.tpl-upload-staged-head small {
  font-weight: 500;
  color: #94a3b8;
}

.tpl-upload-staged-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 180px;
  overflow-y: auto;
  padding-right: 4px;
}

.file-box-dt-only {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.file-box-mob-trigger,
.tpl-sheet-mob-only-top,
.tpl-upload-mob-picker-box,
.mob-btn-text,
.read-price-mob-topstrip,
.read-price-mob-goto-price-btn,
.read-price-mob-selected-banner,
.read-price-mob-inline-note {
  display: none;
}

.tpl-upload-staged-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(148, 163, 184, 0.2);
  cursor: pointer;
  transition: all 0.15s ease;
}

.tpl-upload-staged-item.is-active {
  border-color: rgba(56, 189, 248, 0.55);
  background: rgba(56, 189, 248, 0.07);
}

.tpl-upload-staged-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tpl-upload-staged-meta-left {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-wrap: wrap;
}

.tpl-upload-staged-icon {
  font-size: 17px;
  color: #38bdf8;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
}

.tpl-upload-size-text {
  font-size: 11.5px;
  color: #94a3b8;
  white-space: nowrap;
}

.tpl-upload-name-edit-row {
  display: flex;
  align-items: center;
  width: 100%;
}

.tpl-upload-name-input {
  width: 100% !important;
  flex: 1;
  min-width: 0;
  padding: 7px 11px !important;
  border-radius: 7px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  background: rgba(15, 23, 42, 0.75) !important;
  border: 1px solid rgba(148, 163, 184, 0.28) !important;
  color: #f8fafc !important;
  margin: 0 !important;
}

.tpl-upload-ext-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(148, 163, 184, 0.16);
  color: #cbd5e1;
  flex-shrink: 0;
}

.tpl-upload-clip-tag {
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 10.5px;
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
  font-weight: 700;
  white-space: nowrap;
}

.tpl-upload-foot-cta-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.tpl-upload-img-preview-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border-radius: 9px;
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.tpl-upload-img-preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
}

.tpl-upload-img-preview-frame {
  max-height: 200px;
  overflow: hidden;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: zoom-in;
}

.tpl-upload-img-preview-frame img {
  max-width: 100%;
  max-height: 200px;
  object-fit: contain;
  display: block;
}

.tpl-upload-modal-foot {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 10px !important;
  padding: 13px 22px !important;
  border-top: 1px solid rgba(148, 163, 184, 0.16) !important;
  flex-wrap: wrap !important;
}

.tpl-upload-attach-only-btn {
  padding: 9px 16px !important;
  border-radius: 8px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  background: rgba(255, 255, 255, 0.06) !important;
  border: 1px solid rgba(148, 163, 184, 0.3) !important;
  color: #e2e8f0 !important;
  cursor: pointer !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  width: auto !important;
  margin: 0 !important;
  transition: all 0.15s ease !important;
}

.tpl-upload-attach-only-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.12) !important;
  border-color: rgba(148, 163, 184, 0.5) !important;
  color: #ffffff !important;
}

.tpl-upload-read-cta-btn {
  padding: 9px 20px !important;
  border-radius: 8px !important;
  font-size: 13.5px !important;
  font-weight: 700 !important;
  background: linear-gradient(135deg, #10b981, #059669) !important;
  border: none !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.28) !important;
  cursor: pointer !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  width: auto !important;
  margin: 0 !important;
  transition: all 0.15s ease !important;
}

.tpl-upload-read-cta-btn:hover:not(:disabled) {
  box-shadow: 0 6px 16px rgba(16, 185, 129, 0.42) !important;
  transform: translateY(-1px);
}

.tpl-upload-attach-only-btn:disabled,
.tpl-upload-read-cta-btn:disabled {
  opacity: 0.45 !important;
  cursor: not-allowed !important;
  transform: none !important;
  box-shadow: none !important;
}

/* Light Mode overrides for Upload / Paste Modal */
.page.theme-light-blue .tpl-upload-dropzone {
  background: #f8fafc !important;
