}

/* ==========================================================================
   MODAL 2: XÁC NHẬN GIÁ ĐỌC ĐƯỢC TỪ FILE (FULLSCREEN 100% - PHƯƠNG ÁN A 2 CỘT)
   ========================================================================== */
.read-price-subbar {
  background: rgba(15, 23, 42, 0.75);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.read-price-2col-grid {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 20px;
  padding: 20px 24px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  align-items: stretch;
}

.read-price-left-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.read-price-cur-vat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.read-price-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 14px 24px;
  margin-top: 0;
  flex-shrink: 0;
  flex-wrap: wrap;
}

.read-price-footer-btns {
  display: flex;
  align-items: center;
  gap: 12px;
}

.read-price-cancel-btn {
  width: auto !important;
  margin: 0 !important;
  padding: 10px 26px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 14px;
}

.read-price-col-group {
  margin: 0 !important;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
}

.read-price-search-box {
  position: relative;
  display: inline-flex;
  align-items: center;
  width: 280px;
  max-width: 100%;
}

.read-price-search-box i {
  position: absolute;
  left: 10px;
  font-size: 14px;
  color: #94a3b8;
  pointer-events: none;
}

.read-price-search-box input {
  width: 100% !important;
  padding: 7px 28px 7px 32px !important;
  border-radius: 7px !important;
  font-size: 12.5px !important;
  background: rgba(15, 23, 42, 0.65) !important;
  border: 1px solid rgba(148, 163, 184, 0.25) !important;
  color: #f8fafc !important;
  margin: 0 !important;
}

.read-price-search-clear {
  position: absolute !important;
  right: 6px !important;
  width: 20px !important;
  height: 20px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  background: transparent !important;
  color: #94a3b8 !important;
  font-size: 12px !important;
  cursor: pointer !important;
}

.read-price-rows-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  max-height: 310px;
  overflow-y: auto;
  padding-right: 4px;
}

.read-price-row-item {
  padding: 10px 12px;
  border-radius: 9px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(148, 163, 184, 0.18);
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.read-price-row-item:hover {
  border-color: rgba(56, 189, 248, 0.45);
  background: rgba(30, 41, 59, 0.7);
}

.read-price-row-item.is-selected {
  background: rgba(2, 132, 199, 0.14);
  border-color: #38bdf8;
}

.read-price-row-radio {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 800;
  color: #94a3b8;
  flex-shrink: 0;
}

.read-price-row-item.is-selected .read-price-row-radio {
  color: #38bdf8;
}

.read-price-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.read-price-row-title {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.read-price-best-badge {
  font-size: 9.5px;
  font-weight: 800;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(2, 132, 199, 0.22);
  border: 1px solid rgba(56, 189, 248, 0.45);
  color: #38bdf8;
  letter-spacing: 0.3px;
}

.read-price-row-meta {
  font-size: 11.5px;
  color: #94a3b8;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.read-price-row-meta strong {
  color: #cbd5e1;
}

.read-price-row-price {
  text-align: right;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.read-price-row-cost {
  font-size: 12px;
  color: #cbd5e1;
}

.read-price-row-cost strong {
  color: #f8fafc;
}

.read-price-row-vat {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 600;
}

.read-price-selected-detail-card {
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(148, 163, 184, 0.18);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.read-price-detail-card-head {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #94a3b8;
  padding-bottom: 6px;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.2);
}

.read-price-detail-kv-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 14px;
}

.read-price-kv-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.read-price-kv-item.is-full {
  grid-column: 1 / -1;
}

.read-price-kv-label {
  font-size: 11px;
  color: #94a3b8;
}

.read-price-kv-val {
  font-size: 12.5px;
  color: #f8fafc;
  word-break: break-word;
}

.read-price-kv-desc {
  font-size: 12px;
  color: #cbd5e1;
  line-height: 1.45;
  white-space: pre-line;
  max-height: 84px;
  overflow-y: auto;
}

.read-price-source-img-box {
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(148, 163, 184, 0.18);
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 180px;
}

.read-price-source-img-frame {
  flex: 1;
  min-height: 160px;
  max-height: 300px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.28);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: zoom-in;
}

.read-price-source-img-frame img {
  max-width: 100%;
  max-height: 300px;
  object-fit: contain;
  display: block;
}

.read-price-compare-box {
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.45);
  border: 1px solid rgba(148, 163, 184, 0.2);
  overflow: hidden;
  font-size: 12px;
}

.read-price-compare-head {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr;
  gap: 8px;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.04);
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  color: #94a3b8;
}

.read-price-compare-row {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.14);
  align-items: center;
}

.read-price-compare-row:last-child {
  border-bottom: none;
}

.read-price-compare-label {
  color: #cbd5e1;
  font-weight: 600;
}

.read-price-compare-old {
  color: #94a3b8;
}

.read-price-compare-new {
  color: #f8fafc;
  font-weight: 700;
}

.read-price-compare-new.is-primary {
  color: #34d399;
}

.read-price-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.read-price-field-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #ffffff;
}

.read-price-field-label.is-cost {
  color: #fbbf24;
}

.read-price-select {
  width: 100% !important;
  padding: 10px 14px !important;
  border-radius: 8px !important;
  background: rgba(255, 255, 255, 0.06) !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  color: #f8fafc !important;
  font-weight: 600 !important;
  font-size: 13px !important;
  cursor: pointer;
}

.read-price-select option {
  background: #1e293b;
  color: #f8fafc;
}

.read-price-input.is-cost {
  color: #fbbf24 !important;
}

.read-price-input.is-sale {
  color: #10b981 !important;
  border-color: rgba(16, 185, 129, 0.3) !important;
  background: rgba(16, 185, 129, 0.05) !important;
}

.read-price-apply-info-check {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 12.5px;
  font-weight: 600;
  color: #e2e8f0;
  cursor: pointer;
  padding: 10px 12px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(148, 163, 184, 0.22);
}

.read-price-apply-info-check input[type="checkbox"] {
  width: 16px !important;
  height: 16px !important;
  margin: 0 !important;
  accent-color: #10b981;
  cursor: pointer;
  flex-shrink: 0;
}

.read-price-foot-note {
  font-size: 12px;
  color: #94a3b8;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.read-price-confirm-btn {
  padding: 11px 32px !important;
  border-radius: 8px !important;
  font-size: 14.5px !important;
  font-weight: 700 !important;
  color: #ffffff !important;
  background: linear-gradient(135deg, #10b981, #059669) !important;
  border: none !important;
  box-shadow: 0 4px 15px rgba(16, 185, 129, 0.3) !important;
  cursor: pointer !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: auto !important;
  margin: 0 !important;
  transition: all 0.2s ease !important;
}

.read-price-confirm-btn:hover {
  box-shadow: 0 6px 20px rgba(16, 185, 129, 0.45) !important;
  transform: translateY(-1px);
}

/* Light Mode overrides for Fullscreen Read Price Modal */
