/* Inline Picker Button inside Input (replaces native datalist dropdown arrow) */
.input-with-picker {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
}

.inline-picker-btn {
  position: absolute !important;
  right: 6px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  padding: 5px 10px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.3px !important;
  background: rgba(2, 132, 199, 0.22) !important;
  color: #38bdf8 !important;
  border: 1px solid rgba(56, 189, 248, 0.45) !important;
  cursor: pointer !important;
  width: fit-content !important;
  height: auto !important;
  margin: 0 !important;
  line-height: 1.1 !important;
  z-index: 3 !important;
  transition: all 0.15s ease !important;
}

.inline-picker-btn:hover {
  background: #0284c7 !important;
  color: #ffffff !important;
  border-color: #0284c7 !important;
}

.inline-picker-btn.inline-picker-btn-sm {
  right: 4px !important;
  padding: 3px 7px !important;
  font-size: 10px !important;
  border-radius: 5px !important;
}

.page.theme-light-blue .inline-picker-btn {
  background: #e0f2fe !important;
  color: #0369a1 !important;
  border: 1px solid #7dd3fc !important;
}

.page.theme-light-blue .inline-picker-btn:hover {
  background: #0284c7 !important;
  color: #ffffff !important;
  border-color: #0284c7 !important;
}

/* Picker Modals (Customer & Product) */
