}

.page.theme-light-blue .import-meta-pill {
  background: #f1f5f9 !important;
  border-color: #cbd5e1 !important;
  color: #334155 !important;
}

.page.theme-light-blue .import-features-toggle-btn {
  background: #e0f2fe !important;
  color: #0369a1 !important;
  border-color: #7dd3fc !important;
}

.page.theme-light-blue .import-features-expanded {
  background: #f8fafc !important;
  border-color: #cbd5e1 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .import-matched-prod-box {
  background: #f0f9ff !important;
  color: #0f172a !important;
}

.page.theme-light-blue .import-candidate-trigger-btn {
  background: #f8fafc !important;
  color: #0f172a !important;
  border: 1px solid #cbd5e1 !important;
}

.page.theme-light-blue .import-related-dropdown {
  background: #ffffff !important;
  border: 1px solid #93c5fd !important;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.18) !important;
}

.page.theme-light-blue .import-candidate-option {
  background: #f8fafc !important;
  border-color: #e2e8f0 !important;
  color: #0f172a !important;
}

.page.theme-light-blue .import-candidate-option:hover {
  background: #f0f9ff !important;
}

.page.theme-light-blue .import-candidate-option.selected {
