  border-color: #3b82f6 !important;
}

/* ==============================================================
   MODAL: THAO TÁC & TIỆN ÍCH BÁO GIÁ (PHƯƠNG ÁN 2: BỐ CỤC 2 CỘT)
============================================================== */
.modal-card.more-actions-modal {
  width: 880px !important;
  max-width: 95vw !important;
}

.more-actions-head {
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%) !important;
  padding: 15px 24px !important;
  border-bottom: 1px solid rgba(56, 189, 248, 0.2) !important;
}

.more-actions-body.more-actions-split-layout {
  padding: 22px 26px;
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 24px;
  align-items: stretch;
  max-height: calc(90vh - 130px);
  overflow-y: auto;
}

.more-actions-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 24px !important;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
}

.ma-col-left {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 12px;
  padding: 14px 16px;
}

.ma-col-right {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 14px;
}

.ma-tool-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ma-section-title {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #94a3b8;
  display: flex;
  align-items: center;
  gap: 8px;
}

.ma-section-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(148, 163, 184, 0.16);
}

.ma-note-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.ma-field-label {
  font-size: 11px;
  font-weight: 700;
  color: #e2e8f0;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin: 0;
}

.ma-textarea {
  width: 100%;
  flex: 1;
  min-height: 105px;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 12.5px;
  font-family: inherit;
  line-height: 1.45;
  resize: vertical;
  background: rgba(0, 0, 0, 0.28);
  color: #f8fafc;
  margin: 0;
  box-sizing: border-box;
}

.ma-tool-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.ma-tool-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ma-tool-btn {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 10px;
  width: 100% !important;
  margin: 0 !important;
  padding: 10px 12px !important;
  border-radius: 10px !important;
  background: rgba(30, 41, 59, 0.72) !important;
  border: 1px solid rgba(148, 163, 184, 0.18) !important;
  color: #f8fafc !important;
  text-align: left !important;
  cursor: pointer;
  transition: all 0.18s ease;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.16) !important;
}

.ma-tool-btn:hover {
  background: rgba(30, 41, 59, 0.98) !important;
  border-color: rgba(56, 189, 248, 0.45) !important;
  transform: translateY(-1px);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.26) !important;
}

.ma-tool-btn.ma-span-full {
  grid-column: 1 / -1;
}

.ma-tool-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 15px;
}

.ma-tool-icon svg {
  width: 18px !important;
  height: 18px !important;
  display: block !important;
  flex-shrink: 0;
  stroke: currentColor;
}

.ma-tool-icon.accent-amber {
  background: rgba(245, 158, 11, 0.16);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.32);
}

.ma-tool-icon.accent-emerald {
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.32);
}

.ma-tool-icon.accent-sky {
  background: rgba(14, 165, 233, 0.16);
  color: #38bdf8;
  border: 1px solid rgba(14, 165, 233, 0.32);
}

.ma-tool-icon.accent-orange {
  background: rgba(249, 115, 22, 0.16);
  color: #fb923c;
  border: 1px solid rgba(249, 115, 22, 0.32);
}

.ma-tool-icon.accent-blue {
  background: rgba(59, 130, 246, 0.16);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.32);
}

.ma-tool-icon.accent-purple {
  background: rgba(168, 85, 247, 0.16);
  color: #c084fc;
  border: 1px solid rgba(168, 85, 247, 0.32);
}

.ma-tool-icon.accent-teal {
  background: rgba(20, 184, 166, 0.16);
  color: #2dd4bf;
  border: 1px solid rgba(20, 184, 166, 0.32);
}

.ma-tool-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.ma-tool-label {
  font-size: 12.5px;
  font-weight: 700;
  color: #f8fafc;
  line-height: 1.25;
}

.ma-tool-sub {
  font-size: 11px;
  font-weight: 400;
  color: #94a3b8;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Light Mode overrides cho Bố cục 2 Cột */
.page.theme-light-blue .more-actions-footer {
  background: #ffffff !important;
  border-top: 1px solid #e2e8f0 !important;
}

.page.theme-light-blue .ma-col-left {
  background: #f1f5f9 !important;
  border-color: #cbd5e1 !important;
}

.page.theme-light-blue .ma-section-title {
  color: #334155 !important;
}

.page.theme-light-blue .ma-section-title::after {
  background: #cbd5e1 !important;
}

.page.theme-light-blue .ma-field-label {
  color: #1e293b !important;
}

.page.theme-light-blue .ma-tool-btn {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  color: #0f172a !important;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05) !important;
}

.page.theme-light-blue .ma-tool-btn:hover {
  background: #f0f9ff !important;
  border-color: #3b82f6 !important;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.12) !important;
}

.page.theme-light-blue .ma-tool-label {
  color: #0f172a !important;
}

.page.theme-light-blue .ma-tool-sub {
  color: #64748b !important;
}

.page.theme-light-blue .ma-tool-icon.accent-amber {
  background: #fef3c7 !important;
  color: #d97706 !important;
  border-color: #fcd34d !important;
}

.page.theme-light-blue .ma-tool-icon.accent-emerald {
  background: #d1fae5 !important;
  color: #059669 !important;
  border-color: #6ee7b7 !important;
}

.page.theme-light-blue .ma-tool-icon.accent-sky {
  background: #e0f2fe !important;
  color: #0284c7 !important;
  border-color: #7dd3fc !important;
}

.page.theme-light-blue .ma-tool-icon.accent-orange {
  background: #ffedd5 !important;
  color: #ea580c !important;
  border-color: #fdba74 !important;
}

.page.theme-light-blue .ma-tool-icon.accent-blue {
  background: #dbeafe !important;
  color: #2563eb !important;
  border-color: #93c5fd !important;
}

.page.theme-light-blue .ma-tool-icon.accent-purple {
  background: #f3e8ff !important;
  color: #7e22ce !important;
  border-color: #d8b4fe !important;
}

.page.theme-light-blue .ma-tool-icon.accent-teal {
  background: #ccfbf1 !important;
  color: #0d9488 !important;
  border-color: #5eead4 !important;
}

@media (max-width: 720px) {
  .more-actions-body.more-actions-split-layout {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 1024px) {
  .import-confirm-workspace {
    grid-template-columns: 1fr !important;
    overflow-y: auto !important;
  }
  .export-preview-split-workspace {
    grid-template-columns: 1fr !important;
    gap: 16px !important;
  }
  .preview-split-resizer {
    display: none !important;
  }
}

/* =====================================================================
   XEM TRƯỚC BẢN IN THEO ĐỊNH DẠNG FILE & CHỈNH SỬA + KÉO RỘNG/CAO TRỰC TIẾP
   ===================================================================== */

/* Cách ly hoàn toàn bảng báo giá trong khung giấy in khỏi CSS global (min-width: 1200px, td padding/color) */
.print-preview-sheet,
.print-preview-sheet .nts-print-sheet {
  box-sizing: border-box !important;
  color: #0f172a;
}

.print-preview-sheet table.nts-grid-table {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  table-layout: fixed !important;
  border-collapse: collapse !important;
  margin: 0 !important;
}

.print-preview-sheet table.nts-grid-table td,
.print-preview-sheet table.nts-grid-table th {
  box-sizing: border-box !important;
}

/* Cách ly các nút, ô nhập, nhãn trên thanh công cụ Preview khỏi CSS global button/input/label & media query */
.preview-live-panel,
.preview-zoom-toolbar-strip {
  min-width: 0;
  box-sizing: border-box;
}

.preview-zoom-toolbar-strip {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 18px;
  background: #0f172a;
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
  flex-shrink: 0;
}

/* Thanh chia 2 cột Cấu hình (Trái) & Xem trước (Phải) */
.preview-split-resizer {
  width: 12px;
  cursor: col-resize;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  transition: background 0.15s ease;
  border-radius: 6px;
  margin: 0;
}

.preview-split-resizer:hover,
.preview-split-resizer.is-dragging {
  background: rgba(56, 189, 248, 0.16);
}

.preview-split-resizer-grip {
  width: 4px;
  height: 54px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.45);
  transition: all 0.15s ease;
}

.preview-split-resizer:hover .preview-split-resizer-grip,
.preview-split-resizer.is-dragging .preview-split-resizer-grip {
  height: 84px;
  background: #0ea5e9;
  box-shadow: 0 0 8px rgba(14, 165, 233, 0.55);
}

/* Thanh gộp Topbar: Tab định dạng (Trái) + Nút công cụ (Phải) */
.pv-topbar-unified {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 8px !important;
  flex-wrap: wrap !important;
  background: rgba(15, 23, 42, 0.72);
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 8px;
  padding: 6px 8px;
  flex-shrink: 0;
}

.pv-format-tabs-list {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 5px !important;
  flex-wrap: wrap !important;
}

.pv-topbar-actions {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 5px !important;
  flex-wrap: wrap !important;
  margin-left: auto;
}

.pv-format-tab-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  padding: 4px 9px !important;
  min-height: 26px !important;
  height: 26px !important;
  border-radius: 6px !important;
  border: 1px solid rgba(148, 163, 184, 0.25) !important;
  background: rgba(30, 41, 59, 0.78) !important;
  color: #cbd5e1 !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  cursor: pointer !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  box-shadow: none !important;
  transition: all 0.15s ease;
}

.pv-format-tab-btn:hover {
  border-color: rgba(56, 189, 248, 0.55) !important;
  color: #ffffff !important;
  transform: none !important;
}

.pv-format-tab-btn .pv-fmt-ext {
  font-size: 9.5px;
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.1);
  color: #94a3b8;
}

.pv-format-tab-btn.active.fmt-pdf {
  background: linear-gradient(135deg, #0284c7, #0ea5e9) !important;
  border-color: #7dd3fc !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(14, 165, 233, 0.32) !important;
}

.pv-format-tab-btn.active.fmt-excel {
  background: linear-gradient(135deg, #059669, #10b981) !important;
  border-color: #6ee7b7 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(16, 185, 129, 0.32) !important;
}

.pv-format-tab-btn.active.fmt-word {
  background: linear-gradient(135deg, #1d4ed8, #2563eb) !important;
  border-color: #93c5fd !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.32) !important;
}

.pv-format-tab-btn.active.fmt-png {
  background: linear-gradient(135deg, #d97706, #f59e0b) !important;
  border-color: #fde68a !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(245, 158, 11, 0.32) !important;
}

.pv-format-tab-btn.active.fmt-html {
  background: linear-gradient(135deg, #6d28d9, #8b5cf6) !important;
  border-color: #ddd6fe !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(139, 92, 246, 0.32) !important;
}

.pv-format-tab-btn.active .pv-fmt-ext {
  background: rgba(0, 0, 0, 0.22);
  color: #ffffff;
}

.pv-mode-toggle-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  padding: 4px 10px !important;
  min-height: 26px !important;
  height: 26px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  cursor: pointer !important;
  border: 1px solid rgba(148, 163, 184, 0.35) !important;
  background: rgba(15, 23, 42, 0.65) !important;
  color: #cbd5e1 !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  box-shadow: none !important;
  transition: all 0.15s ease;
}

.pv-mode-toggle-btn.active {
  background: linear-gradient(135deg, #059669, #10b981) !important;
  border-color: #34d399 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 6px rgba(16, 185, 129, 0.3) !important;
}

.pv-reset-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 4px !important;
  padding: 4px 9px !important;
  min-height: 26px !important;
  height: 26px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  cursor: pointer !important;
  border: 1px solid rgba(244, 63, 94, 0.45) !important;
  background: rgba(244, 63, 94, 0.16) !important;
  color: #fda4af !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  box-shadow: none !important;
}

.pv-reset-btn:hover {
  background: #e11d48 !important;
  color: #ffffff !important;
}

.pv-zoom-open-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 5px !important;
  padding: 4px 10px !important;
  min-height: 26px !important;
  height: 26px !important;
  border-radius: 6px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  cursor: pointer !important;
  border: 1px solid rgba(56, 189, 248, 0.45) !important;
  background: rgba(2, 132, 199, 0.22) !important;
  color: #7dd3fc !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  box-shadow: none !important;
}

.pv-zoom-open-btn:hover {
  background: #0284c7 !important;
  color: #ffffff !important;
}

/* Thanh công cụ định dạng ô & chỉnh Rộng/Cao (WYSIWYG Toolbar) */
.pv-wysiwyg-toolbar {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 6px !important;
  flex-wrap: wrap !important;
  padding: 5px 8px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(56, 189, 248, 0.25);
  flex-shrink: 0;
}

.pv-cell-badge {
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  background: rgba(2, 132, 199, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.35);
  padding: 3px 8px;
  border-radius: 5px;
  min-width: 74px;
  text-align: center;
  white-space: nowrap;
}

.pv-tool-group {
  display: inline-flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 3px !important;
  padding-right: 6px;
  border-right: 1px solid rgba(148, 163, 184, 0.2);
}

.pv-tool-group:last-of-type {
  border-right: none;
  padding-right: 0;
}

.pv-tool-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 3px 7px !important;
  min-height: 24px !important;
  height: 24px !important;
  border-radius: 5px !important;
  border: 1px solid rgba(148, 163, 184, 0.25) !important;
  background: rgba(30, 41, 59, 0.85) !important;
  color: #e2e8f0 !important;
  font-size: 11px !important;
  font-weight: 700 !important;
  cursor: pointer !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  box-shadow: none !important;
  transition: all 0.14s ease;
}

.pv-tool-btn:hover:not(:disabled) {
  background: #0284c7 !important;
  border-color: #38bdf8 !important;
  color: #ffffff !important;
  transform: none !important;
}

.pv-tool-btn:disabled {
  opacity: 0.4 !important;
  cursor: not-allowed !important;
}

.pv-cell-restore-btn {
  border-color: rgba(245, 158, 11, 0.45) !important;
  color: #fcd34d !important;
}

.pv-color-picker-label {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  height: 24px !important;
  font-size: 10.5px !important;
  font-weight: 700 !important;
  color: #cbd5e1 !important;
  cursor: pointer !important;
  margin: 0 !important;
  padding: 0 6px !important;
  border-radius: 5px !important;
  background: rgba(30, 41, 59, 0.85) !important;
  border: 1px solid rgba(148, 163, 184, 0.25) !important;
  text-transform: none !important;
  white-space: nowrap !important;
}

.pv-color-picker-label input[type="color"] {
  width: 16px !important;
  height: 16px !important;
  min-height: 16px !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  cursor: pointer !important;
  margin: 0 !important;
}

.pv-size-inputs-group {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
}

.pv-size-input-label {
  display: inline-flex !important;
  align-items: center !important;
  gap: 3px !important;
  height: 24px !important;
  font-size: 10.5px !important;
  font-weight: 700 !important;
  color: #e2e8f0 !important;
  background: rgba(30, 41, 59, 0.9) !important;
  border: 1px solid rgba(56, 189, 248, 0.32) !important;
  padding: 0 5px !important;
  border-radius: 5px !important;
  margin: 0 !important;
  text-transform: none !important;
  white-space: nowrap !important;
}

.pv-size-input-label.pv-row-height-box {
  border-color: rgba(16, 185, 129, 0.45) !important;
}

.pv-size-step-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 18px !important;
  min-width: 18px !important;
  height: 18px !important;
  min-height: 18px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 3px !important;
  border: 1px solid rgba(148, 163, 184, 0.35) !important;
  background: rgba(15, 23, 42, 0.85) !important;
  color: #e2e8f0 !important;
  font-size: 12px !important;
  font-weight: 800 !important;
  line-height: 1 !important;
  cursor: pointer !important;
  box-shadow: none !important;
}

.pv-size-step-btn:hover {
  background: #0284c7 !important;
  border-color: #38bdf8 !important;
  color: #ffffff !important;
}

.pv-size-number-input {
  width: 44px !important;
  min-height: 18px !important;
  height: 18px !important;
  padding: 1px 4px !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  color: #38bdf8 !important;
  background: rgba(15, 23, 42, 0.9) !important;
  border: 1px solid rgba(148, 163, 184, 0.3) !important;
  border-radius: 3px !important;
  text-align: center !important;
  margin: 0 !important;
}

.pv-size-number-input:disabled {
  opacity: 0.45 !important;
  cursor: not-allowed !important;
}

.pv-unit {
  font-size: 9.5px;
  color: #94a3b8;
  font-weight: 600;
}

/* Thanh công thức fx khi chọn tab Excel (.xlsx) */
.pv-excel-formula-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #f8fafc;
  border: 1px solid #94a3b8;
  border-radius: 7px;
  padding: 4px 8px;
  flex-shrink: 0;
}

.pv-excel-addr-box {
  min-width: 50px;
  text-align: center;
  font-family: Consolas, monospace;
  font-size: 11.5px;
  font-weight: 800;
  color: #0f172a;
  background: #e2e8f0;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 2px 6px;
}

.pv-excel-fx-tag {
  font-family: Georgia, serif;
  font-style: italic;
  font-weight: 800;
  font-size: 13px;
  color: #059669;
  padding: 0 4px;
  user-select: none;
}

.pv-excel-formula-input {
  flex: 1;
  min-height: 24px !important;
  height: 24px !important;
  border: 1px solid #cbd5e1 !important;
  background: #ffffff !important;
  color: #0f172a !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  padding: 2px 8px !important;
  border-radius: 4px !important;
  margin: 0 !important;
  width: auto !important;
}

.pv-excel-formula-chip {
  font-family: Consolas, monospace;
  font-size: 10.5px;
  font-weight: 700;
  color: #047857;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  padding: 2px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

/* KHUNG BAO TỜ GIẤY BẢN IN & THƯỚC CỘT A, B, C... + THƯỚC HÀNG 1, 2, 3... */
.pv-paper-frame {
  box-sizing: border-box;
  transition: width 0.05s linear;
}

.pv-col-ruler-wrap {
  position: relative;
  user-select: none;
  background: #cbd5e1;
  border: 1px solid #94a3b8;
  border-bottom: none;
  border-radius: 6px 6px 0 0;
}

.pv-ruler-corner-box {
  position: absolute;
  top: 0;
  left: 0;
  width: 26px;
  height: 22px;
  background: #cbd5e1;
  border-right: 1px solid #94a3b8;
  border-bottom: 1px solid #94a3b8;
  box-sizing: border-box;
  z-index: 2;
}

.pv-ruler-corner-box::after {
  content: '';
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 0 0 7px 7px;
  border-color: transparent transparent #64748b transparent;
}

.pv-col-header-row {
  display: flex;
  width: 100%;
  height: 22px;
  background: #e2e8f0;
  overflow: hidden;
}

.pv-col-header-cell {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 22px;
  padding: 0;
  font-family: Arial, sans-serif;
  font-size: 10px;
  font-weight: 800;
  color: #334155;
  border-right: 1px solid #cbd5e1;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  overflow: visible;
  box-sizing: border-box;
}

.pv-col-letter {
  display: block;
  overflow: hidden;
  text-overflow: clip;
  white-space: nowrap;
  line-height: 1;
}

.pv-col-header-cell.is-active-col {
  background: linear-gradient(180deg, #bae6fd 0%, #7dd3fc 100%);
  color: #0369a1;
}

.pv-col-resizer {
  position: absolute;
  top: 0;
  right: -3px;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  z-index: 6;
  background: transparent;
  transition: background 0.12s ease;
}

.pv-col-resizer:hover {
  background: #0284c7;
}

/* THƯỚC HÀNG 1, 2, 3... BÊN TRÁI TRANG IN */
.pv-paper-body-row {
  display: flex;
  align-items: stretch;
  width: 100%;
  position: relative;
}

.pv-row-ruler-wrap {
  width: 26px;
  flex-shrink: 0;
  background: #cbd5e1;
  border-left: 1px solid #94a3b8;
  border-right: 1px solid #94a3b8;
  border-bottom: 1px solid #94a3b8;
  border-radius: 0 0 0 6px;
  user-select: none;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.pv-row-header-cell {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  font-family: Arial, sans-serif;
  font-size: 9.5px;
  font-weight: 800;
  color: #334155;
  border-bottom: 1px solid #cbd5e1;
  background: linear-gradient(90deg, #f8fafc 0%, #e2e8f0 100%);
  cursor: pointer;
  box-sizing: border-box;
  flex-shrink: 0;
}

.pv-row-header-cell:hover {
  background: #e0f2fe;
  color: #0284c7;
}

.pv-row-header-cell.is-active-row {
  background: linear-gradient(90deg, #a7f3d0 0%, #6ee7b7 100%);
  color: #065f46;
}

.pv-row-num {
  line-height: 1;
  pointer-events: none;
}

.pv-row-resizer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -3px;
  height: 7px;
  cursor: row-resize;
  z-index: 8;
  background: transparent;
  transition: background 0.12s ease;
}

.pv-row-resizer:hover {
  background: #059669;
}

.print-preview-sheet table.nts-grid-table tr.is-row-resize-hover > td {
  box-shadow: inset 0 -2px 0 #0ea5e9 !important;
}

/* CÁC NÚT XUẤT FILE Ở FOOTER ĐỔI MÀU TƯƠNG ỨNG THEO ĐỊNH DẠNG ĐANG SỬA TRỰC TIẾP */
.pv-export-action-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 10px 16px !important;
  min-height: 38px !important;
  height: auto !important;
  border-radius: 8px !important;
  font-weight: 800 !important;
  font-size: 12.5px !important;
  cursor: pointer !important;
  width: auto !important;
  margin: 0 !important;
  white-space: nowrap !important;
  transition: all 0.18s ease !important;
}

.pv-export-action-btn.fmt-export-excel.is-active-fmt {
  background: linear-gradient(135deg, #10b981, #059669) !important;
  border: 1px solid #34d399 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3) !important;
}

.pv-export-action-btn.fmt-export-word.is-active-fmt {
  background: linear-gradient(135deg, #2563eb, #1d4ed8) !important;
  border: 1px solid #60a5fa !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.3) !important;
}

.pv-export-action-btn.fmt-export-pdf.is-active-fmt {
  background: linear-gradient(135deg, #0ea5e9, #0284c7) !important;
  border: 1px solid #38bdf8 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(14, 165, 233, 0.3) !important;
}

.pv-export-action-btn.fmt-export-png.is-active-fmt {
  background: linear-gradient(135deg, #f59e0b, #d97706) !important;
  border: 1px solid #fbbf24 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(245, 158, 11, 0.3) !important;
}

.pv-export-action-btn.fmt-export-html.is-active-fmt {
  background: linear-gradient(135deg, #8b5cf6, #6d28d9) !important;
  border: 1px solid #a78bfa !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(139, 92, 246, 0.3) !important;
}

/* Khi Sửa trực tiếp BẬT: Nút ứng với định dạng đang sửa nổi bật hẳn lên */
.pv-export-action-btn.is-focused-fmt {
  outline: 2px solid #ffffff !important;
  outline-offset: 2px !important;
  transform: translateY(-1px) !important;
}

.pv-export-action-btn.fmt-export-excel.is-focused-fmt {
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.5) !important;
}

.pv-export-action-btn.fmt-export-word.is-focused-fmt {
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.5) !important;
}

.pv-export-action-btn.fmt-export-pdf.is-focused-fmt {
  box-shadow: 0 4px 14px rgba(14, 165, 233, 0.5) !important;
}

.pv-export-action-btn.fmt-export-png.is-focused-fmt {
  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.5) !important;
}

.pv-export-action-btn.fmt-export-html.is-focused-fmt {
  box-shadow: 0 4px 14px rgba(139, 92, 246, 0.5) !important;
}

/* Khi Sửa trực tiếp BẬT: Các nút xuất của định dạng khác chuyển về màu trung tính chìm */
.pv-export-action-btn.is-dimmed-fmt {
  background: rgba(30, 41, 59, 0.65) !important;
  border: 1px solid rgba(148, 163, 184, 0.25) !important;
  color: #94a3b8 !important;
  box-shadow: none !important;
  outline: none !important;
}

.pv-export-action-btn.is-dimmed-fmt:hover {
  background: rgba(51, 65, 85, 0.9) !important;
  border-color: rgba(148, 163, 184, 0.55) !important;
  color: #f8fafc !important;
}

.page.theme-light-blue .pv-export-action-btn.is-dimmed-fmt {
  background: #e2e8f0 !important;
  border: 1px solid #cbd5e1 !important;
  color: #64748b !important;
}

.page.theme-light-blue .pv-export-action-btn.is-dimmed-fmt:hover {
  background: #cbd5e1 !important;
  border-color: #94a3b8 !important;
  color: #0f172a !important;
}

/* TAY NẮM KÉO RỘNG / KÉO CAO KHUNG TRANG BẢN IN (DỌC CẠNH PHẢI, CẠNH DƯỚI & GÓC DƯỚI PHẢI) */
.pv-paper-edge-right {
  position: absolute;
  top: 22px;
  right: -5px;
  width: 10px;
  bottom: 24px;
  cursor: ew-resize;
  z-index: 10;
  border-radius: 4px;
  background: transparent;
  transition: background 0.15s ease;
}

.pv-paper-edge-right:hover {
  background: rgba(14, 165, 233, 0.45);
}

.pv-paper-edge-bottom {
  margin-top: 6px;
  height: 20px;
  border-radius: 5px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px dashed rgba(56, 189, 248, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: ns-resize;
  user-select: none;
  transition: all 0.15s ease;
}

.pv-paper-edge-bottom:hover {
  background: #0284c7;
  border-style: solid;
}

.pv-edge-bottom-pill {
  font-size: 10.5px;
  font-weight: 700;
  color: #e2e8f0;
  letter-spacing: 0.2px;
}

.pv-paper-corner-grip {
  position: absolute;
  right: -4px;
  bottom: 0;
  width: 20px;
  height: 20px;
  border-radius: 4px;
  background: #10b981;
  border: 1px solid #6ee7b7;
  cursor: nwse-resize;
  z-index: 12;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  transition: transform 0.12s ease, background 0.12s ease;
}

.pv-paper-corner-grip::after {
  content: '';
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 8px;
  height: 8px;
  border-right: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
}

.pv-paper-corner-grip:hover {
  background: #059669;
  transform: scale(1.1);
}

/* THƯỚC WORD & CHROME TRÌNH DUYỆT HTML */
.pv-word-ruler {
  display: flex;
  justify-content: space-between;
  background: #f1f5f9;
  border: 1px solid #94a3b8;
  border-bottom: none;
  padding: 2px 14px;
  font-family: Consolas, monospace;
  font-size: 9.5px;
  color: #64748b;
  user-select: none;
}

.pv-word-ruler-mark {
  position: relative;
}

.pv-html-browser-chrome {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #1e293b;
  border: 1px solid #334155;
  border-bottom: none;
  padding: 5px 12px;
}

.pv-browser-dots {
  display: inline-flex;
  gap: 5px;
}

.pv-browser-dots span {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #475569;
}

.pv-browser-dots span:nth-child(1) { background: #ef4444; }
.pv-browser-dots span:nth-child(2) { background: #f59e0b; }
.pv-browser-dots span:nth-child(3) { background: #10b981; }

.pv-browser-url {
  flex: 1;
  background: #0f172a;
  color: #cbd5e1;
  font-family: Consolas, monospace;
  font-size: 11px;
  padding: 2px 10px;
  border-radius: 4px;
  border: 1px solid #334155;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pv-browser-tag {
  font-size: 10px;
  font-weight: 800;
  color: #c4b5fd;
  background: rgba(139, 92, 246, 0.2);
  border: 1px solid rgba(167, 139, 250, 0.4);
  padding: 2px 8px;
  border-radius: 999px;
}

/* GIAO DIỆN NỀN THEO ĐỊNH DẠNG FILE XEM TRƯỚC */
.pv-viewport-stage.stage-pdf {
  background: #64748b;
}

.pv-viewport-stage.stage-excel {
  background: #a7f3d0;
}

.pv-viewport-stage.stage-word {
  background: #bfdbfe;
}

.pv-viewport-stage.stage-png {
  background-color: #cbd5e1;
  background-image:
    linear-gradient(45deg, #94a3b8 25%, transparent 25%),
    linear-gradient(-45deg, #94a3b8 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #94a3b8 75%),
    linear-gradient(-45deg, transparent 75%, #94a3b8 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
}

.pv-viewport-stage.stage-html {
  background: #334155;
}

/* HIỆU ỨNG TƯƠNG TÁC Ô KHI BẬT CHẾ ĐỘ SỬA TRỰC TIẾP TRÊN BẢN IN */
.print-preview-sheet.fmt-sheet-excel td.preview-interactive-td {
  box-shadow: inset 0 0 0 0.5px rgba(148, 163, 184, 0.38);
}

.print-preview-sheet.is-direct-editable td.preview-interactive-td {
  transition: background-color 0.1s ease, outline 0.1s ease;
}

.print-preview-sheet.is-direct-editable td.preview-interactive-td:hover {
  outline: 1.5px dashed #0284c7 !important;
  outline-offset: -1.5px;
}

.print-preview-sheet td.preview-interactive-td.is-active-preview-cell {
  outline: 2px solid #059669 !important;
  outline-offset: -2px;
  background-color: rgba(16, 185, 129, 0.06);
}

/* LIGHT MODE TƯƠNG THÍCH CHO KHUNG PREVIEW */
.page.theme-light-blue .pv-topbar-unified,
.page.theme-light-blue .pv-wysiwyg-toolbar,
.page.theme-light-blue .preview-zoom-toolbar-strip {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.page.theme-light-blue .pv-format-tab-btn:not(.active),
.page.theme-light-blue .pv-mode-toggle-btn:not(.active),
.page.theme-light-blue .pv-tool-btn,
.page.theme-light-blue .pv-color-picker-label,
.page.theme-light-blue .pv-size-input-label {
  background: #ffffff !important;
  color: #1e293b !important;
  border-color: #cbd5e1 !important;
}

.page.theme-light-blue .pv-size-number-input {
  background: #f8fafc !important;
  color: #0284c7 !important;
  border-color: #cbd5e1 !important;
}

/* ═══════════════════════════════════════════════════════════════════════════
   TỐI ƯU GIAO DIỆN MOBILE CHO 2 MODAL:
   1. CHỌN MẪU IN, KHÁCH HÀNG & XUẤT BÁO GIÁ (.export-multi-format-modal)
   2. PHÓNG TO XEM TRƯỚC & CHỈNH SỬA BẢN IN (.export-zoom-preview-modal)
   ═══════════════════════════════════════════════════════════════════════════ */
@media (max-width: 1100px) {
  /* --- 1. MODAL CHỌN MẪU IN, KHÁCH HÀNG & XUẤT BÁO GIÁ --- */
  .modal .modal-card.export-multi-format-modal,
  .modal .modal-card.export-zoom-preview-modal {
    padding: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    width: 100vw !important;
    max-width: 100vw !important;
    height: 100% !important;
    max-height: 100% !important;
    border-radius: 0 !important;
    overflow: hidden !important;
  }

  .export-multi-format-modal .export-multi-head {
    padding: 10px 42px 10px 12px !important;
    justify-content: flex-start !important;
    flex-shrink: 0 !important;
  }

  .export-multi-format-modal .export-multi-head-title {
    font-size: 13px !important;
    line-height: 1.3 !important;
    text-align: left !important;
  }

  .export-multi-format-modal .export-multi-head-title .dt-lbl,
  .export-multi-format-modal .export-multi-dt-btns,
  .export-zoom-preview-modal .export-zoom-title-wrap .dt-lbl,
  .export-multi-format-modal .pv-mode-toggle-btn .dt-lbl,
  .export-zoom-preview-modal .pv-mode-toggle-btn .dt-lbl,
  .export-zoom-preview-modal .pv-reset-btn .dt-lbl {
    display: none !important;
  }

  .export-multi-format-modal .export-multi-head-title .mb-lbl,
  .export-zoom-preview-modal .export-zoom-title-wrap .mb-lbl,
  .export-multi-format-modal .pv-mode-toggle-btn .mb-lbl,
  .export-zoom-preview-modal .pv-mode-toggle-btn .mb-lbl,
  .export-zoom-preview-modal .pv-reset-btn .mb-lbl {
    display: inline !important;
  }

  /* Thanh Chọn Mẫu In + Segmented 2-Tab trên đầu Modal */
  .export-multi-format-modal .export-multi-top-toolbar {
    padding: 8px 12px !important;
    gap: 7px !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    flex-shrink: 0 !important;
  }

  .export-multi-format-modal .export-multi-tpl-left {
    min-width: 0 !important;
    width: 100% !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 5px !important;
  }

  .export-multi-format-modal .export-multi-tpl-head-row {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    gap: 8px !important;
  }

  .export-multi-format-modal .export-multi-tpl-label {
    font-size: 11px !important;
  }

  .export-multi-format-modal .export-multi-setup-mobile-btn {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: auto !important;
    min-width: max-content !important;
    height: 26px !important;
    min-height: 26px !important;
    padding: 0 9px !important;
    margin: 0 !important;
    border-radius: 6px !important;
    background: linear-gradient(135deg, #2563eb, #1d4ed8) !important;
    color: #ffffff !important;
    border: none !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    box-shadow: none !important;
  }

  .export-multi-format-modal .export-multi-tpl-select {
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    height: 36px !important;
    min-height: 36px !important;
    padding: 0 10px !important;
    font-size: 12.5px !important;
    border-radius: 8px !important;
  }

  .export-multi-format-modal .export-multi-filename-note {
    font-size: 11px !important;
    line-height: 1.3 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    display: block !important;
