/* =========================================================================
   MOBILE REDESIGN: DONG BO CARD SAN PHAM CHO CA 1 COT & 2 COT (<= 1100PX)
   ========================================================================= */
.m-sq-title-wrap {
  display: contents;
}

.card-selected-badge .badge-lbl-short,
.m-sq-selected-pill,
.m-sq-dvt-row,
.m-sq-base-orig-row,
.m-sq-active-pl-top,
.m-price-lhs-wrap,
.m-inline-pl-colon-lbl,
